INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2ae5464-7458-4a82-bb87-7fee9dc2cda8', '舞曲歌辭 霓裳辭十首 三', '舞曲歌辞 霓裳辞十首 三', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["自直梨園得出稀，更番上曲不教歸。","一時跪拜霓裳徹，立地階前賜紫衣。"]', '["自直梨园得出稀，更番上曲不教归。","一时跪拜霓裳徹，立地階前賜紫衣。"]', '诗', 'shi', '', NULL, '舞曲歌辭 霓裳辭十首 三 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d4046a1-74fa-49c7-99ff-b974cd2a31de', '舞曲歌辭 霓裳辭十首 四', '舞曲歌辞 霓裳辞十首 四', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["旋翻新譜聲初足，除却梨園未教人。","宣與書家分手寫，中官走馬賜功臣。"]', '["旋翻新譜声初足，除却梨园未教人。","宣與书家分手寫，中官走马賜功臣。"]', '诗', 'shi', '', NULL, '舞曲歌辭 霓裳辭十首 四 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbd26b62-f2ad-4a69-94f5-7ec705622671', '舞曲歌辭 霓裳辭十首 五', '舞曲歌辞 霓裳辞十首 五', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["伴教霓裳有貴妃，從初直到曲成時。","日長耳裏聞聲熟，拍數分毫錯總知。"]', '["伴教霓裳有貴妃，從初直到曲成时。","日长耳裏闻声熟，拍數分毫錯總知。"]', '诗', 'shi', '', NULL, '舞曲歌辭 霓裳辭十首 五 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a28ac61-d628-4b69-8c3e-5dfa084bcaae', '舞曲歌辭 霓裳辭十首 六', '舞曲歌辞 霓裳辞十首 六', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["弦索摐摐隔綵雲，五更初發一山聞。","武皇自送西王母，新換霓裳月色裙。"]', '["弦索摐摐隔綵云，五更初發一山闻。","武皇自送西王母，新換霓裳月色裙。"]', '诗', 'shi', '', NULL, '舞曲歌辭 霓裳辭十首 六 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c1186ac-7c80-41c5-82ec-44fb797e183d', '舞曲歌辭 霓裳辭十首 七', '舞曲歌辞 霓裳辞十首 七', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["敕賜宮人澡浴回，遙看美女院門開。","一山星月霓裳動，好字先從殿裏來。"]', '["敕賜宮人澡浴回，遙看美女院门开。","一山星月霓裳动，好字先從殿裏来。"]', '诗', 'shi', '', NULL, '舞曲歌辭 霓裳辭十首 七 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d12fb3f-a2a0-4278-8a1c-2641995a3f83', '舞曲歌辭 霓裳辭十首 八', '舞曲歌辞 霓裳辞十首 八', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["傳呼法部按霓裳，新得承恩別作行。","應是貴妃樓上看，內人舁下綵羅箱。"]', '["傳呼法部按霓裳，新得承恩別作行。","應是貴妃楼上看，內人舁下綵羅箱。"]', '诗', 'shi', '', NULL, '舞曲歌辭 霓裳辭十首 八 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d02a1d6-015c-4057-b9b6-b9460d5471dd', '舞曲歌辭 霓裳辭十首 九', '舞曲歌辞 霓裳辞十首 九', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["朝元閣上山風起，夜聽霓裳玉露寒。","宮女月中更替立，黃金梯滑竝行難。"]', '["朝元閣上山风起，夜听霓裳玉露寒。","宮女月中更替立，黄金梯滑竝行难。"]', '诗', 'shi', '', NULL, '舞曲歌辭 霓裳辭十首 九 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('485cbcc6-790e-4089-8fba-8e49957ff3d8', '舞曲歌辭 霓裳辭十首 十', '舞曲歌辞 霓裳辞十首 十', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["知向華清年月滿，山頭山底種長生。","去時留下霓裳曲，總是離宮別館聲。"]', '["知向华清年月满，山头山底種长生。","去时留下霓裳曲，總是離宮別館声。"]', '诗', 'shi', '', NULL, '舞曲歌辭 霓裳辭十首 十 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4abce9fd-b9d9-4b3d-b30c-6f9203b04790', '舞曲歌辭 柘枝詞', '舞曲歌辞 柘枝词', '479d822c-b9fc-4b0f-8a4c-f539161d8eda', '唐', '["將軍奉命即須行，塞外領彊兵。","聞道烽煙動，腰間寶劒匣中鳴。"]', '["將軍奉命即須行，塞外領彊兵。","闻道烽煙动，腰间寶劒匣中鳴。"]', '诗', 'shi', '', NULL, '舞曲歌辭 柘枝詞 失撰人名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f5de9fa-8f26-40e7-ab08-f1dad186aa93', '舞曲歌辭 柘枝詞 一', '舞曲歌辞 柘枝词 一', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["同營三十萬，震鼓伐西羌。","戰血黏秋草，征塵攪夕陽。","歸來人不識，帝里獨戎裝。"]', '["同營三十万，震鼓伐西羌。","戰血黏秋草，征塵攪夕陽。","归来人不識，帝里独戎裝。"]', '诗', 'shi', '', NULL, '舞曲歌辭 柘枝詞 一 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('622f7ce8-2658-47bf-8d4f-a501009f4754', '舞曲歌辭 柘枝詞 二', '舞曲歌辞 柘枝词 二', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["懸軍征拓羯，內地隔蕭關。","日色崑崙上，風聲朔漠間。","何當千萬騎，颯颯貳師還。"]', '["懸軍征拓羯，內地隔蕭关。","日色崑崙上，风声朔漠间。","何當千万騎，颯颯貳師還。"]', '诗', 'shi', '', NULL, '舞曲歌辭 柘枝詞 二 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d722410-b3ba-4272-a9ae-ccd584cde3df', '舞曲歌辭 柘枝詞 三', '舞曲歌辞 柘枝词 三', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["意氣成功日，春風起絮天。","樓臺新邸第，歌舞小嬋娟。","急破催搖曳，羅衫半脫肩。"]', '["意氣成功日，春风起絮天。","楼台新邸第，歌舞小嬋娟。","急破催搖曳，羅衫半脫肩。"]', '诗', 'shi', '', NULL, '舞曲歌辭 柘枝詞 三 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99fc9acc-fbe7-4ecf-a3f3-5b9426ed68eb', '舞曲歌辭 屈柘詞', '舞曲歌辞 屈柘词', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["楊柳縈橋綠，玫瑰拂地紅。","繡衫金騕褭，花髻玉瓏璁。","宿雨香潛潤，春流水暗通。","畫樓初夢斷，晴日照湘風。"]', '["楊柳縈橋綠，玫瑰拂地紅。","繡衫金騕褭，花髻玉瓏璁。","宿雨香潛潤，春流水暗通。","畫楼初梦斷，晴日照湘风。"]', '诗', 'shi', '', NULL, '舞曲歌辭 屈柘詞 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82821220-44e6-465e-ae73-68f04886604a', '琴曲歌辭 白雪歌', '琴曲歌辞 白雪歌', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["列鼎佩金章，淚眼看風枝。","却思食藜藿，身作屠沽兒。","負米無遠近，所希升斗歸。","爲人無貴賤，莫學雞狗肥。","斯言如不忘，別更無光輝。","斯言如或忘，即安用人爲。"]', '["列鼎佩金章，泪眼看风枝。","却思食藜藿，身作屠沽兒。","負米無远近，所希升斗归。","爲人無貴賤，莫学雞狗肥。","斯言如不忘，別更無光輝。","斯言如或忘，即安用人爲。"]', '诗', 'shi', '', NULL, '琴曲歌辭 白雪歌 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5b74274-de21-482b-ae7a-b0d8200bbb18', '琴曲歌辭 湘妃', '琴曲歌辞 湘妃', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["帝子不可見，秋風來暮思。","嬋娟湘江月，千載空蛾眉。"]', '["帝子不可见，秋风来暮思。","嬋娟湘江月，千載空蛾眉。"]', '诗', 'shi', '', NULL, '琴曲歌辭 湘妃 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f489fa6f-b73b-422e-848c-b894d73d1653', '琴曲歌辭 湘妃', '琴曲歌辞 湘妃', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["筠竹千年老不死，長伴秦娥蓋湘水。","蠻娘吟弄滿寒空，九山靜綠淚花紅。","離鸞別鳳煙梧中，巫雲蜀雨遙相通。","幽愁秋氣上青楓，涼夜波間吟古龍。"]', '["筠竹千年老不死，长伴秦娥蓋湘水。","蠻娘吟弄满寒空，九山静綠泪花紅。","離鸾別鳳煙梧中，巫云蜀雨遙相通。","幽愁秋氣上青楓，涼夜波间吟古龙。"]', '诗', 'shi', '', NULL, '琴曲歌辭 湘妃 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfe41fd5-0f8c-4a52-9ce5-8622202264ff', '琴曲歌辭 湘妃怨', '琴曲歌辞 湘妃怨', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["南巡竟不返，帝子怨逾積。","萬里喪蛾眉，瀟湘水空碧。","冥冥荒山下，古廟收貞魄。","喬木深青春，清光滿瑤席。","搴芳徒有薦，靈意殊脈脈。","玉佩不可親，裴回煙波夕。"]', '["南巡竟不返，帝子怨逾積。","万里喪蛾眉，瀟湘水空碧。","冥冥荒山下，古廟收貞魄。","喬木深青春，清光满瑤席。","搴芳徒有薦，靈意殊脈脈。","玉佩不可親，裴回煙波夕。"]', '诗', 'shi', '', NULL, '琴曲歌辭 湘妃怨 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6b7bd03-dfa1-4f65-886f-37c09bd9305f', '琴曲歌辭 湘妃怨', '琴曲歌辞 湘妃怨', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["二妃怨處雲沈沈，二妃哭處湘水深。","商人酒滴廟前草，蕭颯風生斑竹林。"]', '["二妃怨处云沈沈，二妃哭处湘水深。","商人酒滴廟前草，蕭颯风生斑竹林。"]', '诗', 'shi', '', NULL, '琴曲歌辭 湘妃怨 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb5b6b57-47da-4cde-aa13-9a28bebc7fc4', '琴曲歌辭 湘妃列女操', '琴曲歌辞 湘妃列女操', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["有虞夫人哭虞後，淑女何事又傷離。","竹上淚跡生不盡，寄哀雲和五十絲。","雲和經奏鈞天曲，乍聽寶琴遙嗣續。","三湘測測流急綠，秋夜露寒蜀帝飛。","楓林月斜楚臣宿，更疑川宮日黃昏。","闇攜女手殷勤言，環佩玲瓏有無間。","終疑既遠雙悄悄，蒼梧舊雲豈難召。","老猨心寒不可嘯，目眄眄兮意蹉跎。"]', '["有虞夫人哭虞後，淑女何事又傷離。","竹上泪跡生不尽，寄哀云和五十絲。","云和經奏鈞天曲，乍听寶琴遙嗣續。","三湘測測流急綠，秋夜露寒蜀帝飞。","楓林月斜楚臣宿，更疑川宮日黄昏。","闇携女手殷勤言，环佩玲瓏有無间。","終疑既远雙悄悄，蒼梧旧云豈难召。","老猨心寒不可嘯，目眄眄兮意蹉跎。"]', '诗', 'shi', '', NULL, '琴曲歌辭 湘妃列女操 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17a6046a-8569-4e63-a8a3-4f34e3d6a18e', '琴曲歌辭 湘夫人', '琴曲歌辞 湘夫人', '5a515500-5a3d-4d73-a4ef-a41eaa5bd467', '唐', '["楓葉下秋渚，二妃愁渡湘。","疑山空杳藹，何處望君王？","日落水雲裏，油油心自傷。"]', '["楓葉下秋渚，二妃愁渡湘。","疑山空杳藹，何处望君王？","日落水云裏，油油心自傷。"]', '诗', 'shi', '', NULL, '琴曲歌辭 湘夫人 鄒紹先 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12b601e6-d430-4602-9468-6f711b10be39', '琴曲歌辭 湘夫人', '琴曲歌辞 湘夫人', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["九嶷日已暮，三湘雲復愁。","窅藹羅袂色，潺湲江水流。","佳期來北渚，捐玦在芳洲。"]', '["九嶷日已暮，三湘云复愁。","窅藹羅袂色，潺湲江水流。","佳期来北渚，捐玦在芳洲。"]', '诗', 'shi', '', NULL, '琴曲歌辭 湘夫人 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01cc3e31-e2e4-4598-915f-36e8dbbe7c95', '琴曲歌辭 湘夫人', '琴曲歌辞 湘夫人', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["娥眉對湘水，遙哭蒼梧間。","萬乘既已歿，孤舟誰忍還。","至今楚山上，猶有淚痕斑。","南有涔陽路，渺渺多新愁。","昔神降回時，風波江上秋。","彩雲忽無處，碧水空安流。"]', '["娥眉对湘水，遙哭蒼梧间。","万乘既已歿，孤舟誰忍還。","至今楚山上，猶有泪痕斑。","南有涔陽路，渺渺多新愁。","昔神降回时，风波江上秋。","彩云忽無处，碧水空安流。"]', '诗', 'shi', '', NULL, '琴曲歌辭 湘夫人 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('258c6029-d04c-435f-9bb6-b4dadc2d7aea', '琴曲歌辭 霹靂引', '琴曲歌辞 霹靂引', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["歲七月，火伏而金生。","客有鼓瑟於門者，奏霹靂之商聲。","始戛羽以騞砉，終扣宮而砰駖。","電耀耀兮龍躍，雷闐闐兮雨冥。","氣嗚唅以會雅，態歘翕以橫生。","有如驅千旗，制五兵，截荒虺，斮長鯨。","孰與廣陵比，意別鶴儔精而已。","俾我雄子魄動，毅夫髮立，懷恩不淺，武義雙輯，視胡若芥，翦羯如拾。","豈徒慨慷中筵，備羣娛之翕習哉。"]', '["歲七月，火伏而金生。","客有鼓瑟於门者，奏霹靂之商声。","始戛羽以騞砉，終扣宮而砰駖。","電耀耀兮龙躍，雷闐闐兮雨冥。","氣嗚唅以會雅，態歘翕以橫生。","有如驱千旗，制五兵，截荒虺，斮长鯨。","孰與廣陵比，意別鹤儔精而已。","俾我雄子魄动，毅夫髮立，懷恩不淺，武義雙輯，視胡若芥，翦羯如拾。","豈徒慨慷中筵，備羣娛之翕習哉。"]', '诗', 'shi', '', NULL, '琴曲歌辭 霹靂引 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86be8315-dc90-4cd4-a3fa-a5c44bfa3535', '琴曲歌辭 拘幽操', '琴曲歌辞 拘幽操', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["目揜揜兮其凝其盲，耳肅肅兮聽不聞聲。","朝不日出兮夜不見月與星，有知無知兮爲死爲生。","嗚呼！臣罪當誅兮天王聖明。"]', '["目揜揜兮其凝其盲，耳肅肅兮听不闻声。","朝不日出兮夜不见月與星，有知無知兮爲死爲生。","嗚呼！臣罪當誅兮天王聖明。"]', '诗', 'shi', '', NULL, '琴曲歌辭 拘幽操 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de20d7c4-b4d0-439a-a765-bd5f796f04e3', '琴曲歌辭 越裳操', '琴曲歌辞 越裳操', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["雨之施，物以孳，我何意於彼爲。","自周之先，其艱其勤。","以有疆宇，私我後人。","我祖在上，四方在下。","厥臨孔威，敢戲以侮。","孰荒於門，孰治於田。","四海既均，越裳是臣。"]', '["雨之施，物以孳，我何意於彼爲。","自周之先，其艱其勤。","以有疆宇，私我後人。","我祖在上，四方在下。","厥臨孔威，敢戲以侮。","孰荒於门，孰治於田。","四海既均，越裳是臣。"]', '诗', 'shi', '', NULL, '琴曲歌辭 越裳操 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6066fefa-2f60-42ef-a7cd-247f3ca068c7', '琴曲歌辭', '琴曲歌辞', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["我家于豳，自我先公。","伊我承緒，敢有不同。","今狄之人，將土我疆。","民爲我戰，誰使死傷。","彼岐有岨，我往獨處。","人莫余追，無思我悲。"]', '["我家于豳，自我先公。","伊我承緒，敢有不同。","今狄之人，將土我疆。","民爲我戰，誰使死傷。","彼岐有岨，我往独处。","人莫余追，無思我悲。"]', '诗', 'shi', '', NULL, '琴曲歌辭 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ce57b19-4e05-403d-9be2-f3670edbf7fa', '琴曲歌辭 履霜操', '琴曲歌辞 履霜操', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["父兮兒寒，母兮兒飢。","兒罪當笞，逐兒何爲？","兒在中野，以宿以處。","四無人聲，誰與兒語。","兒寒何衣，兒飢何食。","兒行于野，履霜以足。","母生衆兒，有母憐之。","獨無母憐，兒寧不悲。"]', '["父兮兒寒，母兮兒飢。","兒罪當笞，逐兒何爲？","兒在中野，以宿以处。","四無人声，誰與兒語。","兒寒何衣，兒飢何食。","兒行于野，履霜以足。","母生衆兒，有母怜之。","独無母怜，兒寧不悲。"]', '诗', 'shi', '', NULL, '琴曲歌辭 履霜操 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9079e16c-a6d4-4106-aef4-c003da92c773', '琴曲歌辭 雉朝飛操', '琴曲歌辞 雉朝飞操', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["麥隴青青三月時，白雉朝飛挾兩雌。","錦衣綺翼何離褷，犢牧采薪感之悲。","春天和，白日暖，啄食飲泉勇氣滿。","爭雄鬬死繡頸斷，雉子班奏急管弦，心傾美酒盡玉椀。","枯楊枯楊爾生荑，我獨七十而孤棲。","彈弦寫恨意不盡，瞑目歸黃泥。"]', '["麦隴青青三月时，白雉朝飞挾兩雌。","錦衣綺翼何離褷，犢牧采薪感之悲。","春天和，白日暖，啄食饮泉勇氣满。","爭雄鬬死繡頸斷，雉子班奏急管弦，心傾美酒尽玉椀。","枯楊枯楊爾生荑，我独七十而孤棲。","彈弦寫恨意不尽，瞑目归黄泥。"]', '诗', 'shi', '', NULL, '琴曲歌辭 雉朝飛操 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('138a3527-5f85-4380-8619-c44082b33c0e', '琴曲歌辭 雉朝飛操', '琴曲歌辞 雉朝飞操', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["雉之飛，于朝日。","羣雌孤雄，意氣橫出。","當東而西，當啄而飛。","隨飛隨啄，羣雌粥粥。","嗟我雖人，曾不如彼雉雞。","生身七十年，無一妾與妃。"]', '["雉之飞，于朝日。","羣雌孤雄，意氣橫出。","當东而西，當啄而飞。","隨飞隨啄，羣雌粥粥。","嗟我雖人，曾不如彼雉雞。","生身七十年，無一妾與妃。"]', '诗', 'shi', '', NULL, '琴曲歌辭 雉朝飛操 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b1f320f-14f3-4520-9bd8-314be626f5f3', '琴曲歌辭 雉朝飛操', '琴曲歌辞 雉朝飞操', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["朝陽隴東泛暖景，雙啄雙飛雙顧影。","朱冠錦襦聊日整，漠漠霧中如衣褧。","傷心盧女弦，七十老翁長獨眠。","雄飛在草雌在田，衷腸結憤氣呵天。","聖人在上心不偏，翁得女妻甚可憐。"]', '["朝陽隴东泛暖景，雙啄雙飞雙顧影。","朱冠錦襦聊日整，漠漠霧中如衣褧。","傷心盧女弦，七十老翁长独眠。","雄飞在草雌在田，衷腸結憤氣呵天。","聖人在上心不偏，翁得女妻甚可怜。"]', '诗', 'shi', '', NULL, '琴曲歌辭 雉朝飛操 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('050952a1-e091-45e6-a189-28cae91ecc11', '琴曲歌辭 思歸引', '琴曲歌辞 思归引', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["重重作閨清旦鐍，兩耳深聲長不徹。","深宮坐愁百年身，一片玉中生憤血。","焦桐罷彈絲自絕，漠漠暗魂愁夜月。","故鄉不歸誰共穴，石上作蒲蒲九節。"]', '["重重作閨清旦鐍，兩耳深声长不徹。","深宮坐愁百年身，一片玉中生憤血。","焦桐罷彈絲自絕，漠漠暗魂愁夜月。","故乡不归誰共穴，石上作蒲蒲九節。"]', '诗', 'shi', '', NULL, '琴曲歌辭 思歸引 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94f344ae-9834-4133-a350-e2cb30265fdf', '琴曲歌辭 猗蘭操', '琴曲歌辞 猗蘭操', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["蘭之猗猗，揚揚其香。","不采而佩，於蘭何傷。","今天之旋，其曷爲然。","我行四方，以日以年。","雪霜貿貿，薺麥之茂。","子如不傷，我不爾覯。","薺麥之茂，薺麥之有。","君子之傷，君子之守。"]', '["蘭之猗猗，揚揚其香。","不采而佩，於蘭何傷。","今天之旋，其曷爲然。","我行四方，以日以年。","雪霜貿貿，薺麦之茂。","子如不傷，我不爾覯。","薺麦之茂，薺麦之有。","君子之傷，君子之守。"]', '诗', 'shi', '', NULL, '琴曲歌辭 猗蘭操 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0d03f1b-abb4-4c3c-84b8-ee1925878a97', '琴曲歌辭 幽蘭', '琴曲歌辞 幽蘭', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["幽植衆能知，貞芳只暗持。","自無君子佩，未是國香衰。","白露霑長早，青春每到遲。"]', '["幽植衆能知，貞芳只暗持。","自無君子佩，未是国香衰。","白露霑长早，青春每到遲。"]', '诗', 'shi', '', NULL, '琴曲歌辭 幽蘭 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16f612a1-559a-4fe0-a9aa-67728642ad85', '琴曲歌辭 將歸操', '琴曲歌辞 將归操', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["秋之水兮其色幽幽，我將濟兮不得其由。","涉其淺兮石齧我足，乘其深兮龍入我舟，我濟而悔兮將安歸尤？","歸乎歸乎，無與石鬬兮無應龍求。"]', '["秋之水兮其色幽幽，我將濟兮不得其由。","涉其淺兮石齧我足，乘其深兮龙入我舟，我濟而悔兮將安归尤？","归乎归乎，無與石鬬兮無應龙求。"]', '诗', 'shi', '', NULL, '琴曲歌辭 將歸操 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bd9bf11-d7d5-4127-bd5a-7df036c66d02', '琴曲歌辭 龜山操', '琴曲歌辞 龟山操', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["龜之氣兮不能雲雨，龜之枿兮不中梁柱，龜之大兮祗以奄魯。","知將隳兮哀莫余伍，周公有鬼兮嗟余歸輔。"]', '["龟之氣兮不能云雨，龟之枿兮不中梁柱，龟之大兮祗以奄魯。","知將隳兮哀莫余伍，周公有鬼兮嗟余归輔。"]', '诗', 'shi', '', NULL, '琴曲歌辭 龜山操 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2363908-b4bc-416c-9b63-dcca77eacb7e', '琴曲歌辭 殘形操', '琴曲歌辞 殘形操', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["有獸維狸兮我夢得之，其身孔明兮而頭不知。","吉凶何爲兮覺坐而思，巫咸上天兮識者其誰。"]', '["有獸維狸兮我梦得之，其身孔明兮而头不知。","吉凶何爲兮覺坐而思，巫咸上天兮識者其誰。"]', '诗', 'shi', '', NULL, '琴曲歌辭 殘形操 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ce3f413-a677-4e46-a301-43f8be3a40c2', '琴曲歌辭 雙燕離', '琴曲歌辞 雙燕離', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["雙燕復雙燕，雙飛令人羨。","玉樓珠閣不獨棲，金窗繡戶長相見。","柏梁失火去，因入吳王宮。","吳宮又焚蕩，雛盡巢亦空。","憔悴一身在，孀雌憶故雄。","雙飛難再得，傷我寸心中。"]', '["雙燕复雙燕，雙飞令人羨。","玉楼珠閣不独棲，金窗繡戶长相见。","柏梁失火去，因入吳王宮。","吳宮又焚蕩，雛尽巢亦空。","憔悴一身在，孀雌憶故雄。","雙飞难再得，傷我寸心中。"]', '诗', 'shi', '', NULL, '琴曲歌辭 雙燕離 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ccd9915-51a1-4748-9989-af243036455b', '琴曲歌辭 列女操', '琴曲歌辞 列女操', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["梧桐相待老，鴛鴦會雙死。","貞婦貴徇夫，舍生亦如此。","波瀾誓不起，妾心井中水。"]', '["梧桐相待老，鴛鴦會雙死。","貞婦貴徇夫，舍生亦如此。","波瀾誓不起，妾心井中水。"]', '诗', 'shi', '', NULL, '琴曲歌辭 列女操 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('781a5cf4-dc33-45f0-be78-ae0dcdb04aa1', '琴曲歌辭 別鵠操', '琴曲歌辞 別鵠操', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["雄鵠銜枝來，雌鵠啄泥歸。","巢成不生子，大義當乖離。","江漢水之大，鵠身鳥之微。","更無相逢日，安可相隨飛。"]', '["雄鵠銜枝来，雌鵠啄泥归。","巢成不生子，大義當乖離。","江漢水之大，鵠身鸟之微。","更無相逢日，安可相隨飞。"]', '诗', 'shi', '', NULL, '琴曲歌辭 別鵠操 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a6798a1-eae0-48d8-9a2a-7dde2eae81fc', '琴曲歌辭 別鶴', '琴曲歌辞 別鹤', '08b14256-c564-4489-be33-927205119c81', '唐', '["海鶴一爲別，高程方杳然。","影搖江海路，思結瀟湘天。","皎然仰白日，真姿棲紫煙。","含情九霄際，顧侶五雲前。","遐心屬清都，淒響激朱弦。","超搖間雲雨，迢遰各山川。","東南信多水，會合當有年。"]', '["海鹤一爲別，高程方杳然。","影搖江海路，思結瀟湘天。","皎然仰白日，真姿棲紫煙。","含情九霄際，顧侶五云前。","遐心屬清都，淒响激朱弦。","超搖间云雨，迢遰各山川。","东南信多水，會合當有年。"]', '诗', 'shi', '', NULL, '琴曲歌辭 別鶴 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3c39438-5647-430e-b814-1318cde0ffb1', '琴曲歌辭 別鶴', '琴曲歌辞 別鹤', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["主人一去池水絕，池鶴散飛不相別。","青天漫漫碧海重，知向何山風雪中？","萬里雖然音影在，向心終是死生同。","池邊巢破松樹死，樹頭年年烏生子。"]', '["主人一去池水絕，池鹤散飞不相別。","青天漫漫碧海重，知向何山风雪中？","万里雖然音影在，向心終是死生同。","池邊巢破松樹死，樹头年年烏生子。"]', '诗', 'shi', '', NULL, '琴曲歌辭 別鶴 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bba0f29-6b38-446b-98d5-20268903330c', '琴曲歌辭 別鶴', '琴曲歌辞 別鹤', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["雙鶴出雲谿，分飛各自迷。","空巢在松杪，折羽落江泥。","尋水終不飲，逢林亦未棲。","別離應易老，萬里兩淒淒。"]', '["雙鹤出云谿，分飞各自迷。","空巢在松杪，折羽落江泥。","尋水終不饮，逢林亦未棲。","別離應易老，万里兩淒淒。"]', '诗', 'shi', '', NULL, '琴曲歌辭 別鶴 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c91b589-bd48-42db-8034-5b8c236dd885', '琴曲歌辭 別鶴', '琴曲歌辞 別鹤', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["分飛共所從，六翮勢摧風。","聲斷碧雲外，影孤明月中。","青田歸路遠，月桂舊巢空。","矯翼知何處，天涯不可窮。"]', '["分飞共所從，六翮勢摧风。","声斷碧云外，影孤明月中。","青田归路远，月桂旧巢空。","矯翼知何处，天涯不可窮。"]', '诗', 'shi', '', NULL, '琴曲歌辭 別鶴 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd4808c5-cefb-4840-8782-a1636acc9856', '琴曲歌辭 走馬引', '琴曲歌辞 走马引', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["我有辭鄉劒，玉鋒堪截雲。","襄陽走馬客，意氣自生春。","朝嫌劒光靜，暮嫌劒花冷。","能持劒向人，不解持照身。"]', '["我有辞乡劒，玉鋒堪截云。","襄陽走马客，意氣自生春。","朝嫌劒光静，暮嫌劒花冷。","能持劒向人，不解持照身。"]', '诗', 'shi', '', NULL, '琴曲歌辭 走馬引 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00c7dc13-8eed-4e09-8479-b35f76d3e883', '琴曲歌辭 昭君怨', '琴曲歌辞 昭君怨', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["明妃風貌最娉婷，合在椒房應四星。","只得當年備宮掖，何曾專夜奉幃屏。","見疎從道迷圖畫，知屈那教配虜廷。","自是君恩薄如紙，不須一向恨丹青。"]', '["明妃风貌最娉婷，合在椒房應四星。","只得當年備宮掖，何曾專夜奉幃屏。","见疎從道迷圖畫，知屈那教配虜廷。","自是君恩薄如紙，不須一向恨丹青。"]', '诗', 'shi', '', NULL, '琴曲歌辭 昭君怨 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25723633-8e6d-4adb-857e-7f371a2572fd', '琴曲歌辭 昭君怨 一', '琴曲歌辞 昭君怨 一', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["萬里邊城遠，千山行路難。","舉頭唯見日，何處是長安。"]', '["万里邊城远，千山行路难。","舉头唯见日，何处是长安。"]', '诗', 'shi', '', NULL, '琴曲歌辭 昭君怨 一 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a26eb089-1854-4fda-b922-6f7be2e3e54c', '琴曲歌辭 昭君怨 二', '琴曲歌辞 昭君怨 二', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["漢庭無大議，戎虜幾先和。","莫羨傾城色，昭君恨最多。"]', '["漢庭無大議，戎虜幾先和。","莫羨傾城色，昭君恨最多。"]', '诗', 'shi', '', NULL, '琴曲歌辭 昭君怨 二 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89ba3c9f-ac0b-474a-85b6-e273072daaca', '琴曲歌辭 昭君怨', '琴曲歌辞 昭君怨', '24b5378b-4560-4aca-88bb-ef672a1a5b11', '唐', '["自古無和親，貽災到妾身。","胡風嘶去馬，漢月弔行輪。","衣薄狼山雪，妝成虜塞春。","回看父母國，生死畢胡塵。"]', '["自古無和親，貽災到妾身。","胡风嘶去马，漢月弔行輪。","衣薄狼山雪，妝成虜塞春。","回看父母国，生死畢胡塵。"]', '诗', 'shi', '', NULL, '琴曲歌辭 昭君怨 梁氏瓊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('034a8779-06a1-4be8-8a41-7d1cd91b9e50', '琴曲歌辭 明妃怨', '琴曲歌辞 明妃怨', '4cc12f00-39c3-4459-bc41-9e7ee53b60ce', '唐', '["漢國明妃去不還，馬駞弦管向陰山。","匣中縱有菱花鏡，羞對單于照舊顏。"]', '["漢国明妃去不還，马駞弦管向陰山。","匣中縱有菱花镜，羞对單于照旧顏。"]', '诗', 'shi', '', NULL, '琴曲歌辭 明妃怨 楊淩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2019c628-e417-42eb-8e73-9991b9003a32', '琴曲歌辭 蔡氏五弄 遊春曲二首 一', '琴曲歌辞 蔡氏五弄 游春曲二首 一', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["萬樹江邊杏，新開一夜風。","滿園深淺色，照在綠波中。"]', '["万樹江邊杏，新开一夜风。","满园深淺色，照在綠波中。"]', '诗', 'shi', '', NULL, '琴曲歌辭 蔡氏五弄 遊春曲二首 一 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ba05592-e341-4956-b1fe-386bd7db5272', '琴曲歌辭 蔡氏五弄 遊春曲二首 二', '琴曲歌辞 蔡氏五弄 游春曲二首 二', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["上苑何窮樹，花開次第新。","香車與絲騎，風靜亦生塵。"]', '["上苑何窮樹，花开次第新。","香车與絲騎，风静亦生塵。"]', '诗', 'shi', '', NULL, '琴曲歌辭 蔡氏五弄 遊春曲二首 二 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74bb4a3f-696f-4218-9ffd-ae4cd1554d02', '琴曲歌辭  遊春辭二首 一', '琴曲歌辞  游春辞二首 一', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["曲江絲柳變煙條，寒骨冰隨暖氣銷。","纔見春光生綺陌，已聞清樂動雲韶。"]', '["曲江絲柳变煙條，寒骨冰隨暖氣銷。","纔见春光生綺陌，已闻清乐动云韶。"]', '诗', 'shi', '', NULL, '琴曲歌辭  遊春辭二首 一 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('637ae116-527c-45fd-9563-79c91c654969', '琴曲歌辭  遊春辭二首 二', '琴曲歌辞  游春辞二首 二', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["經過柳陌與桃蹊，尋逐風光著處迷。","鳥度時時衝絮起，花繁衮衮壓枝低。"]', '["經過柳陌與桃蹊，尋逐风光著处迷。","鸟度时时衝絮起，花繁衮衮壓枝低。"]', '诗', 'shi', '', NULL, '琴曲歌辭  遊春辭二首 二 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('314ba785-3431-4b8d-9ea3-ae18063492d4', '琴曲歌辭  遊春辭三首 一', '琴曲歌辞  游春辞三首 一', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["晚遊臨碧殿，日上望春亭。","芳樹羅仙仗，晴山展翠屏。"]', '["晚游臨碧殿，日上望春亭。","芳樹羅仙仗，晴山展翠屏。"]', '诗', 'shi', '', NULL, '琴曲歌辭  遊春辭三首 一 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95a1424f-b97b-481e-bf7a-50c140e1354b', '琴曲歌辭  遊春辭三首 二', '琴曲歌辞  游春辞三首 二', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["一夜好風吹，新花一萬枝。","風前調玉管，花下簇金羈。"]', '["一夜好风吹，新花一万枝。","风前調玉管，花下簇金羈。"]', '诗', 'shi', '', NULL, '琴曲歌辭  遊春辭三首 二 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cebc8c62-57f4-4b5c-bee3-9ef0de0e1df7', '琴曲歌辭  遊春辭三首 三', '琴曲歌辞  游春辞三首 三', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["閶闔春風起，蓬萊雪水消。","相將折楊柳，爭取最長條。"]', '["閶闔春风起，蓬萊雪水消。","相將折楊柳，爭取最长條。"]', '诗', 'shi', '', NULL, '琴曲歌辭  遊春辭三首 三 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d473eaba-72be-4de0-a7da-db3d833e6564', '琴曲歌辭  淥水曲', '琴曲歌辞  淥水曲', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["淥水明秋月，南湖采白蘋。","荷花嬌欲語，愁殺蕩舟人。"]', '["淥水明秋月，南湖采白蘋。","荷花嬌欲語，愁殺蕩舟人。"]', '诗', 'shi', '', NULL, '琴曲歌辭  淥水曲 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ec9007f-0dc2-4cfb-8f69-d3b0714a6db5', '琴曲歌辭  淥水辭', '琴曲歌辞  淥水辞', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["今宵好風月，阿侯在何處？","爲有傾城色，翻成足愁苦。","東湖采蓮葉，南湖拔蒲根。","未持寄小姑，且持感愁魂。"]', '["今宵好风月，阿侯在何处？","爲有傾城色，翻成足愁苦。","东湖采蓮葉，南湖拔蒲根。","未持寄小姑，且持感愁魂。"]', '诗', 'shi', '', NULL, '琴曲歌辭  淥水辭 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b52ca46-63f4-441a-97cc-dd5d1b722a47', '琴曲歌辭  幽居弄', '琴曲歌辞  幽居弄', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["苔衣生，花露滴，月入西林蕩東壁。","扣商占角兩三聲，洞戶谿窗一冥寂。","獨去滄洲無四鄰，身嬰世網此何身？","關情命曲寄惆悵，久別江南山裏人。"]', '["苔衣生，花露滴，月入西林蕩东壁。","扣商占角兩三声，洞戶谿窗一冥寂。","独去滄洲無四鄰，身嬰世網此何身？","关情命曲寄惆悵，久別江南山裏人。"]', '诗', 'shi', '', NULL, '琴曲歌辭  幽居弄 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed919b66-0fbe-4b4d-a985-9da7e82edc3d', '琴曲歌辭  秋思二首 一', '琴曲歌辞  秋思二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["春陽如昨日，碧樹鳴黃鸝。","蕪然蕙草暮，颯爾涼風吹。","天秋木葉下，月冷莎雞悲。","坐愁羣芳歇，白露凋華滋。"]', '["春陽如昨日，碧樹鳴黄鸝。","蕪然蕙草暮，颯爾涼风吹。","天秋木葉下，月冷莎雞悲。","坐愁羣芳歇，白露凋华滋。"]', '诗', 'shi', '', NULL, '琴曲歌辭  秋思二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e8f31ad-6b8c-422f-8c5d-71f6d5a0cf11', '琴曲歌辭  秋思二首 二', '琴曲歌辞  秋思二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["閼氏黃葉落，妾望白登臺。","月出碧雲斷，蟬聲秋色來。","胡兵沙塞合，漢使玉關回。","征客無歸日，空悲蕙草摧。"]', '["閼氏黄葉落，妾望白登台。","月出碧云斷，蟬声秋色来。","胡兵沙塞合，漢使玉关回。","征客無归日，空悲蕙草摧。"]', '诗', 'shi', '', NULL, '琴曲歌辭  秋思二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b281e5ae-9731-4a72-b474-7ac786246f35', '琴曲歌辭  秋思二首 一', '琴曲歌辞  秋思二首 一', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["胡風吹雁翼，遠別無人鄉。","君近鴈來處，幾回斷君腸。","昔奉千日書，撫心怨星霜。","無書又千日，世路重茫茫。","燕國有佳麗，蛾眉富春光。","自然君歸晚，花落君空堂。","君其若不然，歲晚雙鴛鴦。","顧兔蝕殘月，幽光不如星。","女兒晚事夫，顏色同秋螢。","秋日邊馬思，武夫不遑寧。","燕歌易水怨，劒舞蛟龍腥。","風折連枝樹，水翻無蒂萍。","立身多戶門，何必燕山銘。","生世不如鳥，雙雙比翼翎。"]', '["胡风吹雁翼，远別無人乡。","君近鴈来处，幾回斷君腸。","昔奉千日书，撫心怨星霜。","無书又千日，世路重茫茫。","燕国有佳丽，蛾眉富春光。","自然君归晚，花落君空堂。","君其若不然，歲晚雙鴛鴦。","顧兔蝕殘月，幽光不如星。","女兒晚事夫，顏色同秋螢。","秋日邊马思，武夫不遑寧。","燕歌易水怨，劒舞蛟龙腥。","风折連枝樹，水翻無蒂萍。","立身多戶门，何必燕山銘。","生世不如鸟，雙雙比翼翎。"]', '诗', 'shi', '', NULL, '琴曲歌辭  秋思二首 一 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b2d7014-6a5e-4e92-a1bc-e31e13bb609b', '琴曲歌辭  秋思二首 二', '琴曲歌辞  秋思二首 二', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["季秋天地閑，萬物生意足。","我憂長於生，安得及草木。","試從古人願，致酒歌秉燭。","燕趙皆世人，詎能長似玉。","俯憐老期近，仰視日車速。","蕭颯御風君，魂夢願相逐。","百年夜銷半，端爲垂纓束。"]', '["季秋天地闲，万物生意足。","我憂长於生，安得及草木。","試從古人願，致酒歌秉燭。","燕趙皆世人，詎能长似玉。","俯怜老期近，仰視日车速。","蕭颯御风君，魂梦願相逐。","百年夜銷半，端爲垂纓束。"]', '诗', 'shi', '', NULL, '琴曲歌辭  秋思二首 二 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78657ec0-5fb7-4c24-8b85-a0c10a418bab', '琴曲歌辭  秋思', '琴曲歌辞  秋思', '43b9fd0c-f2f5-4cfb-902a-d0c30a18d0c1', '唐', '["靜與嬾相偶，年將衰共催。","前途歡不集，往事恨空來。","晝景委紅葉，月華鋪綠苔。","沈思更何有？結坐玉琴哀。"]', '["静與嬾相偶，年將衰共催。","前途歡不集，往事恨空来。","晝景委紅葉，月华鋪綠苔。","沈思更何有？結坐玉琴哀。"]', '诗', 'shi', '', NULL, '琴曲歌辭  秋思 司空曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84049d3f-864e-4ffd-bfc7-8ed97e4a5c2d', '琴曲歌辭  秋思', '琴曲歌辞  秋思', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["身病時亦危，逢秋多慟哭。","風波一搖蕩，天地幾翻覆。","孤螢出荒池，落葉穿破屋。"]', '["身病时亦危，逢秋多慟哭。","风波一搖蕩，天地幾翻覆。","孤螢出荒池，落葉穿破屋。"]', '诗', 'shi', '', NULL, '琴曲歌辭  秋思 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3863ffe-6786-4785-9e56-6234fe5922f8', '琴曲歌辭  秋思二首 一', '琴曲歌辞  秋思二首 一', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["網軒涼吹動輕衣，夜聽更長玉漏稀。","月渡天河光轉溼，鵲驚秋樹葉頻飛。"]', '["網軒涼吹动轻衣，夜听更长玉漏稀。","月渡天河光轉溼，鵲驚秋樹葉頻飞。"]', '诗', 'shi', '', NULL, '琴曲歌辭  秋思二首 一 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbcf126a-4653-4297-8d15-52e894fcaaf4', '琴曲歌辭  秋思二首 二', '琴曲歌辞  秋思二首 二', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["宮連太液見蒼波，暑氣微清秋意多。","一夜輕風蘋末起，露珠翻盡滿池荷。"]', '["宮連太液见蒼波，暑氣微清秋意多。","一夜轻风蘋末起，露珠翻尽满池荷。"]', '诗', 'shi', '', NULL, '琴曲歌辭  秋思二首 二 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1f24e9c-4e19-44f1-b2e3-faff9539d036', '琴曲歌辭 胡笳十八拍 第一拍', '琴曲歌辞 胡笳十八拍 第一拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["漢室將衰兮四夷不賓，動干戈兮征戰頻。","哀哀父母生育我，見離亂兮當此辰。","紗窗對鏡未經事，將謂珠簾能蔽身。","一朝虜騎入中國，蒼黃處處逢胡人。","忽將薄命委鋒鏑，可惜紅顏隨虜塵。"]', '["漢室將衰兮四夷不賓，动干戈兮征戰頻。","哀哀父母生育我，见離亂兮當此辰。","紗窗对镜未經事，將謂珠簾能蔽身。","一朝虜騎入中国，蒼黄处处逢胡人。","忽將薄命委鋒鏑，可惜紅顏隨虜塵。"]', '诗', 'shi', '', NULL, '琴曲歌辭 胡笳十八拍 第一拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dff6c8a4-beba-41cf-852d-4ebff7178019', '琴曲歌辭 胡笳十八拍 第二拍', '琴曲歌辞 胡笳十八拍 第二拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["馬上將余向絕域，厭生求死死不得。","戎羯腥膻豈是人，豺狼喜怒難姑息。","行盡天山足霜霰，風土蕭條近胡國。","萬里重陰鳥不飛，寒沙莽莽無南北。"]', '["马上將余向絕域，厭生求死死不得。","戎羯腥膻豈是人，豺狼喜怒难姑息。","行尽天山足霜霰，风土蕭條近胡国。","万里重陰鸟不飞，寒沙莽莽無南北。"]', '诗', 'shi', '', NULL, '琴曲歌辭 胡笳十八拍 第二拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c421b42a-d13e-4531-b92b-6f7890911e80', '琴曲歌辭 胡笳十八拍 第三拍', '琴曲歌辞 胡笳十八拍 第三拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["如羇囚兮在縲紲，憂慮萬端無處說。","使余力兮翦余髮，食余肉兮飲余血。","誠知殺身願如此，以余爲妻不如死。","早被蛾眉累此身，空悲弱質柔如水。"]', '["如羇囚兮在縲紲，憂慮万端無处说。","使余力兮翦余髮，食余肉兮饮余血。","誠知殺身願如此，以余爲妻不如死。","早被蛾眉累此身，空悲弱質柔如水。"]', '诗', 'shi', '', NULL, '琴曲歌辭 胡笳十八拍 第三拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afb354cd-575a-4bd9-837a-c5a4c199524a', '琴曲歌辭 胡笳十八拍 第四拍', '琴曲歌辞 胡笳十八拍 第四拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["山川路長誰記得，何處天涯是鄉國？","自從驚怖少精神，不覺風霜損顏色。","夜中歸夢來又去，朦朧豈解傳消息。","漫漫胡天叫不聞，明明漢月應相識。"]', '["山川路长誰記得，何处天涯是乡国？","自從驚怖少精神，不覺风霜損顏色。","夜中归梦来又去，朦朧豈解傳消息。","漫漫胡天叫不闻，明明漢月應相識。"]', '诗', 'shi', '', NULL, '琴曲歌辭 胡笳十八拍 第四拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('788b5b30-f9e9-47f0-b51c-aa396a2bdac7', '琴曲歌辭 胡笳十八拍 第五拍', '琴曲歌辞 胡笳十八拍 第五拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["水頭宿兮草頭坐，風吹漢地衣裳破。","羊脂沐髮長不梳，羔子皮裘領仍左。","狐襟貉袖腥復膻，晝披行兮夜披臥。","氈帳時移無定居，日月長兮不可過。"]', '["水头宿兮草头坐，风吹漢地衣裳破。","羊脂沐髮长不梳，羔子皮裘領仍左。","狐襟貉袖腥复膻，晝披行兮夜披臥。","氈帳时移無定居，日月长兮不可過。"]', '诗', 'shi', '', NULL, '琴曲歌辭 胡笳十八拍 第五拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63703064-7741-4e1f-802a-f37572bbe641', '琴曲歌辭 胡笳十八拍 第六拍', '琴曲歌辞 胡笳十八拍 第六拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["怪得春光不來久，胡中風土無花柳。","天翻地覆誰得知，如今正南看北斗。","姓名音信兩不通，終日經年常閉口。","是非取與在指撝，言語傳情不如手。"]', '["怪得春光不来久，胡中风土無花柳。","天翻地覆誰得知，如今正南看北斗。","姓名音信兩不通，終日經年常閉口。","是非取與在指撝，言語傳情不如手。"]', '诗', 'shi', '', NULL, '琴曲歌辭 胡笳十八拍 第六拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1732f3c-f3c8-4f2f-80de-f293835118b0', '琴曲歌辭 胡笳十八拍 第七拍', '琴曲歌辞 胡笳十八拍 第七拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["男兒婦人帶弓箭，塞馬蕃羊臥霜霰。","寸步東西豈自由，偷生乞死非情願。","龜茲篳篥愁中聽，碎葉琵琶夜深怨。","竟夕無雲月上天，故鄉應得重相見。"]', '["男兒婦人带弓箭，塞马蕃羊臥霜霰。","寸步东西豈自由，偷生乞死非情願。","龟茲篳篥愁中听，碎葉琵琶夜深怨。","竟夕無云月上天，故乡應得重相见。"]', '诗', 'shi', '', NULL, '琴曲歌辭 胡笳十八拍 第七拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afa11a8c-8bce-408c-a688-2af0cc6632b5', '琴曲歌辭 胡笳十八拍 第八拍', '琴曲歌辞 胡笳十八拍 第八拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["憶昔私家恣嬌小，遠取珍禽學馴擾。","如今淪棄念故鄉，悔不當初放林表。","朔風蕭蕭寒日暮，星河寥落胡天曉。","旦夕思歸不得歸，愁心想似籠中鳥。"]', '["憶昔私家恣嬌小，远取珍禽学馴擾。","如今淪棄念故乡，悔不當初放林表。","朔风蕭蕭寒日暮，星河寥落胡天晓。","旦夕思归不得归，愁心想似籠中鸟。"]', '诗', 'shi', '', NULL, '琴曲歌辭 胡笳十八拍 第八拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('174db93b-a107-453b-b886-008cebf67118', '琴曲歌辭 胡笳十八拍 第九拍', '琴曲歌辞 胡笳十八拍 第九拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["當日蘇武單于問，道是賓鴻解傳信。","學他刺血寫得書，書上千重萬重恨。","髯胡少年能走馬，彎弓射飛無遠近。","遂令邊雁轉怕人，絕域何由達方寸。"]', '["當日蘇武單于问，道是賓鴻解傳信。","学他刺血寫得书，书上千重万重恨。","髯胡少年能走马，彎弓射飞無远近。","遂令邊雁轉怕人，絕域何由達方寸。"]', '诗', 'shi', '', NULL, '琴曲歌辭 胡笳十八拍 第九拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('171eb58b-bb4c-4495-afec-5e09ef658a83', '琴曲歌辭 胡笳十八拍 第十拍', '琴曲歌辞 胡笳十八拍 第十拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["恨凌辱兮惡腥膻，憎胡地兮怨胡天。","生得胡兒欲棄捐，及生母子情宛然。","貌殊語異憎還愛，心中不覺常相牽。","朝朝暮暮在眼前，腹生手養寧不憐。"]', '["恨凌辱兮惡腥膻，憎胡地兮怨胡天。","生得胡兒欲棄捐，及生母子情宛然。","貌殊語異憎還愛，心中不覺常相牽。","朝朝暮暮在眼前，腹生手養寧不怜。"]', '诗', 'shi', '', NULL, '琴曲歌辭 胡笳十八拍 第十拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca98fed4-d62e-480c-bcb7-b2b95749441a', '琴曲歌辭 胡笳十八拍 第十一拍', '琴曲歌辞 胡笳十八拍 第十一拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["日來月往相推遷，迢迢星歲欲周天。","無冬無夏臥霜霰，水凍草枯爲一年。","漢家甲子有正朔，絕域三光空自懸。","幾回鴻雁來又去，腸斷蟾蜍虧復圓。"]', '["日来月往相推遷，迢迢星歲欲周天。","無冬無夏臥霜霰，水凍草枯爲一年。","漢家甲子有正朔，絕域三光空自懸。","幾回鴻雁来又去，腸斷蟾蜍虧复圓。"]', '诗', 'shi', '', NULL, '琴曲歌辭 胡笳十八拍 第十一拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6e20a39-bf74-4373-9181-f7dc61b22c33', '琴曲歌辭 胡笳十八拍 第十二拍', '琴曲歌辞 胡笳十八拍 第十二拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["破瓶落井空永沈，故鄉望斷無歸心。","寧知遠使問姓名，漢語泠泠傳好音。","夢魂幾度到鄉國，覺後翻成哀怨深。","如今果是夢中事，喜過悲來情不任。"]', '["破瓶落井空永沈，故乡望斷無归心。","寧知远使问姓名，漢語泠泠傳好音。","梦魂幾度到乡国，覺後翻成哀怨深。","如今果是梦中事，喜過悲来情不任。"]', '诗', 'shi', '', NULL, '琴曲歌辭 胡笳十八拍 第十二拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16c5ed5e-3738-4454-9580-c3929d9aea70', '琴曲歌辭 胡笳十八拍 第十三拍', '琴曲歌辞 胡笳十八拍 第十三拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["童稚牽衣雙在側，將來不可留又憶。","還鄉惜別兩難分，寧棄胡兒歸舊國。","山川萬里復邊戍，背面無由得消息。","淚痕滿面對殘陽，終日依依向南北。"]', '["童稚牽衣雙在側，將来不可留又憶。","還乡惜別兩难分，寧棄胡兒归旧国。","山川万里复邊戍，背面無由得消息。","泪痕满面对殘陽，終日依依向南北。"]', '诗', 'shi', '', NULL, '琴曲歌辭 胡笳十八拍 第十三拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bab04bd0-d69a-4a0b-ad70-f312ae4e2850', '琴曲歌辭 胡笳十八拍 第十四拍', '琴曲歌辞 胡笳十八拍 第十四拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["莫以胡兒可羞恥，恩情亦各言其子。","手中十指有長短，截之痛惜皆相似。","還鄉豈不見親族，念此飄零隔生死。","南風萬里吹我心，心亦隨風渡遼水。"]', '["莫以胡兒可羞恥，恩情亦各言其子。","手中十指有长短，截之痛惜皆相似。","還乡豈不见親族，念此飄零隔生死。","南风万里吹我心，心亦隨风渡遼水。"]', '诗', 'shi', '', NULL, '琴曲歌辭 胡笳十八拍 第十四拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ecbe1b7-261f-4a6c-867b-8bdf85041193', '琴曲歌辭 胡笳十八拍 第十五拍', '琴曲歌辞 胡笳十八拍 第十五拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["歎息襟懷無定分，當時怨來歸又恨。","不知愁怨意若何？似有鋒鋩擾方寸。","悲歡竝行情未快，心意相尤自相問。","不緣生得天屬親，豈向仇讐結恩信。"]', '["歎息襟懷無定分，當时怨来归又恨。","不知愁怨意若何？似有鋒鋩擾方寸。","悲歡竝行情未快，心意相尤自相问。","不緣生得天屬親，豈向仇讐結恩信。"]', '诗', 'shi', '', NULL, '琴曲歌辭 胡笳十八拍 第十五拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48ced39d-5dd8-4338-8d84-872036b9cb90', '琴曲歌辭 胡笳十八拍 第十六拍', '琴曲歌辞 胡笳十八拍 第十六拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["去時只覺天蒼蒼，歸日始知胡地長。","重陰白日落何處？秋鴈所向應南方。","平沙四顧自迷惑，遠近悠悠隨鴈行。","征途未盡馬蹄盡，不見行人邊草黃。"]', '["去时只覺天蒼蒼，归日始知胡地长。","重陰白日落何处？秋鴈所向應南方。","平沙四顧自迷惑，远近悠悠隨鴈行。","征途未尽马蹄尽，不见行人邊草黄。"]', '诗', 'shi', '', NULL, '琴曲歌辭 胡笳十八拍 第十六拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c02906d2-c9d0-4319-8996-95902b618962', '琴曲歌辭 胡笳十八拍 第十七拍', '琴曲歌辞 胡笳十八拍 第十七拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["行盡胡天千萬里，惟見黃沙白雲起。","馬飢跑雪銜草根，人渴敲冰飲流水。","燕山髣髴辨烽戍，鼙鼓如聞漢家壘。","努力前程是帝鄉，生前免向胡中死。"]', '["行尽胡天千万里，惟见黄沙白云起。","马飢跑雪銜草根，人渴敲冰饮流水。","燕山髣髴辨烽戍，鼙鼓如闻漢家壘。","努力前程是帝乡，生前免向胡中死。"]', '诗', 'shi', '', NULL, '琴曲歌辭 胡笳十八拍 第十七拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1809b35f-90e9-48f1-9844-c467caabddd7', '琴曲歌辭 胡笳十八拍 第十八拍', '琴曲歌辞 胡笳十八拍 第十八拍', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["歸來故鄉見親族，田園半蕪春草綠。","明燭重然煨燼灰，寒泉更洗沈泥玉。","載持巾櫛禮儀好，一弄絲桐生死足。","出入關山十二年，哀情盡在胡笳曲。"]', '["归来故乡见親族，田园半蕪春草綠。","明燭重然煨燼灰，寒泉更洗沈泥玉。","載持巾櫛禮儀好，一弄絲桐生死足。","出入关山十二年，哀情尽在胡笳曲。"]', '诗', 'shi', '', NULL, '琴曲歌辭 胡笳十八拍 第十八拍 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d56a5527-058e-49dc-918a-1cc378feed24', '琴曲歌辭 飛龍引二首 一', '琴曲歌辞 飞龙引二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["黃帝鑄鼎於荆山，鍊丹砂。","丹砂成黃金，騎龍飛上太清家。","雲愁海思令人嗟，宮中綵女顏如花。","飄然揮手凌紫霞，從風縱體登鑾車。","登鑾車，侍軒轅。","遨遊青天中，其樂不可言。"]', '["黄帝鑄鼎於荆山，鍊丹砂。","丹砂成黄金，騎龙飞上太清家。","云愁海思令人嗟，宮中綵女顏如花。","飄然揮手凌紫霞，從风縱體登鑾车。","登鑾车，侍軒轅。","遨游青天中，其乐不可言。"]', '诗', 'shi', '', NULL, '琴曲歌辭 飛龍引二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82319857-3f0e-4f8f-8e9b-d636d68cae97', '琴曲歌辭 飛龍引二首 二', '琴曲歌辞 飞龙引二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["鼎湖流水清且閑，軒轅去時有弓劒。","古人傳道留其間，後宮嬋娟多花顏。","乘鸞飛煙亦不還，騎龍攀天造天關。","造天關，聞天語，長雲河車載玉女。","載玉女，過紫皇，紫皇乃賜白兔所擣之藥，後天而老凋三光。","下視瑤池見王母，蛾眉蕭颯如秋霜。"]', '["鼎湖流水清且闲，軒轅去时有弓劒。","古人傳道留其间，後宮嬋娟多花顏。","乘鸾飞煙亦不還，騎龙攀天造天关。","造天关，闻天語，长云河车載玉女。","載玉女，過紫皇，紫皇乃賜白兔所擣之藥，後天而老凋三光。","下視瑤池见王母，蛾眉蕭颯如秋霜。"]', '诗', 'shi', '', NULL, '琴曲歌辭 飛龍引二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6392275-4bf7-46df-ba00-314acb2923e1', '琴曲歌辭 烏夜啼引', '琴曲歌辞 烏夜啼引', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["秦烏啼啞啞，夜啼長安吏人家。","吏人得罪囚在獄，傾家賣產將自贖。","少婦起聽夜啼烏，知是官家有赦書。","下牀心喜不重寐，未明上堂賀舅姑。","少婦語啼烏，汝啼慎勿虛。","借汝庭樹作高巢，年年不令傷爾雛。"]', '["秦烏啼啞啞，夜啼长安吏人家。","吏人得罪囚在獄，傾家賣產將自贖。","少婦起听夜啼烏，知是官家有赦书。","下牀心喜不重寐，未明上堂賀舅姑。","少婦語啼烏，汝啼慎勿虛。","借汝庭樹作高巢，年年不令傷爾雛。"]', '诗', 'shi', '', NULL, '琴曲歌辭 烏夜啼引 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16c63af4-622a-45e2-9a1c-ebb406711054', '琴曲歌辭 宛轉歌 一', '琴曲歌辞 宛轉歌 一', 'aff13fc2-5a00-4377-82e1-6a8e636e4aaf', '唐', '["風已清，月朗琴復鳴。","掩抑非千態，殷勤是一聲。","歌宛轉，宛轉和且長。","願爲雙鴻鵠，比翼共翱翔。"]', '["风已清，月朗琴复鳴。","掩抑非千態，殷勤是一声。","歌宛轉，宛轉和且长。","願爲雙鴻鵠，比翼共翱翔。"]', '诗', 'shi', '', NULL, '琴曲歌辭 宛轉歌 一 郎大家宋氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('261f0670-83cc-482d-bdcf-a5c090d0f5bd', '琴曲歌辭 宛轉歌 二', '琴曲歌辞 宛轉歌 二', 'aff13fc2-5a00-4377-82e1-6a8e636e4aaf', '唐', '["日已暮，長簷鳥應度。","此時望君君不來，此時思君君不顧。","歌宛轉，宛轉那能異棲宿。","願爲形與影，出入恆相逐。"]', '["日已暮，长簷鸟應度。","此时望君君不来，此时思君君不顧。","歌宛轉，宛轉那能異棲宿。","願爲形與影，出入恆相逐。"]', '诗', 'shi', '', NULL, '琴曲歌辭 宛轉歌 二 郎大家宋氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1f3e67e-7367-4ec5-883c-1034927aff24', '琴曲歌辭 宛轉歌二首 一', '琴曲歌辞 宛轉歌二首 一', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["星參差，月二八，燈五枝。","黃鶴瑤琴將別去，芙蓉羽帳惜空垂。","歌宛轉，宛轉恨無窮。","願爲波與浪，俱起碧流中。"]', '["星參差，月二八，灯五枝。","黄鹤瑤琴將別去，芙蓉羽帳惜空垂。","歌宛轉，宛轉恨無窮。","願爲波與浪，俱起碧流中。"]', '诗', 'shi', '', NULL, '琴曲歌辭 宛轉歌二首 一 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5e1247c-6c4a-45a3-9f2e-60adee788526', '琴曲歌辭 宛轉歌二首 二', '琴曲歌辞 宛轉歌二首 二', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["曉將近，黃姑織女銀河盡。","九華錦衾無復情，千金寶鏡誰能引。","歌宛轉，宛轉傷別離。","願作楊與柳，同向玉窗垂。"]', '["晓將近，黄姑织女銀河尽。","九华錦衾無复情，千金寶镜誰能引。","歌宛轉，宛轉傷別離。","願作楊與柳，同向玉窗垂。"]', '诗', 'shi', '', NULL, '琴曲歌辭 宛轉歌二首 二 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('debccda9-ee99-40d6-9b3e-f4b38cdfa8bb', '琴曲歌辭 宛轉行', '琴曲歌辞 宛轉行', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["華屋重翠幄，綺席雕象牀。","遠漏微更疎，薄衾中夜涼。","爐氳暗裴回，寒燈背斜光。","妍姿結宵態，寢臂幽夢長。","宛轉復宛轉，憶憶更未央。"]', '["华屋重翠幄，綺席雕象牀。","远漏微更疎，薄衾中夜涼。","爐氳暗裴回，寒灯背斜光。","妍姿結宵態，寢臂幽梦长。","宛轉复宛轉，憶憶更未央。"]', '诗', 'shi', '', NULL, '琴曲歌辭 宛轉行 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be5f29a5-663b-4905-80e7-b034a6b2a745', '琴曲歌辭 王敬伯歌', '琴曲歌辞 王敬伯歌', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["妾本舟中客，聞君江上琴。","君初感妾歎，妾亦感君心。","遂出合歡被，同爲交頸禽。","傳杯惟畏淺，接膝猶嫌遠。","侍婢奏箜篌，女郎歌宛轉。","宛轉怨如何，中庭霜漸多。","霜多葉可惜，昨日非今夕。","徒結萬里歡，終成一宵客。","王敬伯，淥水青山從此隔。"]', '["妾本舟中客，闻君江上琴。","君初感妾歎，妾亦感君心。","遂出合歡被，同爲交頸禽。","傳杯惟畏淺，接膝猶嫌远。","侍婢奏箜篌，女郎歌宛轉。","宛轉怨如何，中庭霜漸多。","霜多葉可惜，昨日非今夕。","徒結万里歡，終成一宵客。","王敬伯，淥水青山從此隔。"]', '诗', 'shi', '', NULL, '琴曲歌辭 王敬伯歌 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b145a90c-e179-4cc0-8a66-1d63af2bfe6b', '琴曲歌辭 三峽流泉歌', '琴曲歌辞 三峽流泉歌', 'a3109d9f-4c03-46dd-bd4b-7cd2ac938b2b', '唐', '["妾家本住巫山雲，巫山流水常自聞。","玉琴彈出轉寥敻，直似當時夢中聽。","三峽流泉幾千里，一時流入深閨裏。","巨石奔崖指下生，飛波走浪弦中起。","初疑噴湧含雷風，又似嗚咽流不通。","回湍曲瀨勢將盡，時復滴瀝平沙中。","憶昔阮公爲此曲，能使仲容聽不足。","一彈既罷復一彈，願似流泉鎮相續。"]', '["妾家本住巫山云，巫山流水常自闻。","玉琴彈出轉寥敻，直似當时梦中听。","三峽流泉幾千里，一时流入深閨裏。","巨石奔崖指下生，飞波走浪弦中起。","初疑噴湧含雷风，又似嗚咽流不通。","回湍曲瀨勢將尽，时复滴瀝平沙中。","憶昔阮公爲此曲，能使仲容听不足。","一彈既罷复一彈，願似流泉鎮相續。"]', '诗', 'shi', '', NULL, '琴曲歌辭 三峽流泉歌 李季蘭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('333b66bc-2738-4424-aaf9-c8834be7fabe', '琴曲歌辭 風入松歌', '琴曲歌辞 风入松歌', 'd031d511-00fb-47fd-8345-864309b121e2', '唐', '["西嶺松聲落日秋，千枝萬葉風颼飀。","美人援琴弄成曲，寫得松間聲斷續。","聲斷續，清我魂，流波壞陵安足論。","美人夜坐月明裏，含少商兮照清徵。","風何淒兮飄飉，攪寒松兮又夜起。","夜未央，曲何長，金徽更促聲泱泱。","何人此時不得意，意苦弦悲聞客堂。"]', '["西嶺松声落日秋，千枝万葉风颼飀。","美人援琴弄成曲，寫得松间声斷續。","声斷續，清我魂，流波壞陵安足論。","美人夜坐月明裏，含少商兮照清徵。","风何淒兮飄飉，攪寒松兮又夜起。","夜未央，曲何长，金徽更促声泱泱。","何人此时不得意，意苦弦悲闻客堂。"]', '诗', 'shi', '', NULL, '琴曲歌辭 風入松歌 僧皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ecd869d-dd96-421b-905b-a70a0cb44bad', '琴曲歌辭 秋風引', '琴曲歌辞 秋风引', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["何處秋風至？蕭蕭送鴈羣。","朝來入庭樹，孤客最先聞。"]', '["何处秋风至？蕭蕭送鴈羣。","朝来入庭樹，孤客最先闻。"]', '诗', 'shi', '', NULL, '琴曲歌辭 秋風引 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b4cf3ff-a6ad-440d-bdd1-85fea0b62ae4', '琴曲歌辭 明月引', '琴曲歌辞 明月引', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["洞庭波起兮鴻鴈翔，風瑟瑟兮野蒼蒼。","浮雲卷靄，明月流光。","荆南兮趙北，碣石兮瀟湘。","澄清規於萬里，照離思於千行。","橫桂枝於西第，繞菱花於北堂。","高樓思婦，飛蓋君王。","文姬絕域，侍子他鄉。","見胡鞍之似練，知漢劒之如霜。","試登高而極目，莫不變而迴腸。"]', '["洞庭波起兮鴻鴈翔，风瑟瑟兮野蒼蒼。","浮云卷靄，明月流光。","荆南兮趙北，碣石兮瀟湘。","澄清規於万里，照離思於千行。","橫桂枝於西第，繞菱花於北堂。","高楼思婦，飞蓋君王。","文姬絕域，侍子他乡。","见胡鞍之似練，知漢劒之如霜。","試登高而極目，莫不变而迴腸。"]', '诗', 'shi', '', NULL, '琴曲歌辭 明月引 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cc847cf-e7a7-4e9b-a32b-d621e1f0b3e1', '琴曲歌辭 明月歌', '琴曲歌辞 明月歌', '279468d4-48db-402e-9185-d8eb7a150748', '唐', '["梅花雪白柳葉黃，雲霧四起月蒼蒼，箭水泠冷刻漏長。","揮玉指，拂羅裳，爲君一奏楚明光。"]', '["梅花雪白柳葉黄，云霧四起月蒼蒼，箭水泠冷刻漏长。","揮玉指，拂羅裳，爲君一奏楚明光。"]', '诗', 'shi', '', NULL, '琴曲歌辭 明月歌 閻朝隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d058b37e-109f-4f52-be37-f42936cdd75b', '琴曲歌辭 綠竹引', '琴曲歌辞 綠竹引', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["青溪綠潭潭水側，修竹嬋娟同一色。","徒生仙實鳳不遊，老死空山人詎識。","妙年秉願逃俗紛，歸臥嵩丘弄白雲。"]', '["青溪綠潭潭水側，修竹嬋娟同一色。","徒生仙實鳳不游，老死空山人詎識。","妙年秉願逃俗紛，归臥嵩丘弄白云。"]', '诗', 'shi', '', NULL, '琴曲歌辭 綠竹引 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09837acc-5db1-4202-9c19-541451797944', '琴曲歌辭 山人勸酒', '琴曲歌辞 山人勸酒', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["蒼蒼雲松，落落綺皓。","春風爾來爲阿誰，胡蝶忽然滿芳草。","秀眉霜雪顏桃花，骨青髓綠長美好。","稱是秦時避世人，勸酒相歡不知老。","各守兔鹿志，恥隨龍虎爭。","歘起佐太子，漢王乃復驚。","顧謂戚夫人，彼翁羽翼成。","歸來南山下，泛若雲無情。","舉觴酹巢由，洗耳何獨清？","浩歌望嵩嶽，意氣還相傾。"]', '["蒼蒼云松，落落綺皓。","春风爾来爲阿誰，胡蝶忽然满芳草。","秀眉霜雪顏桃花，骨青髓綠长美好。","稱是秦时避世人，勸酒相歡不知老。","各守兔鹿志，恥隨龙虎爭。","歘起佐太子，漢王乃复驚。","顧謂戚夫人，彼翁羽翼成。","归来南山下，泛若云無情。","舉觴酹巢由，洗耳何独清？","浩歌望嵩嶽，意氣還相傾。"]', '诗', 'shi', '', NULL, '琴曲歌辭 山人勸酒 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('540059fa-03ad-4e23-8ca7-7a7b6dfcfb63', '琴曲歌辭 幽澗泉', '琴曲歌辞 幽澗泉', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["拂彼白石，彈吾素琴。","幽澗愀兮流泉深，善手明徽高張清。","心寂歷似千古，松颼飀兮萬尋。","中見愁猨弔影而危處兮，呌秋木而長吟。","客有哀時失志而聽者，淚淋浪以霑襟。","乃緝商綴羽，潺湲成音。","吾但寫聲發情於妙指，殊不知此曲之古今。","幽澗泉，鳴深林。"]', '["拂彼白石，彈吾素琴。","幽澗愀兮流泉深，善手明徽高張清。","心寂歷似千古，松颼飀兮万尋。","中见愁猨弔影而危处兮，呌秋木而长吟。","客有哀时失志而听者，泪淋浪以霑襟。","乃緝商綴羽，潺湲成音。","吾但寫声發情於妙指，殊不知此曲之古今。","幽澗泉，鳴深林。"]', '诗', 'shi', '', NULL, '琴曲歌辭 幽澗泉 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bc23215-91c6-48d6-8d9d-5995b37c244d', '琴曲歌辭 龍宮操', '琴曲歌辞 龙宮操', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["龍宮月明光參差，精衛銜石東飛時。","鮫人織綃采藕絲，翻江倒海傾吳蜀。","漢女江妃杳相續，龍王宮中水不足。"]', '["龙宮月明光參差，精衛銜石东飞时。","鮫人织綃采藕絲，翻江倒海傾吳蜀。","漢女江妃杳相續，龙王宮中水不足。"]', '诗', 'shi', '', NULL, '琴曲歌辭 龍宮操 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4b42026-8bea-4d0d-a0b3-f6ecc59a420a', '琴曲歌辭 飛鳶操', '琴曲歌辞 飞鳶操', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["鳶飛杳杳青雲裏，鳶鳴蕭蕭風四起。","旗尾飄揚勢漸高，箭頭砉劃聲相似。","長空悠悠霽日懸，六翮不動凝飛煙。","遊鶤翔鴈出其下，慶雲清景相迴旋。","忽聞飢烏一噪聚，瞥下雲中爭腐鼠。","騰音礪吻相喧呼，仰天大嚇疑鴛雛。","畏人避犬投高處，俛啄無聲猶屢顧。","青鳥自愛玉山禾，仙禽徒貴華亭露。","樸𣙙危巢向暮時，毰毸飽腹蹲枯枝。","遊童挾彈一麾肘，臆碎羽分人不悲。","天生衆禽各有類，威鳳文章在仁義。","鷹隼儀形螻蟻心，雖能戾天何足貴。"]', '["鳶飞杳杳青云裏，鳶鳴蕭蕭风四起。","旗尾飄揚勢漸高，箭头砉劃声相似。","长空悠悠霽日懸，六翮不动凝飞煙。","游鶤翔鴈出其下，慶云清景相迴旋。","忽闻飢烏一噪聚，瞥下云中爭腐鼠。","腾音礪吻相喧呼，仰天大嚇疑鴛雛。","畏人避犬投高处，俛啄無声猶屢顧。","青鸟自愛玉山禾，仙禽徒貴华亭露。","樸𣙙危巢向暮时，毰毸飽腹蹲枯枝。","游童挾彈一麾肘，臆碎羽分人不悲。","天生衆禽各有類，威鳳文章在仁義。","鷹隼儀形螻蟻心，雖能戾天何足貴。"]', '诗', 'shi', '', NULL, '琴曲歌辭 飛鳶操 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2558ab95-ea7f-4124-96e5-a498f843198c', '琴曲歌辭 昇仙操', '琴曲歌辞 昇仙操', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["嬴女去秦宮，瓊簫生碧空。","鳳臺閉煙霧，鸞吹飄天風。","復聞周太子，亦遇浮丘公。","叢簧發仙弄，輕舉紫霞中。","濁世不久住，清都路何窮。","一去霄漢上，世人那得逢。"]', '["嬴女去秦宮，瓊簫生碧空。","鳳台閉煙霧，鸾吹飄天风。","复闻周太子，亦遇浮丘公。","叢簧發仙弄，轻舉紫霞中。","濁世不久住，清都路何窮。","一去霄漢上，世人那得逢。"]', '诗', 'shi', '', NULL, '琴曲歌辭 昇仙操 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b7a1754-680e-4488-be9b-d530ede678b6', '琴曲歌辭 司馬相如琴歌', '琴曲歌辞 司马相如琴歌', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["鳳兮鳳兮非無凰，山重水闊不可量。","梧桐結陰在朝陽，濯羽弱水鳴高翔。"]', '["鳳兮鳳兮非無凰，山重水闊不可量。","梧桐結陰在朝陽，濯羽弱水鳴高翔。"]', '诗', 'shi', '', NULL, '琴曲歌辭 司馬相如琴歌 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('271c14ff-6628-4ab5-862c-ee0a524358f8', '琴曲歌辭 霍將軍', '琴曲歌辞 霍將軍', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["長安甲第高入雲，誰家居住霍將軍。","日晚朝回擁賓從，路傍揖拜何紛紛。","莫言炙手手可熱，須臾火盡灰亦滅。","莫言貧賤即可欺，人生富貴自有時。","一朝天子賜顏色，世上悠悠應自知。"]', '["长安甲第高入云，誰家居住霍將軍。","日晚朝回擁賓從，路傍揖拜何紛紛。","莫言炙手手可熱，須臾火尽灰亦滅。","莫言貧賤即可欺，人生富貴自有时。","一朝天子賜顏色，世上悠悠應自知。"]', '诗', 'shi', '', NULL, '琴曲歌辭 霍將軍 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfc0cb68-548a-41aa-a47f-492d7e264183', '琴曲歌辭 琴歌', '琴曲歌辞 琴歌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["琴調秋些，胡風遶雪。","峽泉生咽，佳人愁些。"]', '["琴調秋些，胡风遶雪。","峽泉生咽，佳人愁些。"]', '诗', 'shi', '', NULL, '琴曲歌辭 琴歌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ee76ac8-3321-4568-9217-ae3267ce875f', '雜曲歌辭 秦女休行', '杂曲歌辞 秦女休行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["西門秦氏女，秀色如瓊花。","手揮白楊刀，清晝殺讐家。","羅袖灑赤血，英聲凌紫霞。","直上西山去，關吏相邀遮。","壻爲燕國王，身被詔獄加。","犯刑若履虎，不畏落爪牙。","素頸未及斷，摧眉伏泥沙。","金雞忽放赦，大辟得寬賒。","何慙聶政姊，萬古共驚嗟。"]', '["西门秦氏女，秀色如瓊花。","手揮白楊刀，清晝殺讐家。","羅袖灑赤血，英声凌紫霞。","直上西山去，关吏相邀遮。","壻爲燕国王，身被詔獄加。","犯刑若履虎，不畏落爪牙。","素頸未及斷，摧眉伏泥沙。","金雞忽放赦，大辟得寬賒。","何慙聶政姊，万古共驚嗟。"]', '诗', 'shi', '', NULL, '雜曲歌辭 秦女休行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b9e0802-9e1e-44f0-893a-8f34e4be5394', '雜曲歌辭 出門行二首 一', '杂曲歌辞 出门行二首 一', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["長河悠悠去無極，百齡同此可歎息。","秋風白露霑人衣，壯心凋落奪顏色。","少年出門將訴誰，川無梁兮路無岐。","一聞陌上苦寒奏，使我佇立驚且悲。","君今得意厭粱肉，豈復念我貧賤時。"]', '["长河悠悠去無極，百齡同此可歎息。","秋风白露霑人衣，壯心凋落奪顏色。","少年出门將訴誰，川無梁兮路無岐。","一闻陌上苦寒奏，使我佇立驚且悲。","君今得意厭粱肉，豈复念我貧賤时。"]', '诗', 'shi', '', NULL, '雜曲歌辭 出門行二首 一 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('215dbf70-fc96-41e5-80ae-edf233df30e1', '雜曲歌辭 出門行二首 二', '杂曲歌辞 出门行二首 二', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["海風蕭蕭天雨霜，窮愁獨坐夜何長？","驅車舊憶太行險，始知遊子悲故鄉。","美人相思隔天闕，長望雲端不可越。","手持琅玕欲有贈，愛而不見心斷絕。","南山峨峨白石爛，碧海之波浩漫漫。","參辰出沒不相待，我欲橫天無羽翰。"]', '["海风蕭蕭天雨霜，窮愁独坐夜何长？","驱车旧憶太行險，始知游子悲故乡。","美人相思隔天闕，长望云端不可越。","手持琅玕欲有贈，愛而不见心斷絕。","南山峨峨白石爛，碧海之波浩漫漫。","參辰出沒不相待，我欲橫天無羽翰。"]', '诗', 'shi', '', NULL, '雜曲歌辭 出門行二首 二 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fd9bf41-ae6c-4def-aa3e-e6c92abc811f', '雜曲歌辭 出門行', '杂曲歌辞 出门行', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["兄弟同出門，同行不同志。","悽悽分岐路，各各營所爲。","兄上荆山巔，翻石辨虹氣。","弟沈滄海底，偷珠待龍睡。","出門不數年，同歸亦同遂。","俱用私所珍，升沈自茲異。","獻珠龍王宮，值龍覓珠次。","但喜復得珠，不求珠所自。","酬客雙龍女，授客六龍轡。","遣充行雨神，雨澤隨客意。","雩夏鐘鼓繁，禜秋玉帛積。","彩色畫廊廟，奴僮被珠翠。","驥騄千萬雙，鴛鴦七十二。","言者禾稼枯，無人敢輕議。","其兄因獻璞，再刖不履地。","門戶親戚疎，匡牀妻妾棄。","銘心有所待，視足無所愧。","持璞自枕頭，淚痕雙血漬。","一朝龍醒寤，本問偷珠事。","因知行雨偏，妻子五刑備。","仁兄捧屍哭，勢友掉頭諱。","喪車黔首葬，弔客青蠅至。","楚有望氣人，王前忽長跪。","賀王得貴寶，不遠王所莅。","求之果如言，剖則浮雲膩。","白珩無顏色，垂棘有瑕累。","在楚列地封，入趙連城貴。","秦遣李斯書，書爲傳國瑞。","秦亡漢魏傳，傳者得神器。","卞和名永永，與寶不相墜。","勸爾出門行，行難莫行易。","易得還易失，難同亦難離。","善賈識貪廉，良田無稙穉。","磨劒莫磨錐，磨錐成小利。"]', '["兄弟同出门，同行不同志。","悽悽分岐路，各各營所爲。","兄上荆山巔，翻石辨虹氣。","弟沈滄海底，偷珠待龙睡。","出门不數年，同归亦同遂。","俱用私所珍，升沈自茲異。","獻珠龙王宮，值龙覓珠次。","但喜复得珠，不求珠所自。","酬客雙龙女，授客六龙轡。","遣充行雨神，雨澤隨客意。","雩夏鐘鼓繁，禜秋玉帛積。","彩色畫廊廟，奴僮被珠翠。","驥騄千万雙，鴛鴦七十二。","言者禾稼枯，無人敢轻議。","其兄因獻璞，再刖不履地。","门戶親戚疎，匡牀妻妾棄。","銘心有所待，視足無所愧。","持璞自枕头，泪痕雙血漬。","一朝龙醒寤，本问偷珠事。","因知行雨偏，妻子五刑備。","仁兄捧屍哭，勢友掉头諱。","喪车黔首葬，弔客青蠅至。","楚有望氣人，王前忽长跪。","賀王得貴寶，不远王所莅。","求之果如言，剖則浮云膩。","白珩無顏色，垂棘有瑕累。","在楚列地封，入趙連城貴。","秦遣李斯书，书爲傳国瑞。","秦亡漢魏傳，傳者得神器。","卞和名永永，與寶不相墜。","勸爾出门行，行难莫行易。","易得還易失，难同亦难離。","善賈識貪廉，良田無稙穉。","磨劒莫磨錐，磨錐成小利。"]', '诗', 'shi', '', NULL, '雜曲歌辭 出門行 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f49d949-dffa-43ef-a250-75f80a49f914', '雜曲歌辭 出自薊北門行', '杂曲歌辞 出自薊北门行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["虜陣橫北荒，胡星曜精芒。","羽書速驚電，烽火晝連光。","虎竹救邊急，戎車森已行。","明主不安席，按劒心飛揚。","推轂出猛將，連旗登戰場。","兵威衝絕漠，殺氣凌穹蒼。","列卒赤山下，開營紫塞傍。","途冬沙風緊，旌旗颯凋傷。","[畫]角悲海月，征衣卷天霜。","揮刃斬樓蘭，彎弓射賢王。","單于一平蕩，種落自奔亡。","收功報天子，行歌歸咸陽。"]', '["虜陣橫北荒，胡星曜精芒。","羽书速驚電，烽火晝連光。","虎竹救邊急，戎车森已行。","明主不安席，按劒心飞揚。","推轂出猛將，連旗登戰場。","兵威衝絕漠，殺氣凌穹蒼。","列卒赤山下，开營紫塞傍。","途冬沙风緊，旌旗颯凋傷。","[畫]角悲海月，征衣卷天霜。","揮刃斬楼蘭，彎弓射賢王。","單于一平蕩，種落自奔亡。","收功報天子，行歌归咸陽。"]', '诗', 'shi', '', NULL, '雜曲歌辭 出自薊北門行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79bf2cc4-024c-4e4c-bb59-62e5c8f333d7', '雜曲歌辭 薊門行五首 一', '杂曲歌辞 薊门行五首 一', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["邊城十一月，雨雪亂霏霏。","元戎號令嚴，人馬亦輕肥。","羌胡無盡日，征戰幾人歸。"]', '["邊城十一月，雨雪亂霏霏。","元戎號令嚴，人马亦轻肥。","羌胡無尽日，征戰幾人归。"]', '诗', 'shi', '', NULL, '雜曲歌辭 薊門行五首 一 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('697c1c85-a50d-494b-8319-013009006006', '雜曲歌辭 薊門行五首 二', '杂曲歌辞 薊门行五首 二', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["幽州多騎射，結髮重橫行。","一朝事將軍，出入有聲名。","紛紛獵秋草，相向角弓鳴。"]', '["幽州多騎射，結髮重橫行。","一朝事將軍，出入有声名。","紛紛獵秋草，相向角弓鳴。"]', '诗', 'shi', '', NULL, '雜曲歌辭 薊門行五首 二 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfc7bc0d-8f02-4987-a99c-b18d95073829', '雜曲歌辭 薊門行五首 三', '杂曲歌辞 薊门行五首 三', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["薊門逢古老，獨立思氛氳。","一身既零丁，頭鬢白紛紛。","勳庸今已矣，不識霍將軍。"]', '["薊门逢古老，独立思氛氳。","一身既零丁，头鬢白紛紛。","勳庸今已矣，不識霍將軍。"]', '诗', 'shi', '', NULL, '雜曲歌辭 薊門行五首 三 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('571e88d5-df2d-4c4a-bedf-5faea8b44382', '雜曲歌辭 薊門行五首 四', '杂曲歌辞 薊门行五首 四', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["茫茫長城外，日沒更煙塵。","胡騎雖憑陵，漢兵不顧身。","古樹滿空塞，黃雲愁殺人。"]', '["茫茫长城外，日沒更煙塵。","胡騎雖憑陵，漢兵不顧身。","古樹满空塞，黄云愁殺人。"]', '诗', 'shi', '', NULL, '雜曲歌辭 薊門行五首 四 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('182de17f-2ad0-4afb-be82-3891ea7b55b1', '雜曲歌辭 薊門行五首 五', '杂曲歌辞 薊门行五首 五', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["漢家能用武，開拓窮異域。","戍卒厭糠覈，降胡飽衣食。","開亭試一望，吾欲涕霑臆。"]', '["漢家能用武，开拓窮異域。","戍卒厭糠覈，降胡飽衣食。","开亭試一望，吾欲涕霑臆。"]', '诗', 'shi', '', NULL, '雜曲歌辭 薊門行五首 五 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('888e21ea-f3bc-4453-83b8-2048410e3b91', '雜曲歌辭 薊門行', '杂曲歌辞 薊门行', '4954b3c6-757a-44f4-9f1e-a3693107a677', '唐', '["旄頭有精芒，胡騎獵秋草。","羽檄南渡河，邊庭用兵早。","漢家愛征戰，宿將今已老。","辛苦羽林兒，從戎榆關道。","一身救邊速，烽火連薊門。","前軍鳥飛斷，格鬬塵沙昏。","寒日鼓聲急，單于夜火奔。","當須徇忠義，身死報國恩。"]', '["旄头有精芒，胡騎獵秋草。","羽檄南渡河，邊庭用兵早。","漢家愛征戰，宿將今已老。","辛苦羽林兒，從戎榆关道。","一身救邊速，烽火連薊门。","前軍鸟飞斷，格鬬塵沙昏。","寒日鼓声急，單于夜火奔。","當須徇忠義，身死報国恩。"]', '诗', 'shi', '', NULL, '雜曲歌辭 薊門行 李希仲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9aab1a47-7626-4ca7-af13-80ec5bc8e741', '雜曲歌辭 君子有所思行', '杂曲歌辞 君子有所思行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["紫閣連終南，青冥天倪色。","憑崖望咸陽，宮闕羅北極。","萬井驚畫出，九衢如弦直。","渭水清銀河，橫天流不息。","朝野盛文物，衣冠何翕赩。","廐馬散連山，軍容威絕域。","伊皐運元化，衛霍輸筋力。","歌鐘樂未休，榮去老還逼。","圓光過滿缺，太陽移中昃。","不散東海金，何爭西輝匿。","無作牛山悲，惻愴淚霑臆。"]', '["紫閣連終南，青冥天倪色。","憑崖望咸陽，宮闕羅北極。","万井驚畫出，九衢如弦直。","渭水清銀河，橫天流不息。","朝野盛文物，衣冠何翕赩。","廐马散連山，軍容威絕域。","伊皐運元化，衛霍輸筋力。","歌鐘乐未休，榮去老還逼。","圓光過满缺，太陽移中昃。","不散东海金，何爭西輝匿。","無作牛山悲，惻愴泪霑臆。"]', '诗', 'shi', '', NULL, '雜曲歌辭 君子有所思行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('664ccc00-6def-413f-94ac-733c4ec9b6c1', '雜曲歌辭 君子有所思行 一', '杂曲歌辞 君子有所思行 一', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["我愛正考甫，思賢作商頌。","我愛揚子雲，理亂皆如鳳。","振衣中夜起，露花香旖旎。","撲碎驪龍明月珠，敲出鳳凰五色髓。","陋卷蕭蕭風淅淅，緬想斯人勝珪璧。","寂寥千載不相逢，無限區區盡虛擲。","君不見沈約道，佳人不在茲，春光爲誰惜。"]', '["我愛正考甫，思賢作商頌。","我愛揚子云，理亂皆如鳳。","振衣中夜起，露花香旖旎。","撲碎驪龙明月珠，敲出鳳凰五色髓。","陋卷蕭蕭风淅淅，緬想斯人勝珪璧。","寂寥千載不相逢，無限區區尽虛擲。","君不见沈約道，佳人不在茲，春光爲誰惜。"]', '诗', 'shi', '', NULL, '雜曲歌辭 君子有所思行 一 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36ccc570-092d-4e94-932d-43f019f20802', '雜曲歌辭 君子有所思行 二', '杂曲歌辞 君子有所思行 二', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["安得龍猛筆，點石爲黃金。","散問酷吏家，使無貪殘心。","甘棠密葉成翠幄，潁鳳不來天地塞。","所以傾城人，如今不可得。"]', '["安得龙猛笔，点石爲黄金。","散问酷吏家，使無貪殘心。","甘棠密葉成翠幄，潁鳳不来天地塞。","所以傾城人，如今不可得。"]', '诗', 'shi', '', NULL, '雜曲歌辭 君子有所思行 二 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82166154-7317-4617-a50c-a9a5a2896da3', '雜曲歌辭 傷歌行', '杂曲歌辞 傷歌行', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["黃門詔下促收捕，京兆君繫御史府。","出門無復部曲隨，親戚相逢不容語。","辭成謫尉南海州，受命不得須臾留。","身著青衫騎惡馬，東門之東無送者。","郵夫防吏急喧驅，往往驚墮馬蹏下。","長安里中荒大宅，朱門已除十二戟。","高堂舞榭鎖管弦，美人遙望西南天。"]', '["黄门詔下促收捕，京兆君繫御史府。","出门無复部曲隨，親戚相逢不容語。","辞成謫尉南海州，受命不得須臾留。","身著青衫騎惡马，东门之东無送者。","郵夫防吏急喧驱，往往驚墮马蹏下。","长安里中荒大宅，朱门已除十二戟。","高堂舞榭鎖管弦，美人遙望西南天。"]', '诗', 'shi', '', NULL, '雜曲歌辭 傷歌行 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ba3b183-531e-48da-aa22-cacc3936e6aa', '雜曲歌辭 傷歌行', '杂曲歌辞 傷歌行', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["衆毒蔓貞松，一枝難久榮。","豈知黃庭客，仙骨生不成。","春色舍芳蕙，秋風遶枯莖。","彈琴不成曲，始覺知音傾。","館月改舊照，弔賓寫餘情。","還舟空江上，波浪送銘旌。"]', '["衆毒蔓貞松，一枝难久榮。","豈知黄庭客，仙骨生不成。","春色舍芳蕙，秋风遶枯莖。","彈琴不成曲，始覺知音傾。","館月改旧照，弔賓寫餘情。","還舟空江上，波浪送銘旌。"]', '诗', 'shi', '', NULL, '雜曲歌辭 傷歌行 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('217032c7-c751-4c94-8b3b-b1b3417dcac7', '雜曲歌辭 傷歌行', '杂曲歌辞 傷歌行', '998a453e-7ad8-44a7-ac68-91abf4146a26', '唐', '["兔走鳥飛不相見，人事依稀速如電。","王母夭桃一度開，玉樓紅粉千回變。","車馳馬走咸陽道，石家舊宅空荒草。","秋雨無情不惜花，芙蓉一一驚香倒。","勸君莫謾栽荆棘，秦皇虛費驅山力。","英風一去更無言，白骨沈埋暮山碧。"]', '["兔走鸟飞不相见，人事依稀速如電。","王母夭桃一度开，玉楼紅粉千回变。","车驰马走咸陽道，石家旧宅空荒草。","秋雨無情不惜花，芙蓉一一驚香倒。","勸君莫謾栽荆棘，秦皇虛費驱山力。","英风一去更無言，白骨沈埋暮山碧。"]', '诗', 'shi', '', NULL, '雜曲歌辭 傷歌行 莊南傑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c9fcb36-9e32-4ad9-8e44-eafc1df1b2a3', '雜曲歌辭 悲歌', '杂曲歌辞 悲歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["悲來乎，悲來乎！主人有酒且莫斟，聽我一曲悲來吟。","悲來不吟還不笑，天下無人知我心。","君有數斗酒，我有三尺琴。","琴鳴酒樂兩相得，一杯不啻千鈞金。","悲來乎，悲來乎！天雖長，地雖久，金玉滿堂應不守。","富貴百年能幾何？死生一度人皆有。","孤猨坐啼墳上月，且須一盡杯中酒。","悲來乎，悲來乎！鳳鳥不至河無圖，微子去之箕子奴。","漢帝不憶李將軍，楚王放却屈大夫。","悲來乎，悲來乎！秦家李斯早追悔，虛名撥向身之外。","范子何曾愛五湖，功成名遂身自退。","劒是一夫用，書能知姓名。","惠施不肯干萬乘，卜式未必窮一經。","還須黑頭取方伯，莫謾白首爲儒生。"]', '["悲来乎，悲来乎！主人有酒且莫斟，听我一曲悲来吟。","悲来不吟還不笑，天下無人知我心。","君有數斗酒，我有三尺琴。","琴鳴酒乐兩相得，一杯不啻千鈞金。","悲来乎，悲来乎！天雖长，地雖久，金玉满堂應不守。","富貴百年能幾何？死生一度人皆有。","孤猨坐啼墳上月，且須一尽杯中酒。","悲来乎，悲来乎！鳳鸟不至河無圖，微子去之箕子奴。","漢帝不憶李將軍，楚王放却屈大夫。","悲来乎，悲来乎！秦家李斯早追悔，虛名撥向身之外。","范子何曾愛五湖，功成名遂身自退。","劒是一夫用，书能知姓名。","惠施不肯干万乘，卜式未必窮一經。","還須黑头取方伯，莫謾白首爲儒生。"]', '诗', 'shi', '', NULL, '雜曲歌辭 悲歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c257f77-fbd5-4f89-a01d-f069cc2189b2', '雜曲歌辭 悲哉行', '杂曲歌辞 悲哉行', 'aafdb19f-05e9-4e14-911a-2b39ebf7f1af', '唐', '["孤兒去慈親，遠客喪主人。","莫吟苦辛曲，誰忍聞可聞。","可聞不可說，去去無期別。","行人念前程，不待參辰沒。","朝亦常苦飢，暮亦常苦飢。","飄飄萬餘里，貧賤多是非。","少年莫遠遊，遠遊多不歸。"]', '["孤兒去慈親，远客喪主人。","莫吟苦辛曲，誰忍闻可闻。","可闻不可说，去去無期別。","行人念前程，不待參辰沒。","朝亦常苦飢，暮亦常苦飢。","飄飄万餘里，貧賤多是非。","少年莫远游，远游多不归。"]', '诗', 'shi', '', NULL, '雜曲歌辭 悲哉行 孟雲卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21781aca-5d96-4c9e-9bc1-ed8140e1107b', '雜曲歌辭 悲哉行', '杂曲歌辞 悲哉行', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["悲哉爲儒者，力學不能疲。","讀書眼欲暗，秉筆手生胝。","十上方一第，成名常苦遲。","縱有宦達者，兩鬢已成絲。","可憐少壯日，適在窮賤時。","丈夫老且病，焉用富貴爲。","沈沈朱門宅，中有乳臭兒。","狀貌如婦人，光明膏粱肌。","手不把書卷，身不擐戎衣。","二十襲封爵，門承勳戚資。","春來日日出，服御何輕肥。","朝從博徒飲，暮有倡樓期。","評封還酒債，堆金選蛾眉。","聲色狗馬外，其餘一無知。","山苗與澗松，地勢隨高卑。","古來無奈何，非君獨傷悲。"]', '["悲哉爲儒者，力学不能疲。","读书眼欲暗，秉笔手生胝。","十上方一第，成名常苦遲。","縱有宦達者，兩鬢已成絲。","可怜少壯日，適在窮賤时。","丈夫老且病，焉用富貴爲。","沈沈朱门宅，中有乳臭兒。","狀貌如婦人，光明膏粱肌。","手不把书卷，身不擐戎衣。","二十襲封爵，门承勳戚資。","春来日日出，服御何轻肥。","朝從博徒饮，暮有倡楼期。","評封還酒債，堆金選蛾眉。","声色狗马外，其餘一無知。","山苗與澗松，地勢隨高卑。","古来無奈何，非君独傷悲。"]', '诗', 'shi', '', NULL, '雜曲歌辭 悲哉行 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd8c3590-e097-4289-bcda-ad852ed095ab', '雜曲歌辭 悲哉行', '杂曲歌辞 悲哉行', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["促促晨復昏，死生同一源。","貴年不懼老，賤老傷久存。","朗朗哭前歌，絳旌引幽魂。","來爲千金子，去臥百草根。","黃土塞生路，悲風送回轅。","金鞍舊良馬，四顧不出門。","生結千歲念，榮及百代孫。","黃金買性命，白刃讐一言。","寧知北山上，松柏侵田園。"]', '["促促晨复昏，死生同一源。","貴年不懼老，賤老傷久存。","朗朗哭前歌，絳旌引幽魂。","来爲千金子，去臥百草根。","黄土塞生路，悲风送回轅。","金鞍旧良马，四顧不出门。","生結千歲念，榮及百代孫。","黄金買性命，白刃讐一言。","寧知北山上，松柏侵田园。"]', '诗', 'shi', '', NULL, '雜曲歌辭 悲哉行 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad84f24a-7552-4e1d-ac0e-8e74b824f807', '雜曲歌辭 妾薄命', '杂曲歌辞 妾薄命', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["雖入秦帝宮，不上秦帝牀。","夜夜玉窗裏，與他卷羅裳。"]', '["雖入秦帝宮，不上秦帝牀。","夜夜玉窗裏，與他卷羅裳。"]', '诗', 'shi', '', NULL, '雜曲歌辭 妾薄命 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ba1642b-a69c-4d3a-87ac-fd019f934922', '雜曲歌辭 妾薄命', '杂曲歌辞 妾薄命', '2d883805-5c5b-4bdf-9122-62fa17ee1f6e', '唐', '["有女妖且麗，裴回湘水湄。","水湄蘭杜芳，采之將寄誰。","瓠犀發皓齒，雙蛾嚬翠眉。","紅臉如開蓮，素膚若凝脂。","綽約多逸態，輕盈不自持。","常矜絕代色，復恃傾城姿。","子夫前入侍，飛燕復當時。","正悅掌中舞，寧哀團扇詩。","洛川昔云遇，高唐今尚違。","幽閤禽雀噪，閑階草露滋。","流景一何速，年華不可追。","解佩安何贈，怨咽空自悲。"]', '["有女妖且丽，裴回湘水湄。","水湄蘭杜芳，采之將寄誰。","瓠犀發皓齒，雙蛾嚬翠眉。","紅臉如开蓮，素膚若凝脂。","綽約多逸態，轻盈不自持。","常矜絕代色，复恃傾城姿。","子夫前入侍，飞燕复當时。","正悅掌中舞，寧哀團扇诗。","洛川昔云遇，高唐今尚違。","幽閤禽雀噪，闲階草露滋。","流景一何速，年华不可追。","解佩安何贈，怨咽空自悲。"]', '诗', 'shi', '', NULL, '雜曲歌辭 妾薄命 武平一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37b7744a-916c-481e-9420-6703ead41481', '雜曲歌辭 妾薄命', '杂曲歌辞 妾薄命', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["團扇秋風起，長門夜月明。","羞聞拊背人，恨說舞腰輕。","太常應已醉，劉君恆帶酲。","橫陳每虛設，吉夢竟何成。"]', '["團扇秋风起，长门夜月明。","羞闻拊背人，恨说舞腰轻。","太常應已醉，劉君恆带酲。","橫陳每虛設，吉梦竟何成。"]', '诗', 'shi', '', NULL, '雜曲歌辭 妾薄命 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83fb9c9b-7cdf-48cd-b03a-0c1102bf7728', '雜曲歌辭 妾薄命', '杂曲歌辞 妾薄命', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["草綠長門閉，苔青永巷幽。","寵移新愛奪，泣下故情留。","啼鳥驚殘夢，飛花攪獨愁。","自憐春色罷，團扇復迎秋。"]', '["草綠长门閉，苔青永巷幽。","寵移新愛奪，泣下故情留。","啼鸟驚殘梦，飞花攪独愁。","自怜春色罷，團扇复迎秋。"]', '诗', 'shi', '', NULL, '雜曲歌辭 妾薄命 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('362e9ec3-e452-4f59-b5f4-10757da34b28', '雜曲歌辭 妾薄命', '杂曲歌辞 妾薄命', '258a289f-2556-453e-8391-edca666a2b5e', '唐', '["自從離別守空閨，遙聞征戰起雲梯。","夜夜愁君遼海外，年年棄妾渭橋西。","陽春白日照空暖，紫燕銜花向庭滿。","綵鸞琴裏怨聲多，飛鵲鏡前妝梳斷。","誰家夫壻不從征，應是漁陽別有情。","莫道紅顏燕地少，家家還似洛陽城。","且逐新人殊未歸，還令秋至夜霜飛。","北斗星前橫度鴈，南樓月下擣寒衣。","夜深聞鴈腸欲絕，獨坐縫衣燈又滅。","暗啼羅帳空自憐，夢度陽關向誰說。","每憐容貌宛如神，如何薄命不勝人。","願君朝夕燕山至，好作明年楊柳春。"]', '["自從離別守空閨，遙闻征戰起云梯。","夜夜愁君遼海外，年年棄妾渭橋西。","陽春白日照空暖，紫燕銜花向庭满。","綵鸾琴裏怨声多，飞鵲镜前妝梳斷。","誰家夫壻不從征，應是漁陽別有情。","莫道紅顏燕地少，家家還似洛陽城。","且逐新人殊未归，還令秋至夜霜飞。","北斗星前橫度鴈，南楼月下擣寒衣。","夜深闻鴈腸欲絕，独坐縫衣灯又滅。","暗啼羅帳空自怜，梦度陽关向誰说。","每怜容貌宛如神，如何薄命不勝人。","願君朝夕燕山至，好作明年楊柳春。"]', '诗', 'shi', '', NULL, '雜曲歌辭 妾薄命 劉元淑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11470667-67f3-4142-b415-e82d74b30252', '雜曲歌辭 妾薄命', '杂曲歌辞 妾薄命', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["漢帝重阿嬌，貯之黃金屋。","咳唾落九天，隨風生珠玉。","寵極愛還歇，妒深情却疎。","長門一步地，不肯暫回車。","雨落不上天，水覆難再收。","君情與妾意，各自東西流。","昔日芙蓉花，今成斷根草。","以色事他人，能得幾時好。"]', '["漢帝重阿嬌，貯之黄金屋。","咳唾落九天，隨风生珠玉。","寵極愛還歇，妒深情却疎。","长门一步地，不肯暫回车。","雨落不上天，水覆难再收。","君情與妾意，各自东西流。","昔日芙蓉花，今成斷根草。","以色事他人，能得幾时好。"]', '诗', 'shi', '', NULL, '雜曲歌辭 妾薄命 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('973d6b4b-6a53-4d6c-a900-b187c8eb569a', '雜曲歌辭 妾薄命', '杂曲歌辞 妾薄命', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["不惜十指弦，爲君千萬彈。","常恐新聲至，坐使故聲殘。","棄置今日悲，即是昨日歡。","將新變故易，持故爲新難。","青山有蘼蕪，淚葉長不乾。","空令後代人，采掇幽思攢。"]', '["不惜十指弦，爲君千万彈。","常恐新声至，坐使故声殘。","棄置今日悲，即是昨日歡。","將新变故易，持故爲新难。","青山有蘼蕪，泪葉长不乾。","空令後代人，采掇幽思攢。"]', '诗', 'shi', '', NULL, '雜曲歌辭 妾薄命 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9d02cdb-7dc0-436a-a758-e29b65bb461b', '雜曲歌辭 妾薄命', '杂曲歌辞 妾薄命', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["薄命婦，良家子，無事從軍去萬里。","漢家天子平四夷，護羌都尉裹屍歸。","念君此行爲死別，對君裁縫泉下衣。","與君一日爲夫婦，千年萬歲亦相守。","君愛龍城征戰功，妾願青樓歡樂同。","人生各各有所欲，詎得將心入君腹。"]', '["薄命婦，良家子，無事從軍去万里。","漢家天子平四夷，護羌都尉裹屍归。","念君此行爲死別，对君裁縫泉下衣。","與君一日爲夫婦，千年万歲亦相守。","君愛龙城征戰功，妾願青楼歡乐同。","人生各各有所欲，詎得將心入君腹。"]', '诗', 'shi', '', NULL, '雜曲歌辭 妾薄命 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8eb9a73-6985-4572-806d-733ed9452ff8', '雜曲歌辭 妾薄命三首 一', '杂曲歌辞 妾薄命三首 一', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["憶妾初嫁君，花鬟如綠雲。","回燈入綺帳，對面脫羅裙。","折步教人學，偷香與客熏。","容顏南國重，名字北方聞。","一從失恩意，轉覺身憔悴。","對鏡不梳頭，倚窗空落淚。","新人莫恃新，秋至會無春。","從來閉在長門者，必是宮中第一人。"]', '["憶妾初嫁君，花鬟如綠云。","回灯入綺帳，对面脫羅裙。","折步教人学，偷香與客熏。","容顏南国重，名字北方闻。","一從失恩意，轉覺身憔悴。","对镜不梳头，倚窗空落泪。","新人莫恃新，秋至會無春。","從来閉在长门者，必是宮中第一人。"]', '诗', 'shi', '', NULL, '雜曲歌辭 妾薄命三首 一 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fde07a47-7e59-407b-b7c9-f5d65ff73ecc', '雜曲歌辭 妾薄命三首 二', '杂曲歌辞 妾薄命三首 二', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["玉壘城邊爭走馬，銅蹏市裏共乘舟。","鳴環動佩思無盡，掩袖低巾淚不流。","疇昔將歌邀客醉，如今欲舞對君羞。","忍懷賤妾平生曲，獨上襄陽舊酒樓。"]', '["玉壘城邊爭走马，銅蹏市裏共乘舟。","鳴环动佩思無尽，掩袖低巾泪不流。","疇昔將歌邀客醉，如今欲舞对君羞。","忍懷賤妾平生曲，独上襄陽旧酒楼。"]', '诗', 'shi', '', NULL, '雜曲歌辭 妾薄命三首 二 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b80850c4-91b8-47bc-b9a7-7c51345c051e', '雜曲歌辭 妾薄命三首 三', '杂曲歌辞 妾薄命三首 三', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["自從君棄妾，憔悴不羞人。","惟餘壞粉淚，未免映衫勻。"]', '["自從君棄妾，憔悴不羞人。","惟餘壞粉泪，未免映衫勻。"]', '诗', 'shi', '', NULL, '雜曲歌辭 妾薄命三首 三 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8789639-b0e2-407b-bc97-844def8f9dc4', '雜曲歌辭 妾薄命', '杂曲歌辞 妾薄命', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["妾年初二八，兩度嫁狂夫。","薄命今猶在，堅貞掃地無。"]', '["妾年初二八，兩度嫁狂夫。","薄命今猶在，堅貞掃地無。"]', '诗', 'shi', '', NULL, '雜曲歌辭 妾薄命 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26d7090e-d22c-439c-9b47-5c3e2f2608e3', '雜曲歌辭 妾薄命', '杂曲歌辞 妾薄命', 'a7b71c66-84ae-4790-a9a8-a3e3c66ca279', '唐', '["君恩已斷盡成空，追想嬌歡恨莫窮。","長爲蕣華光曉日，誰知團扇送秋風。","黃金買賦心徒切，清路飛塵信莫通。","閑凭玉欄思舊事，幾回春暮泣殘紅。"]', '["君恩已斷尽成空，追想嬌歡恨莫窮。","长爲蕣华光晓日，誰知團扇送秋风。","黄金買賦心徒切，清路飞塵信莫通。","闲凭玉欄思旧事，幾回春暮泣殘紅。"]', '诗', 'shi', '', NULL, '雜曲歌辭 妾薄命 盧弼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da83e659-b95a-4cd4-b9ba-40f581921a90', '雜曲歌辭 妾薄命', '杂曲歌辞 妾薄命', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["阿嬌初失漢皇恩，舊賜羅衣亦罷熏。","欹枕夜悲金屋雨，卷簾朝泣玉樓雲。","宮前葉落鴛鴦瓦，架上塵生翡翠裙。","龍騎不巡時漸久，長門長掩綠苔文。"]', '["阿嬌初失漢皇恩，旧賜羅衣亦罷熏。","欹枕夜悲金屋雨，卷簾朝泣玉楼云。","宮前葉落鴛鴦瓦，架上塵生翡翠裙。","龙騎不巡时漸久，长门长掩綠苔文。"]', '诗', 'shi', '', NULL, '雜曲歌辭 妾薄命 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7c33d59-df0b-464e-b700-aec62a9a2795', '雜曲歌辭 妾薄命', '杂曲歌辞 妾薄命', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["薄命頭欲白，頻年嫁不成。","秦娥未十五，昨夜事公卿。","豈有機杼力，空傳歌舞名。","妾專修婦德，媒氏却相輕。"]', '["薄命头欲白，頻年嫁不成。","秦娥未十五，昨夜事公卿。","豈有機杼力，空傳歌舞名。","妾專修婦德，媒氏却相轻。"]', '诗', 'shi', '', NULL, '雜曲歌辭 妾薄命 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3683533a-058c-4b40-affa-2c1a9ca032d2', '雜曲歌辭 羽林行', '杂曲歌辞 羽林行', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["長安惡少出名字，樓下劫商樓上醉。","天明下直明光宮，散入五陵松柏中。","百回殺人身合死，赦書尚有收城功。","九衢一日消息定，鄉吏籍中重改姓。","出來依舊屬羽林，立在殿前射飛禽。"]', '["长安惡少出名字，楼下劫商楼上醉。","天明下直明光宮，散入五陵松柏中。","百回殺人身合死，赦书尚有收城功。","九衢一日消息定，乡吏籍中重改姓。","出来依旧屬羽林，立在殿前射飞禽。"]', '诗', 'shi', '', NULL, '雜曲歌辭 羽林行 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5c4e4d0-682a-4c8f-9756-c181dc9a52dc', '雜曲歌辭 羽林行', '杂曲歌辞 羽林行', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["朔雪寒斷指，朔風勁裂冰。","胡中射鵰者，此日猶不能。","翩翩羽林兒，錦臂飛蒼鷹。","揮鞭決白馬，走出黃河凌。"]', '["朔雪寒斷指，朔风勁裂冰。","胡中射鵰者，此日猶不能。","翩翩羽林兒，錦臂飞蒼鷹。","揮鞭決白马，走出黄河凌。"]', '诗', 'shi', '', NULL, '雜曲歌辭 羽林行 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('230aaaca-a890-41d0-a4b4-4dfc73f7a14a', '雜曲歌辭 羽林行', '杂曲歌辞 羽林行', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["朝出羽林宮，入參雲臺議。","獨請萬里行，不奏和親事。","君王重年少，深納開邊利。","寶馬雕玉鞍，一朝從萬騎。","煌煌都門外，祖帳光七貴。","歌鐘樂行軍，雲物慘別地。","簫笳整部曲，幢蓋動郊次。","臨風親戚懷，滿袖兒女淚。","行行復何贈，長劒報恩字。"]', '["朝出羽林宮，入參云台議。","独請万里行，不奏和親事。","君王重年少，深納开邊利。","寶马雕玉鞍，一朝從万騎。","煌煌都门外，祖帳光七貴。","歌鐘乐行軍，云物慘別地。","簫笳整部曲，幢蓋动郊次。","臨风親戚懷，满袖兒女泪。","行行复何贈，长劒報恩字。"]', '诗', 'shi', '', NULL, '雜曲歌辭 羽林行 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('402c5cc0-8255-4a01-8e5e-2641417bf8a2', '雜曲歌辭 白馬篇', '杂曲歌辞 白马篇', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["龍馬花雪毛，金鞍五陵豪。","秋霜切玉劒，落日明珠袍。","鬬雞事萬乘，軒蓋一何高。","弓摧宜山虎，手接泰山猱。","酒後競風彩，三杯弄寶刀。","殺人如翦草，劇孟同遊遨。","發憤去函谷，從軍向臨洮。","叱咤萬戰場，匈奴盡波濤。","歸來使酒氣，未肯拜蕭曹。","羞入原憲室，荒徑隱蓬蒿。"]', '["龙马花雪毛，金鞍五陵豪。","秋霜切玉劒，落日明珠袍。","鬬雞事万乘，軒蓋一何高。","弓摧宜山虎，手接泰山猱。","酒後競风彩，三杯弄寶刀。","殺人如翦草，劇孟同游遨。","發憤去函谷，從軍向臨洮。","叱咤万戰場，匈奴尽波濤。","归来使酒氣，未肯拜蕭曹。","羞入原憲室，荒徑隐蓬蒿。"]', '诗', 'shi', '', NULL, '雜曲歌辭 白馬篇 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4365fdc6-9e89-489c-abe1-4eda95a85062', '雜曲歌辭 升天行', '杂曲歌辞 升天行', '405848e7-8d14-42db-a593-f688fd279870', '唐', '["身不沈，骨不重，驅青鸞，駕白鳳。","幢蓋飄飄入冷空，天風瑟瑟星河動。","瑤闕參差阿母家，樓臺戲閉凝彤霞。","五三仙子乘龍車，堂前碾爛蟠桃花。","回頭却顧蓬山頂，一點濃嵐在深井。"]', '["身不沈，骨不重，驱青鸾，駕白鳳。","幢蓋飄飄入冷空，天风瑟瑟星河动。","瑤闕參差阿母家，楼台戲閉凝彤霞。","五三仙子乘龙车，堂前碾爛蟠桃花。","回头却顧蓬山頂，一点濃嵐在深井。"]', '诗', 'shi', '', NULL, '雜曲歌辭 升天行 僧齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d19a6b1-ec7b-4bfc-b393-0c4d431d82e2', '雜曲歌辭 神仙曲', '杂曲歌辞 神仙曲', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["碧峰海面藏靈書，上帝揀作神仙居。","晴時笑語聞空虛，鬬乘巨浪騎鯨魚。","春羅翦字邀王母，共宴紅樓最深處。","鶴羽衝風過海遲，不如卻使青龍去。","猶疑王母不相許，垂露娃鬟更傳語。"]', '["碧峰海面藏靈书，上帝揀作神仙居。","晴时笑語闻空虛，鬬乘巨浪騎鯨鱼。","春羅翦字邀王母，共宴紅楼最深处。","鹤羽衝风過海遲，不如卻使青龙去。","猶疑王母不相許，垂露娃鬟更傳語。"]', '诗', 'shi', '', NULL, '雜曲歌辭 神仙曲 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd66d8b3-abe6-4316-ab34-b88a4bb8bb83', '雜曲歌辭 北風行', '杂曲歌辞 北风行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["燭龍棲寒門，光曜猶旦開。","日月照之何不及此，惟有北風怒號天上來。","燕山雪花大如席，片片吹落軒轅臺。","幽州思婦十二月，停歌罷笑雙蛾摧。","倚門望行人，念君長城苦寒良可哀。","別時提劒救邊去，遺此虎文金髀釵。","中有一雙白羽箭，蜘蛛結網生塵埃。","箭空在，人今戰死不復迴。","不忍見此物，焚之已成灰。","黃河捧土尚可塞，北風雨雪恨難裁。"]', '["燭龙棲寒门，光曜猶旦开。","日月照之何不及此，惟有北风怒號天上来。","燕山雪花大如席，片片吹落軒轅台。","幽州思婦十二月，停歌罷笑雙蛾摧。","倚门望行人，念君长城苦寒良可哀。","別时提劒救邊去，遺此虎文金髀釵。","中有一雙白羽箭，蜘蛛結網生塵埃。","箭空在，人今戰死不复迴。","不忍见此物，焚之已成灰。","黄河捧土尚可塞，北风雨雪恨难裁。"]', '诗', 'shi', '', NULL, '雜曲歌辭 北風行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3a972d4-cd1c-4b14-b1a5-77ddcf3f02f8', '雜曲歌辭 苦熱行', '杂曲歌辞 苦熱行', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["赤日滿天地，火雲成山嶽。","草木盡焦卷，川澤皆竭涸。","輕紈覺衣重，密樹苦陰薄。","莞簟不可近，絺綌再三濯。","思出宇宙外，曠然在寥廓。","長風萬里來，江海蕩煩濁。","却顧身爲患，始知心未覺。","忽入甘露門，宛然清涼樂。"]', '["赤日满天地，火云成山嶽。","草木尽焦卷，川澤皆竭涸。","轻紈覺衣重，密樹苦陰薄。","莞簟不可近，絺綌再三濯。","思出宇宙外，曠然在寥廓。","长风万里来，江海蕩煩濁。","却顧身爲患，始知心未覺。","忽入甘露门，宛然清涼乐。"]', '诗', 'shi', '', NULL, '雜曲歌辭 苦熱行 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('736e1080-b7ce-4a2f-9e8c-8ba28fd28de9', '雜曲歌辭 苦熱行', '杂曲歌辞 苦熱行', '96b87115-9522-4659-92a6-83e4aec4f244', '唐', '["祝融南來鞭火龍，火旗焰焰燒天紅。","日輪當午凝不去，萬國如在洪爐中。","五嶽翠乾雲彩滅，陽侯海底愁波竭。","何當一夕金風發？爲我掃却天下熱。"]', '["祝融南来鞭火龙，火旗焰焰燒天紅。","日輪當午凝不去，万国如在洪爐中。","五嶽翠乾云彩滅，陽侯海底愁波竭。","何當一夕金风發？爲我掃却天下熱。"]', '诗', 'shi', '', NULL, '雜曲歌辭 苦熱行 王轂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e3ea889-0643-4291-90bb-41e29b0151c5', '雜曲歌辭 苦熱行', '杂曲歌辞 苦熱行', 'd031d511-00fb-47fd-8345-864309b121e2', '唐', '["六月金數伏，茲辰日在庚。","炎曦曝肌膚，毒霧昏檐楹。","安得奮翅翮，超遙出雲征。","不知天地心，如何匠生成。","火德燒百卉，瑤草不及榮。","省客當此時，忽貽懷中瓊。","捧翫煩袂滌，嘯歌美風生。","遲君佐元氣，調使四序平。","中令霜不祅，火餘氣常貞。","江南詩騷客，休吟苦熱行。"]', '["六月金數伏，茲辰日在庚。","炎曦曝肌膚，毒霧昏檐楹。","安得奮翅翮，超遙出云征。","不知天地心，如何匠生成。","火德燒百卉，瑤草不及榮。","省客當此时，忽貽懷中瓊。","捧翫煩袂滌，嘯歌美风生。","遲君佐元氣，調使四序平。","中令霜不祅，火餘氣常貞。","江南诗騷客，休吟苦熱行。"]', '诗', 'shi', '', NULL, '雜曲歌辭 苦熱行 僧皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13b0c8fc-cd4b-43c1-aed7-6d7224438823', '雜曲歌辭 苦熱行', '杂曲歌辞 苦熱行', '405848e7-8d14-42db-a593-f688fd279870', '唐', '["離宮劃開赤帝怒，喝起六龍奔日馭。","下土熬熬若煎煮，蒼生惶惶無處處。","火雲崢嶸焚泬寥，東皐老農腸欲焦。","何當一雨蘇我苗？爲君擊壞歌帝堯。"]', '["離宮劃开赤帝怒，喝起六龙奔日馭。","下土熬熬若煎煮，蒼生惶惶無处处。","火云崢嶸焚泬寥，东皐老農腸欲焦。","何當一雨蘇我苗？爲君擊壞歌帝堯。"]', '诗', 'shi', '', NULL, '雜曲歌辭 苦熱行 僧齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b5df95c-2080-4a03-9c87-7a53cad39113', '雜曲歌辭 太行苦熱行', '杂曲歌辞 太行苦熱行', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["迢迢太行路，自古稱險惡。","千騎儼欲前，羣峯望如削。","火雲從中起，仰視飛鳥落。","汗馬臥高原，危旌倚長薄。","清風何不至？赤日方煎爍。","石露山木焦，鱗窮水泉涸。","九重今旰食，萬里傳明略。","諸將候軒車，元兇愁鼎鑊。","何勞短兵接，自有長纓縛。","通越事豈難，渡瀘功未博。","朝辭羊腸坂，夕望貝丘郭。","漳水斜遶營，常山遙入幕。","永懷姑蘇下，因寄建安作。","白雪和誠難，滄波意空託。","陳琳書記好，王粲從軍樂。","早晚歸漢庭，隨君上麟閣。"]', '["迢迢太行路，自古稱險惡。","千騎儼欲前，羣峯望如削。","火云從中起，仰視飞鸟落。","汗马臥高原，危旌倚长薄。","清风何不至？赤日方煎爍。","石露山木焦，鱗窮水泉涸。","九重今旰食，万里傳明略。","諸將候軒车，元兇愁鼎鑊。","何勞短兵接，自有长纓縛。","通越事豈难，渡瀘功未博。","朝辞羊腸坂，夕望貝丘郭。","漳水斜遶營，常山遙入幕。","永懷姑蘇下，因寄建安作。","白雪和誠难，滄波意空託。","陳琳书記好，王粲從軍乐。","早晚归漢庭，隨君上麟閣。"]', '诗', 'shi', '', NULL, '雜曲歌辭 太行苦熱行 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bf64938-ec5a-4d0e-bcbc-2e6a0f024489', '雜曲歌辭 太行苦熱行', '杂曲歌辞 太行苦熱行', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["駟馬上太行，修途亙遼碣。","王程無留駕，日昃未遑歇。","請問此何時，恢台朱明月。","長蛇稽天討，上將方北伐。","明主命使臣，皇華得時傑。","已忘羊腸險，豈憚溫風入。","搖策汗滂沲，登崖思紆結。","炎雲如煙火，溪谷將恐竭。","晝景赩可畏，涼飆何由發？","山長飛鳥墮，目極行車絕。","趙魏方俶擾，安危俟明哲。","歸路豈不懷，飲冰有苦節。","會同傳檄至，疑議立談決。","況有阮元瑜，翩翩秉書札。","起予歌赤坂，永好踰白雪。","維念剖竹人，無因執羈紲。"]', '["駟马上太行，修途亙遼碣。","王程無留駕，日昃未遑歇。","請问此何时，恢台朱明月。","长蛇稽天討，上將方北伐。","明主命使臣，皇华得时傑。","已忘羊腸險，豈憚溫风入。","搖策汗滂沲，登崖思紆結。","炎云如煙火，溪谷將恐竭。","晝景赩可畏，涼飆何由發？","山长飞鸟墮，目極行车絕。","趙魏方俶擾，安危俟明哲。","归路豈不懷，饮冰有苦節。","會同傳檄至，疑議立談決。","況有阮元瑜，翩翩秉书札。","起予歌赤坂，永好踰白雪。","維念剖竹人，無因執羈紲。"]', '诗', 'shi', '', NULL, '雜曲歌辭 太行苦熱行 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb55e33f-ee4d-4b88-a23f-280fd0cfd271', '雜曲歌辭 春日行', '杂曲歌辞 春日行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["深宮高樓入紫清，金作蛟龍盤繡楹。","佳人當窗弄白日，弦將手語彈鳴箏。","春風吹落君王耳，此曲乃是升天行。","因出天池汎蓬瀛，樓船蹙沓波浪驚。","三千雙蛾獻歌笑，撾鐘考鼓宮殿傾。","萬姓聚舞歌太平，我無爲，人自寧。","三十六帝欲相迎，仙人飄翩下雲軿。","帝不去，留鎬京。","安能爲軒轅，獨往入窅冥。","小臣拜獻南山壽，陛下萬古垂鴻名。"]', '["深宮高楼入紫清，金作蛟龙盤繡楹。","佳人當窗弄白日，弦將手語彈鳴箏。","春风吹落君王耳，此曲乃是升天行。","因出天池汎蓬瀛，楼船蹙沓波浪驚。","三千雙蛾獻歌笑，撾鐘考鼓宮殿傾。","万姓聚舞歌太平，我無爲，人自寧。","三十六帝欲相迎，仙人飄翩下云軿。","帝不去，留鎬京。","安能爲軒轅，独往入窅冥。","小臣拜獻南山壽，陛下万古垂鴻名。"]', '诗', 'shi', '', NULL, '雜曲歌辭 春日行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5180277d-a3b2-4644-9f1f-2d5a4af7c604', '雜曲歌辭 春日行', '杂曲歌辞 春日行', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["春日融融池上暖，竹牙出土蘭心短。","草堂晨起酒半醒，家僮報我園花滿。","頭上皮冠未曾整，直入花間不尋徑。","樹樹殷勤盡遶行，舉枝未徧春日暝。","不用積金著青天，不用服藥求神仙。","但願園裏花長好，一生飲酒花前老。"]', '["春日融融池上暖，竹牙出土蘭心短。","草堂晨起酒半醒，家僮報我园花满。","头上皮冠未曾整，直入花间不尋徑。","樹樹殷勤尽遶行，舉枝未徧春日暝。","不用積金著青天，不用服藥求神仙。","但願园裏花长好，一生饮酒花前老。"]', '诗', 'shi', '', NULL, '雜曲歌辭 春日行 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c35c203f-69aa-42f9-ba07-77e7ea2975f5', '雜曲歌辭 朗月行', '杂曲歌辞 朗月行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["小時不識月，呼作白玉盤。","又疑瑤臺鏡，飛在青雲端。","仙人垂兩足，桂樹作團團。","白兔擣藥成，問言與誰餐。","蟾蜍蝕圜影，天明夜已殘。","羿昔落九烏，天人清且安。","陰精此淪惑，去去不足觀。","憂來其如何？惻愴摧心肝。"]', '["小时不識月，呼作白玉盤。","又疑瑤台镜，飞在青云端。","仙人垂兩足，桂樹作團團。","白兔擣藥成，问言與誰餐。","蟾蜍蝕圜影，天明夜已殘。","羿昔落九烏，天人清且安。","陰精此淪惑，去去不足观。","憂来其如何？惻愴摧心肝。"]', '诗', 'shi', '', NULL, '雜曲歌辭 朗月行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('152344f5-238d-42e9-9b7e-3476310e1b35', '雜曲歌辭 前有一尊酒行二首 一', '杂曲歌辞 前有一尊酒行二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["春風東來忽相過，金尊綠酒生微波。","落花紛紛稍覺多，美人欲醉朱顏酡。","青軒桃李能幾何？流光欺人忽蹉跎。","君起舞，日西夕，當年意氣不肯傾，白髮如絲歎何益。"]', '["春风东来忽相過，金尊綠酒生微波。","落花紛紛稍覺多，美人欲醉朱顏酡。","青軒桃李能幾何？流光欺人忽蹉跎。","君起舞，日西夕，當年意氣不肯傾，白髮如絲歎何益。"]', '诗', 'shi', '', NULL, '雜曲歌辭 前有一尊酒行二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0882a5d4-0b22-4bfa-80c3-2a39bd5a841d', '雜曲歌辭 前有一尊酒行二首 二', '杂曲歌辞 前有一尊酒行二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["琴奏龍門之綠桐，玉壺美酒清若空。","催弦拂柱與君飲，看朱成碧顏始紅。","胡姬貌如花，當鑪笑春風。","笑春風，舞羅衣，君今不醉欲安歸。"]', '["琴奏龙门之綠桐，玉壺美酒清若空。","催弦拂柱與君饮，看朱成碧顏始紅。","胡姬貌如花，當鑪笑春风。","笑春风，舞羅衣，君今不醉欲安归。"]', '诗', 'shi', '', NULL, '雜曲歌辭 前有一尊酒行二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f40cb6c3-66e9-4a83-a497-124d085ed298', '雜曲歌辭 緩歌行', '杂曲歌辞 緩歌行', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["小來託身攀貴遊，傾財破產無所憂。","暮擬經過石渠署，朝將出入銅龍樓。","結交杜陵輕薄子，謂言可生復可死。","一沈一浮會有時，棄我翻然如脫屣。","男兒立身須自彊，十五閉戶潁水陽。","業就功成見明主，擊鐘鼎食坐華堂。","二八蛾眉梳墮馬，美酒清歌曲房下。","文昌宮中賜錦衣，長安陌上退朝歸。","五侯賓從莫敢視，三省官僚揖者稀。","早知今日讀書是，悔作從來任俠非。"]', '["小来託身攀貴游，傾財破產無所憂。","暮擬經過石渠署，朝將出入銅龙楼。","結交杜陵轻薄子，謂言可生复可死。","一沈一浮會有时，棄我翻然如脫屣。","男兒立身須自彊，十五閉戶潁水陽。","業就功成见明主，擊鐘鼎食坐华堂。","二八蛾眉梳墮马，美酒清歌曲房下。","文昌宮中賜錦衣，长安陌上退朝归。","五侯賓從莫敢視，三省官僚揖者稀。","早知今日读书是，悔作從来任俠非。"]', '诗', 'shi', '', NULL, '雜曲歌辭 緩歌行 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8eeb3273-d271-4674-900b-2057c3f59957', '雜曲歌辭 結客少年場行', '杂曲歌辞 結客少年場行', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["韓魏多奇節，倜儻遺名利。","共矜然諾心，各負縱橫志。","結友一言重，相思千里至。","綠沈明月弦，金絡浮雲轡。","吹簫入吳市，擊筑游燕肆。","尋源博望侯，結客遠相求。","少年重一顧，長驅背隴頭。","燄燄霜戈動，耿耿劒虹浮。","天山冬夏雪，交河南北流。","雲起龍沙暗，木落鴈行秋。","輕生徇知己，非是爲身謀。"]', '["韓魏多奇節，倜儻遺名利。","共矜然諾心，各負縱橫志。","結友一言重，相思千里至。","綠沈明月弦，金絡浮云轡。","吹簫入吳市，擊筑游燕肆。","尋源博望侯，結客远相求。","少年重一顧，长驱背隴头。","燄燄霜戈动，耿耿劒虹浮。","天山冬夏雪，交河南北流。","云起龙沙暗，木落鴈行秋。","轻生徇知己，非是爲身謀。"]', '诗', 'shi', '', NULL, '雜曲歌辭 結客少年場行 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79462191-3bcb-4599-b51b-40bcf4d3065d', '雜曲歌辭 結客少年場行', '杂曲歌辞 結客少年場行', 'cbd92d57-cc9c-4374-90aa-06d246d4f394', '唐', '["幽幷俠少年，金絡控連錢。","竊符方救趙，擊筑正懷燕。","輕生辭鳳闕，揮袂上祁連。","陸離橫寶劒，出沒驚徂旃。","蒙輪恆顧敵，超乘忽爭先。","摧枯逾百戰，拓地遠三千。","骨都魂已散，樓蘭首復傳。","龍城含曉霧，瀚海隔遙天。","歌吹金微返，振旅玉門旋。","烽火今已息，非復照甘泉。"]', '["幽幷俠少年，金絡控連錢。","竊符方救趙，擊筑正懷燕。","轻生辞鳳闕，揮袂上祁連。","陸離橫寶劒，出沒驚徂旃。","蒙輪恆顧敵，超乘忽爭先。","摧枯逾百戰，拓地远三千。","骨都魂已散，楼蘭首复傳。","龙城含晓霧，瀚海隔遙天。","歌吹金微返，振旅玉门旋。","烽火今已息，非复照甘泉。"]', '诗', 'shi', '', NULL, '雜曲歌辭 結客少年場行 虞羽客 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3e3dab9-6df9-4bc1-b428-ace90e3a922c', '雜曲歌辭 結客少年場行', '杂曲歌辞 結客少年場行', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["長安重遊俠，洛陽富才雄。","玉劒浮雲騎，金鞍明月弓。","鬬雞過渭北，走馬向關東。","孫賓遙見待，郭解暗相通。","不受千金爵，誰論萬里功。","將軍下天上，虜騎入雲中。","烽火夜似月，兵氣曉成虹。","橫行徇知己，負羽遠從戎。","龍旌昏朔霧，鳥陣卷寒風。","追奔瀚海咽，戰罷陰山空。","歸來謝天子，何如馬上翁。"]', '["长安重游俠，洛陽富才雄。","玉劒浮云騎，金鞍明月弓。","鬬雞過渭北，走马向关东。","孫賓遙见待，郭解暗相通。","不受千金爵，誰論万里功。","將軍下天上，虜騎入云中。","烽火夜似月，兵氣晓成虹。","橫行徇知己，負羽远從戎。","龙旌昏朔霧，鸟陣卷寒风。","追奔瀚海咽，戰罷陰山空。","归来謝天子，何如马上翁。"]', '诗', 'shi', '', NULL, '雜曲歌辭 結客少年場行 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('818ab313-009a-4bca-829a-30768146e907', '雜曲歌辭 結客少年場行', '杂曲歌辞 結客少年場行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["紫燕黃金瞳，啾啾搖綠鬉。","平明相馳逐，結客洛門東。","少年學劒術，凌轢白猨公。","珠袍曳錦帶，七首插吳鴻。","由來萬夫勇，挾此生雄風。","託交從劇孟，買醉入新豐。","笑盡一杯酒，殺人都市中。","羞道易水寒，從令日貫虹。","燕丹事不立，虛沒秦帝宮。","舞陽死灰人，安可與成功。"]', '["紫燕黄金瞳，啾啾搖綠鬉。","平明相驰逐，結客洛门东。","少年学劒術，凌轢白猨公。","珠袍曳錦带，七首插吳鴻。","由来万夫勇，挾此生雄风。","託交從劇孟，買醉入新豐。","笑尽一杯酒，殺人都市中。","羞道易水寒，從令日貫虹。","燕丹事不立，虛沒秦帝宮。","舞陽死灰人，安可與成功。"]', '诗', 'shi', '', NULL, '雜曲歌辭 結客少年場行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d7dac40-92dc-450e-a834-3050521eb709', '雜曲歌辭 結客少年場行', '杂曲歌辞 結客少年場行', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["重義輕生一劒知，白虹貫日報讐歸。","片心惆悵清平世，酒市無人問布衣。"]', '["重義轻生一劒知，白虹貫日報讐归。","片心惆悵清平世，酒市無人问布衣。"]', '诗', 'shi', '', NULL, '雜曲歌辭 結客少年場行 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51e663b3-6f76-41f4-8e75-c03772e5f8e1', '雜曲歌辭 少年子', '杂曲歌辞 少年子', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["少年飛翠蓋，上路動金鑣。","始酌文君酒，新吹弄玉簫。","少年不歡樂，何以盡芳朝。","千金笑裏面，一搦抱中腰。","挂冠豈憚宿，迎拜不勝嬌。","寄語少年子，無辭歸路遙。"]', '["少年飞翠蓋，上路动金鑣。","始酌文君酒，新吹弄玉簫。","少年不歡乐，何以尽芳朝。","千金笑裏面，一搦抱中腰。","挂冠豈憚宿，迎拜不勝嬌。","寄語少年子，無辞归路遙。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年子 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e475a182-9775-4dcb-9087-4abb71fc6476', '雜曲歌辭 少年子', '杂曲歌辞 少年子', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["青雲少年子，挾彈章臺左。","鞍馬四邊開，突如流星過。","金丸落飛鳥，夜入瓊樓臥。","夷齊是何人？獨守西山餓。"]', '["青云少年子，挾彈章台左。","鞍马四邊开，突如流星過。","金丸落飞鸟，夜入瓊楼臥。","夷齊是何人？独守西山餓。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年子 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('232b2330-be81-492f-ab96-52be310cd64d', '雜曲歌辭 少年樂', '杂曲歌辞 少年乐', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["芳草落花如錦地，二十長遊醉鄉裏。","紅纓不重白馬驕，垂柳金絲香拂水。","吳娥未笑花不開，綠鬢聳墮蘭雲起。","陸郎倚醉牽羅袂，奪得寶釵金翡翠。"]', '["芳草落花如錦地，二十长游醉乡裏。","紅纓不重白马驕，垂柳金絲香拂水。","吳娥未笑花不开，綠鬢聳墮蘭云起。","陸郎倚醉牽羅袂，奪得寶釵金翡翠。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年樂 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d9c03ce-ae52-44ae-8100-f43432da8432', '雜曲歌辭 少年樂', '杂曲歌辞 少年乐', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["二十便封侯，名居第一流。","綠鬟深小院，清管下高樓。","醉把金船擲，閑敲玉鐙遊。","帶盤紅鼹鼠，袍砑紫犀牛。","錦袋歸調箭，羅鞋起撥毬。","眼前長貴盛，那信世間愁。"]', '["二十便封侯，名居第一流。","綠鬟深小院，清管下高楼。","醉把金船擲，闲敲玉鐙游。","带盤紅鼹鼠，袍砑紫犀牛。","錦袋归調箭，羅鞋起撥毬。","眼前长貴盛，那信世间愁。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年樂 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cc5782f-97e4-4f04-970a-d56618e8edf9', '雜曲歌辭 少年行三首 一', '杂曲歌辞 少年行三首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["擊筑飲美酒，劒歌易水湄。","經過燕太子，結託幷州兒。","少年負壯氣，奮烈自有時。","因聲魯句踐，爭情勿相欺。"]', '["擊筑饮美酒，劒歌易水湄。","經過燕太子，結託幷州兒。","少年負壯氣，奮烈自有时。","因声魯句踐，爭情勿相欺。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年行三首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21bf8b8a-d5c1-4146-b572-31d2372a6474', '雜曲歌辭 少年行三首 二', '杂曲歌辞 少年行三首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["五陵年少金市東，銀鞍白馬度春風。","落花踏盡遊何處？笑入胡姬酒肆中。"]', '["五陵年少金市东，銀鞍白马度春风。","落花踏尽游何处？笑入胡姬酒肆中。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年行三首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1c29cbc-5e59-4332-8a20-033c7524e3d0', '雜曲歌辭 少年行三首 三', '杂曲歌辞 少年行三首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["君不見淮南少年遊俠客，白日毬獵夜擁擲。","呼盧百萬終不惜，報讐千里如咫尺。","少年遊俠好經過，渾身裝束皆綺羅。","蘭蕙相隨喧妓女，風光去處滿笙歌。","驕矜自言不可有，俠士堂中養來久。","好鞍好馬乞與人，十千五千旋沽酒。","赤心用盡爲知己，黃金不惜栽桃李。","桃李栽來幾度春，一回花落一回新。","府縣盡爲門下客，王侯皆是平交人。","男兒百年且樂命，何須徇書受貧病。","男兒百年且榮身，何須徇節甘風塵。","衣冠半是征戰士，窮儒浪作林泉民。","遮莫枝根長百丈，不如當代多還往。","遮莫姻親連帝城，不如當身自簪纓。","看取富貴眼前者，何用悠悠身後名。"]', '["君不见淮南少年游俠客，白日毬獵夜擁擲。","呼盧百万終不惜，報讐千里如咫尺。","少年游俠好經過，渾身裝束皆綺羅。","蘭蕙相隨喧妓女，风光去处满笙歌。","驕矜自言不可有，俠士堂中養来久。","好鞍好马乞與人，十千五千旋沽酒。","赤心用尽爲知己，黄金不惜栽桃李。","桃李栽来幾度春，一回花落一回新。","府縣尽爲门下客，王侯皆是平交人。","男兒百年且乐命，何須徇书受貧病。","男兒百年且榮身，何須徇節甘风塵。","衣冠半是征戰士，窮儒浪作林泉民。","遮莫枝根长百丈，不如當代多還往。","遮莫姻親連帝城，不如當身自簪纓。","看取富貴眼前者，何用悠悠身後名。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年行三首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e16cb386-9a1c-463f-a43f-2110e2a36e33', '雜曲歌辭 少年行四首 一', '杂曲歌辞 少年行四首 一', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["新豐美酒斗十千，咸陽遊俠多少年。","相逢意氣爲君飲，繫馬高樓垂柳邊。"]', '["新豐美酒斗十千，咸陽游俠多少年。","相逢意氣爲君饮，繫马高楼垂柳邊。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年行四首 一 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('428cbfda-43a6-4cb3-9418-d65f2ea45d54', '雜曲歌辭 少年行四首 二', '杂曲歌辞 少年行四首 二', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["漢家君臣歡宴終，高議雲臺論戰功。","天子臨軒賜侯印，將軍佩出明光宮。"]', '["漢家君臣歡宴終，高議云台論戰功。","天子臨軒賜侯印，將軍佩出明光宮。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年行四首 二 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6acd85a2-fea8-4875-83c5-6ef888f875bc', '雜曲歌辭 少年行四首 三', '杂曲歌辞 少年行四首 三', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["出身仕漢羽林郎，初隨驃騎戰漁陽。","孰知不向邊庭苦，縱死猶聞俠骨香。"]', '["出身仕漢羽林郎，初隨驃騎戰漁陽。","孰知不向邊庭苦，縱死猶闻俠骨香。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年行四首 三 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66f48ee1-6f1b-4a05-89ae-c904f70ac9b7', '雜曲歌辭 少年行四首 四', '杂曲歌辞 少年行四首 四', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["一身能臂兩雕弧，虜騎千羣只似無。","偏坐金鞍調白羽，紛紛射殺五單于。"]', '["一身能臂兩雕弧，虜騎千羣只似無。","偏坐金鞍調白羽，紛紛射殺五單于。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年行四首 四 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77659827-473d-4602-9888-f305d9c70273', '雜曲歌辭 少年行二首 一', '杂曲歌辞 少年行二首 一', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["西陵俠年少，送客過長亭。","青槐夾兩路，白馬如流星。","聞道羽書急，單于寇井陘。","氣高輕赴難，誰顧燕山銘。"]', '["西陵俠年少，送客過长亭。","青槐夾兩路，白马如流星。","闻道羽书急，單于寇井陘。","氣高轻赴难，誰顧燕山銘。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年行二首 一 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21943b5d-11e5-44f2-9714-ad996dade3ae', '雜曲歌辭 少年行二首 二', '杂曲歌辞 少年行二首 二', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["走馬還相尋，西樓下夕陰。","結交期一劒，留意贈千金。","高閣歌聲遠，重關柳色深。","夜閑須盡醉，莫負百年心。"]', '["走马還相尋，西楼下夕陰。","結交期一劒，留意贈千金。","高閣歌声远，重关柳色深。","夜闲須尽醉，莫負百年心。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年行二首 二 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70adc79e-eace-4cd8-a20e-1e8b609ab8eb', '雜曲歌辭 少年行', '杂曲歌辞 少年行', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["少年從出獵長楊，禁中新拜羽林郎。","獨到輦前射雙虎，君王手賜黃金鐺。","日日鬬雞都市裏，贏得寶刀重刻字。","百里報讐夜出城，平明還在倡樓醉。","遙聞虜到平陵下，不待詔書行上馬。","斬得名王獻桂宮，封侯起第一日中。","不爲六郡良家子，百戰始取邊城功。"]', '["少年從出獵长楊，禁中新拜羽林郎。","独到輦前射雙虎，君王手賜黄金鐺。","日日鬬雞都市裏，贏得寶刀重刻字。","百里報讐夜出城，平明還在倡楼醉。","遙闻虜到平陵下，不待詔书行上马。","斬得名王獻桂宮，封侯起第一日中。","不爲六郡良家子，百戰始取邊城功。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年行 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0049020-3b5e-4a46-9b66-71f6de65501d', '雜曲歌辭 少年行三首 一', '杂曲歌辞 少年行三首 一', 'e70c2a3f-d1d9-4ef3-b56a-f276ecf53e0d', '唐', '["十八羽林郎，戎衣事漢王。","臂鷹金殿側，挾彈玉輿旁。","馳道春風起，陪遊出建章。"]', '["十八羽林郎，戎衣事漢王。","臂鷹金殿側，挾彈玉輿旁。","驰道春风起，陪游出建章。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年行三首 一 李嶷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cf6265f-c453-4bc5-9f3f-55a6ab43a83a', '雜曲歌辭 少年行三首 二', '杂曲歌辞 少年行三首 二', 'e70c2a3f-d1d9-4ef3-b56a-f276ecf53e0d', '唐', '["侍獵長楊下，承恩更射飛。","塵生馬影滅，箭落鴈行稀。","薄暮歸隨仗，聯翩入瑣闈。"]', '["侍獵长楊下，承恩更射飞。","塵生马影滅，箭落鴈行稀。","薄暮归隨仗，聯翩入瑣闈。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年行三首 二 李嶷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8baf651c-c608-4795-9260-c572c4af580b', '雜曲歌辭 少年行三首 三', '杂曲歌辞 少年行三首 三', 'e70c2a3f-d1d9-4ef3-b56a-f276ecf53e0d', '唐', '["玉劒膝邊橫，金杯馬上傾。","朝遊茂陵道，暮宿鳳凰城。","豪吏多猜忌，無勞問姓名。"]', '["玉劒膝邊橫，金杯马上傾。","朝游茂陵道，暮宿鳳凰城。","豪吏多猜忌，無勞问姓名。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年行三首 三 李嶷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60de5a95-c758-49be-ad0a-380712d15cb3', '雜曲歌辭 少年行', '杂曲歌辞 少年行', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["射飛誇侍獵，行樂愛聯鑣。","薦枕青娥豔，鳴鞭白馬驕。","曲房珠翠合，深巷管弦調。","日晚春風裏，衣香滿路飄。"]', '["射飞誇侍獵，行乐愛聯鑣。","薦枕青娥豔，鳴鞭白马驕。","曲房珠翠合，深巷管弦調。","日晚春风裏，衣香满路飄。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年行 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a194d8f-5981-4036-9da1-dc6e3cedf4f9', '雜曲歌辭 少年行四首 一', '杂曲歌辞 少年行四首 一', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["少小邊州慣放狂，驏騎蕃馬射黃羊。","如今年事無筋力，猶倚營門數鴈行。"]', '["少小邊州慣放狂，驏騎蕃马射黄羊。","如今年事無筋力，猶倚營门數鴈行。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年行四首 一 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9c061a4-c957-4d74-a0f3-86001d8b2a7f', '雜曲歌辭 少年行四首 二', '杂曲歌辞 少年行四首 二', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["家本清河住五城，須憑弓箭得功名。","等閑飛鞚秋原上，獨向寒雲試射聲。"]', '["家本清河住五城，須憑弓箭得功名。","等闲飞鞚秋原上，独向寒云試射声。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年行四首 二 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('133359e4-c7c2-4a43-9adc-e5e8ea4e2e41', '雜曲歌辭 少年行四首 三', '杂曲歌辞 少年行四首 三', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["弓背霞明劒照霜，秋風走馬出咸陽。","未收天子河湟地，不擬回頭望故鄉。"]', '["弓背霞明劒照霜，秋风走马出咸陽。","未收天子河湟地，不擬回头望故乡。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年行四首 三 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f5d9f3e-a3d3-446a-ba9c-3066f4b6eff9', '雜曲歌辭 少年行四首 四', '杂曲歌辞 少年行四首 四', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["霜滿中庭月過樓，金尊玉柱對清秋。","當年稱意須爲樂，不到天明未肯休。"]', '["霜满中庭月過楼，金尊玉柱对清秋。","當年稱意須爲乐，不到天明未肯休。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年行四首 四 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('195ac36f-552e-4cc2-9e99-6d8c0cc93b72', '雜曲歌辭 少年行二首 一', '杂曲歌辞 少年行二首 一', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["官爲駿馬監，職帥羽林兒。","兩綬藏不見，落花何處期？","獵敲白玉鐙，怒袖紫金鎚。","田竇長留醉，蘇辛曲護岐。","豪持出塞節，笑別遠山眉。","捷報雲臺賀，公卿拜壽巵。"]', '["官爲駿马監，職帥羽林兒。","兩綬藏不见，落花何处期？","獵敲白玉鐙，怒袖紫金鎚。","田竇长留醉，蘇辛曲護岐。","豪持出塞節，笑別远山眉。","捷報云台賀，公卿拜壽巵。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年行二首 一 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de67de33-4490-4be1-accf-46965ae26d38', '雜曲歌辭 少年行二首 二', '杂曲歌辞 少年行二首 二', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["連環羈玉聲光碎，綠錦蔽泥虬卷高。","春風細雨走馬去，珠落璀璀白𦋺袍。"]', '["連环羈玉声光碎，綠錦蔽泥虬卷高。","春风細雨走马去，珠落璀璀白𦋺袍。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年行二首 二 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94fe7344-b244-4341-8887-e717c373c9a2', '雜曲歌辭 少年行三首 一', '杂曲歌辞 少年行三首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["莫笑田家老瓦盆，自從盛酒長兒孫。","傾銀注瓦驚人眼，共醉終同臥竹根。"]', '["莫笑田家老瓦盆，自從盛酒长兒孫。","傾銀注瓦驚人眼，共醉終同臥竹根。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年行三首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f609657-375a-4d97-b35e-880dbca040b2', '雜曲歌辭 少年行三首 二', '杂曲歌辞 少年行三首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["巢燕養雛渾去盡，紅花結子已無多。","黃衫年少來宜數，不見堂前東逝波。"]', '["巢燕養雛渾去尽，紅花結子已無多。","黄衫年少来宜數，不见堂前东逝波。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年行三首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a97a451-d5e0-4de9-8762-7ccdf64773dd', '雜曲歌辭 少年行三首 三', '杂曲歌辞 少年行三首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["馬上誰家白面郎，臨階下馬坐人牀。","不通姓字麄豪甚，指點銀瓶索酒嘗。"]', '["马上誰家白面郎，臨階下马坐人牀。","不通姓字麄豪甚，指点銀瓶索酒嘗。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年行三首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0145b0c7-8703-4e0d-b2a0-16a069723bd0', '雜曲歌辭 少年行', '杂曲歌辞 少年行', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["少年足風情，垂鞭賣眼行。","帶金師子小，裘錦騏驎獰。","選匠裝金鐙，推錢買[鈿]箏。","李陵雖效死，時論得虛名。"]', '["少年足风情，垂鞭賣眼行。","带金師子小，裘錦騏驎獰。","選匠裝金鐙，推錢買[鈿]箏。","李陵雖效死，时論得虛名。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年行 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26f3fc34-fc1c-41ef-8c59-9b6d1806020e', '雜曲歌辭 少年行', '杂曲歌辞 少年行', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["千點斕斒噴玉驄，青絲結尾繡纏騣。","鳴鞭晚出章臺路，葉葉春依楊柳風。"]', '["千点斕斒噴玉驄，青絲結尾繡纏騣。","鳴鞭晚出章台路，葉葉春依楊柳风。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年行 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3e7c18c-7987-4926-ae60-8e2ef9e2d7dd', '雜曲歌辭 少年行', '杂曲歌辞 少年行', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["醉騎白馬走空衢，惡少皆稱電不如。","五鳳街頭閑勒轡，半垂衫袖揖金吾。"]', '["醉騎白马走空衢，惡少皆稱電不如。","五鳳街头闲勒轡，半垂衫袖揖金吾。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年行 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('924c524c-67cb-4e2a-9d9b-e16243269c66', '雜曲歌辭 少年行三首 一', '杂曲歌辞 少年行三首 一', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["錦衣鮮華手擎鶻，閑行氣貌多輕忽。","稼穡艱難總不知，五帝三王是何物。"]', '["錦衣鲜华手擎鶻，闲行氣貌多轻忽。","稼穡艱难總不知，五帝三王是何物。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年行三首 一 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3702d36-4293-4d70-a4e9-3b752445769f', '雜曲歌辭 少年行三首 二', '杂曲歌辞 少年行三首 二', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["自拳五色毬，迸入他人宅。","卻捉蒼頭奴，玉鞭打一百。"]', '["自拳五色毬，迸入他人宅。","卻捉蒼头奴，玉鞭打一百。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年行三首 二 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de165d68-2bc6-4a4f-8b86-d746d9f82a7d', '雜曲歌辭 少年行三首 三', '杂曲歌辞 少年行三首 三', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["面白如削玉，猖狂曲江曲。","馬上黃金鞍，適來新賭得。"]', '["面白如削玉，猖狂曲江曲。","马上黄金鞍，適来新賭得。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年行三首 三 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de37c5eb-9420-4c1d-a0a8-e9d9a5a118ca', '雜曲歌辭 少年行', '杂曲歌辞 少年行', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["五陵豪客多，買酒黃金賤。","醉下酒家樓，美人雙翠幰。","揮劒邯鄲市，走馬梁王苑。","樂事殊未央，年華已云晚。"]', '["五陵豪客多，買酒黄金賤。","醉下酒家楼，美人雙翠幰。","揮劒邯鄲市，走马梁王苑。","乐事殊未央，年华已云晚。"]', '诗', 'shi', '', NULL, '雜曲歌辭 少年行 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('151b748b-c973-46df-9c3a-6ce7a9ab53e0', '雜曲歌辭 漢宮少年行', '杂曲歌辞 漢宮少年行', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["君不見上宮警夜營八屯，鼕鼕街鼓朝朱軒。","玉階霜仗擁未合，少年排入銅龍門。","暗聞弦管九天上，宮漏沈沈清吹繁。","纔明走馬絕馳道，呼鷹挾彈通繚垣。","玉籠金瑣養黃口，探雛取卵伴王孫。","分曹六博快一擲，迎歡先意笑語喧。","巧爲柔媚學優孟，儒衣嬉戲冠沐猨。","晚來香街經柳市，行過倡市宿桃根。","相逢杯酒一言失，回朱點白聞至尊。","金張許史伺顏色，王侯將相莫敢論。","豈知人事無定勢，朝歡暮戚如掌翻。","椒房寵移子愛奪，一夕秋風生戾園。","徒用黃金將買賦，寧知白玉暗成痕。","持杯收水水已覆，徙薪避火火更燔。","欲求四老張丞相，南山如天不可上。"]', '["君不见上宮警夜營八屯，鼕鼕街鼓朝朱軒。","玉階霜仗擁未合，少年排入銅龙门。","暗闻弦管九天上，宮漏沈沈清吹繁。","纔明走马絕驰道，呼鷹挾彈通繚垣。","玉籠金瑣養黄口，探雛取卵伴王孫。","分曹六博快一擲，迎歡先意笑語喧。","巧爲柔媚学優孟，儒衣嬉戲冠沐猨。","晚来香街經柳市，行過倡市宿桃根。","相逢杯酒一言失，回朱点白闻至尊。","金張許史伺顏色，王侯將相莫敢論。","豈知人事無定勢，朝歡暮戚如掌翻。","椒房寵移子愛奪，一夕秋风生戾园。","徒用黄金將買賦，寧知白玉暗成痕。","持杯收水水已覆，徙薪避火火更燔。","欲求四老張丞相，南山如天不可上。"]', '诗', 'shi', '', NULL, '雜曲歌辭 漢宮少年行 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d98b9ab-f80b-40ee-9b22-370fd62cac82', '雜曲歌辭 長樂少年行', '杂曲歌辞 长乐少年行', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["遺卻珊瑚鞭，白馬驕不行。","章臺折楊柳，春草路旁情。"]', '["遺卻珊瑚鞭，白马驕不行。","章台折楊柳，春草路旁情。"]', '诗', 'shi', '', NULL, '雜曲歌辭 長樂少年行 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ab356ea-69fc-43ff-b74c-4ece4a0b8277', '雜曲歌辭 長安少年行十首 一', '杂曲歌辞 长安少年行十首 一', '0ac28590-334d-4d3b-9abe-9ad672e9b9cc', '唐', '["金紫少年郎，繞街鞍馬光。","身從左中尉，官屬右春坊。","剗戴揚州帽，重熏異國香。","垂鞭踏青草，來去杏園芳。"]', '["金紫少年郎，繞街鞍马光。","身從左中尉，官屬右春坊。","剗戴揚州帽，重熏異国香。","垂鞭踏青草，来去杏园芳。"]', '诗', 'shi', '', NULL, '雜曲歌辭 長安少年行十首 一 李廓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d2c74e3-c2b7-490c-9acf-50569e84ac7f', '雜曲歌辭 長安少年行十首 二', '杂曲歌辞 长安少年行十首 二', '0ac28590-334d-4d3b-9abe-9ad672e9b9cc', '唐', '["追逐輕薄伴，閑遊不著緋。","長攏出獵馬，數換打毬衣。","曉日尋花去，春風帶酒歸。","青樓無晝夜，歌舞歇時稀。"]', '["追逐轻薄伴，闲游不著緋。","长攏出獵马，數換打毬衣。","晓日尋花去，春风带酒归。","青楼無晝夜，歌舞歇时稀。"]', '诗', 'shi', '', NULL, '雜曲歌辭 長安少年行十首 二 李廓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5fe37ca-edcb-443c-ad33-7031aeb811fe', '雜曲歌辭 長安少年行十首 三', '杂曲歌辞 长安少年行十首 三', '0ac28590-334d-4d3b-9abe-9ad672e9b9cc', '唐', '["日高春睡足，帖馬賞年華。","倒插銀魚袋，行隨金犢車。","還攜新市酒，遠醉曲江花。","幾度歸侵黑，金吾送到家。"]', '["日高春睡足，帖马賞年华。","倒插銀鱼袋，行隨金犢车。","還携新市酒，远醉曲江花。","幾度归侵黑，金吾送到家。"]', '诗', 'shi', '', NULL, '雜曲歌辭 長安少年行十首 三 李廓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30de6830-2b0e-4719-b3df-cf10cd1ff31e', '雜曲歌辭 長安少年行十首 四', '杂曲歌辞 长安少年行十首 四', '0ac28590-334d-4d3b-9abe-9ad672e9b9cc', '唐', '["好勝耽長行，天明燭滿樓。","留人看獨脚，賭馬換偏頭。","樂奏曾無歇，杯巡不暫休。","時時遙冷笑，怪客有春愁。"]', '["好勝耽长行，天明燭满楼。","留人看独脚，賭马換偏头。","乐奏曾無歇，杯巡不暫休。","时时遙冷笑，怪客有春愁。"]', '诗', 'shi', '', NULL, '雜曲歌辭 長安少年行十首 四 李廓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4dce1fe-1d34-467d-bd5c-4c4700dbfc30', '雜曲歌辭 長安少年行十首 五', '杂曲歌辞 长安少年行十首 五', '0ac28590-334d-4d3b-9abe-9ad672e9b9cc', '唐', '["遨遊攜豔妓，裝束似男兒。","杯酒逢花住，笙歌簇馬吹。","鸎聲催曲急，春色訝歸遲。","不以聞銜鼓，華筵待月移。"]', '["遨游携豔妓，裝束似男兒。","杯酒逢花住，笙歌簇马吹。","鸎声催曲急，春色訝归遲。","不以闻銜鼓，华筵待月移。"]', '诗', 'shi', '', NULL, '雜曲歌辭 長安少年行十首 五 李廓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20fddc31-f54f-42b1-94ab-982db8af120a', '雜曲歌辭 長安少年行十首 六', '杂曲歌辞 长安少年行十首 六', '0ac28590-334d-4d3b-9abe-9ad672e9b9cc', '唐', '["賞春惟逐勝，大宅可曾歸。","不樂還逃席，多狂慣衩衣。","歌人踏月起，語燕卷簾飛。","好婦惟相妒，倡樓不醉稀。"]', '["賞春惟逐勝，大宅可曾归。","不乐還逃席，多狂慣衩衣。","歌人踏月起，語燕卷簾飞。","好婦惟相妒，倡楼不醉稀。"]', '诗', 'shi', '', NULL, '雜曲歌辭 長安少年行十首 六 李廓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53d87055-9847-4740-b963-b9ed763b27dc', '雜曲歌辭 長安少年行十首 七', '杂曲歌辞 长安少年行十首 七', '0ac28590-334d-4d3b-9abe-9ad672e9b9cc', '唐', '["戟門連日閉，苦飲惜殘春。","開瑣通新客，教姬屈醉人。","請歌牽白馬，自舞踏紅茵。","時輩皆相許，平生不負身。"]', '["戟门連日閉，苦饮惜殘春。","开瑣通新客，教姬屈醉人。","請歌牽白马，自舞踏紅茵。","时輩皆相許，平生不負身。"]', '诗', 'shi', '', NULL, '雜曲歌辭 長安少年行十首 七 李廓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ead3046a-4747-487f-a645-2695cd744c3d', '雜曲歌辭 長安少年行十首 八', '杂曲歌辞 长安少年行十首 八', '0ac28590-334d-4d3b-9abe-9ad672e9b9cc', '唐', '["新年高殿上，始見有光輝。","玉鴈排方帶，金鵝立仗衣。","酒深和椀賜，馬疾打珂飛。","朝下人爭看，香街意氣歸。"]', '["新年高殿上，始见有光輝。","玉鴈排方带，金鵝立仗衣。","酒深和椀賜，马疾打珂飞。","朝下人爭看，香街意氣归。"]', '诗', 'shi', '', NULL, '雜曲歌辭 長安少年行十首 八 李廓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12371483-23f7-473a-a7fa-b466029e7023', '雜曲歌辭 長安少年行十首 九', '杂曲歌辞 长安少年行十首 九', '0ac28590-334d-4d3b-9abe-9ad672e9b9cc', '唐', '["遊市慵騎馬，隨姬入坐車。","樓邊聽歌吹，簾外市釵花。","樂眼從人鬧，歸心畏日斜。","蒼頭來去報，飲伴到倡家。"]', '["游市慵騎马，隨姬入坐车。","楼邊听歌吹，簾外市釵花。","乐眼從人鬧，归心畏日斜。","蒼头来去報，饮伴到倡家。"]', '诗', 'shi', '', NULL, '雜曲歌辭 長安少年行十首 九 李廓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8f002c5-afdb-457a-975a-78cc51739426', '雜曲歌辭 長安少年行十首 十', '杂曲歌辞 长安少年行十首 十', '0ac28590-334d-4d3b-9abe-9ad672e9b9cc', '唐', '["小婦教鸚鵡，頭邊喚醉醒。","犬嬌眠玉簟，鷹掣撼金鈴。","碧地攢花障，紅泥待客亭。","雖然長按曲，不飲不曾聽。"]', '["小婦教鸚鵡，头邊喚醉醒。","犬嬌眠玉簟，鷹掣撼金鈴。","碧地攢花障，紅泥待客亭。","雖然长按曲，不饮不曾听。"]', '诗', 'shi', '', NULL, '雜曲歌辭 長安少年行十首 十 李廓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88223ac4-d3bd-4452-a514-35b58bf8f219', '雜曲歌辭 長安少年行', '杂曲歌辞 长安少年行', 'd031d511-00fb-47fd-8345-864309b121e2', '唐', '["翠樓春酒蝦蟆陵，長安少年皆共矜。","紛紛半醉綠槐道，蹀躞花驄驕不勝。"]', '["翠楼春酒蝦蟆陵，长安少年皆共矜。","紛紛半醉綠槐道，蹀躞花驄驕不勝。"]', '诗', 'shi', '', NULL, '雜曲歌辭 長安少年行 僧皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f5d6ee5-b0eb-4fe8-b26f-26f4bd9fe093', '雜曲歌辭 渭城少年行', '杂曲歌辞 渭城少年行', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["洛陽二月梨花飛，秦地行人春憶歸。","揚鞭走馬城南陌，朝逢驛使秦川客。","驛使前日發章臺，傳道長安春早來。","棠梨宮中燕初至，葡萄館裏花正開。","念此使人歸更早，三月便達長安道。","長安道上春可憐，搖風蕩日曲河邊。","萬戶樓臺臨渭水，五陵花柳滿秦川。","秦川寒食盛繁華，遊子春來喜見花。","鬬雞下杜塵初合，走馬章臺日半斜。","章臺帝城稱貴里，青樓日晚歌鐘起。","貴里豪家白馬驕，五陵年少不相饒。","雙雙挾彈來金市，兩兩鳴鞭上渭橋。","渭城橋頭酒新熟，金鞍白馬誰家宿。","可憐錦瑟箏琵琶，玉臺清酒就君家。","小婦春來不解羞，嬌歌一曲楊柳花。"]', '["洛陽二月梨花飞，秦地行人春憶归。","揚鞭走马城南陌，朝逢驛使秦川客。","驛使前日發章台，傳道长安春早来。","棠梨宮中燕初至，葡萄館裏花正开。","念此使人归更早，三月便達长安道。","长安道上春可怜，搖风蕩日曲河邊。","万戶楼台臨渭水，五陵花柳满秦川。","秦川寒食盛繁华，游子春来喜见花。","鬬雞下杜塵初合，走马章台日半斜。","章台帝城稱貴里，青楼日晚歌鐘起。","貴里豪家白马驕，五陵年少不相饒。","雙雙挾彈来金市，兩兩鳴鞭上渭橋。","渭城橋头酒新熟，金鞍白马誰家宿。","可怜錦瑟箏琵琶，玉台清酒就君家。","小婦春来不解羞，嬌歌一曲楊柳花。"]', '诗', 'shi', '', NULL, '雜曲歌辭 渭城少年行 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48156f67-5e1a-4a77-8b33-207ee517a763', '雜曲歌辭 邯鄲少年行', '杂曲歌辞 邯鄲少年行', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["邯鄲城南遊俠子，自矜生長邯鄲裏。","千場縱博家仍富，幾度報讐身不死。","宅中歌笑日紛紛，門外車馬如雲屯。","未知肝膽向誰是，令人却憶平原君。","君不見今人交態薄，黃金用盡還疎索。","以茲感激辭舊遊，更於時事無所求。","且與少年飲美酒，往來射獵西山頭。"]', '["邯鄲城南游俠子，自矜生长邯鄲裏。","千場縱博家仍富，幾度報讐身不死。","宅中歌笑日紛紛，门外车马如云屯。","未知肝膽向誰是，令人却憶平原君。","君不见今人交態薄，黄金用尽還疎索。","以茲感激辞旧游，更於时事無所求。","且與少年饮美酒，往来射獵西山头。"]', '诗', 'shi', '', NULL, '雜曲歌辭 邯鄲少年行 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45052a4c-136c-4b68-9ac8-839e3fb430ad', '雜曲歌辭 長安少年行', '杂曲歌辞 长安少年行', '901b5a45-86c2-4256-81ed-7d1cf0852db6', '唐', '["霞鞍金口騮，豹袖紫貂裘。","家住叢臺下，門前漳水流。","喚人呈楚舞，借客試吳鉤。","見說秦兵至，甘心赴國讐。"]', '["霞鞍金口騮，豹袖紫貂裘。","家住叢台下，门前漳水流。","喚人呈楚舞，借客試吳鉤。","见说秦兵至，甘心赴国讐。"]', '诗', 'shi', '', NULL, '雜曲歌辭 長安少年行 鄭錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5b07d20-8ae2-43eb-a1a2-9559f9434b11', '雜曲歌辭 輕薄篇', '杂曲歌辞 轻薄篇', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["豪不必馳千騎，雄不在垂雙鞬。","天生俊氣自相逐，出與鵰鶚同飛翻。","朝行九衢不得意，下鞭走馬城西原。","忽聞燕雁一聲去，迴鞭挾彈平陵園。","歸來青樓曲未半，美人玉色當金尊。","淮陰少年不相下，酒酣半笑倚市門。","安知我有不平色，白日欲顧紅塵昏。","死生容易如反掌，得意失意由一言。","少年但飲莫相問，此中報讐亦報恩。"]', '["豪不必驰千騎，雄不在垂雙鞬。","天生俊氣自相逐，出與鵰鶚同飞翻。","朝行九衢不得意，下鞭走马城西原。","忽闻燕雁一声去，迴鞭挾彈平陵园。","归来青楼曲未半，美人玉色當金尊。","淮陰少年不相下，酒酣半笑倚市门。","安知我有不平色，白日欲顧紅塵昏。","死生容易如反掌，得意失意由一言。","少年但饮莫相问，此中報讐亦報恩。"]', '诗', 'shi', '', NULL, '雜曲歌辭 輕薄篇 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a46720e-68dc-4499-a81c-531d77dcc20f', '雜曲歌辭 輕薄篇二首 一', '杂曲歌辞 轻薄篇二首 一', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["繡林錦野，春態相壓。","誰家少年，馬蹏蹋蹋。","鬬雞走狗夜不歸，一擲賭却如花妾。","惟云不顛不狂，其名不彰。","悲夫！。"]', '["繡林錦野，春態相壓。","誰家少年，马蹏蹋蹋。","鬬雞走狗夜不归，一擲賭却如花妾。","惟云不顛不狂，其名不彰。","悲夫！。"]', '诗', 'shi', '', NULL, '雜曲歌辭 輕薄篇二首 一 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7d10684-3aca-47d4-9e9e-bbe65fc2be41', '雜曲歌辭 輕薄篇二首 二', '杂曲歌辞 轻薄篇二首 二', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["木落蕭蕭，蛩鳴唧唧。","不覺朱蔫臉紅，霜劫鬢漆。","世途多事，泣向秋日。","方吟少壯不努力，老大徒傷悲。"]', '["木落蕭蕭，蛩鳴唧唧。","不覺朱蔫臉紅，霜劫鬢漆。","世途多事，泣向秋日。","方吟少壯不努力，老大徒傷悲。"]', '诗', 'shi', '', NULL, '雜曲歌辭 輕薄篇二首 二 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d4e85e1-0bed-4e7b-8bb6-81677d9f448d', '雜曲歌辭 輕薄行', '杂曲歌辞 轻薄行', '405848e7-8d14-42db-a593-f688fd279870', '唐', '["玉鞭金鐙驊騮蹏，橫眉吐氣如虹霓。","五陵春暖芳草齊，笙歌到處花成泥。","日沈月上且鬬雞，醉來莫問天高低。","伯陽道德何涕唾，仲尼禮樂徒卑棲。"]', '["玉鞭金鐙驊騮蹏，橫眉吐氣如虹霓。","五陵春暖芳草齊，笙歌到处花成泥。","日沈月上且鬬雞，醉来莫问天高低。","伯陽道德何涕唾，仲尼禮乐徒卑棲。"]', '诗', 'shi', '', NULL, '雜曲歌辭 輕薄行 僧齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8406ffdc-03fd-479f-9231-a716d93ab242', '雜曲歌辭 灞上輕薄行', '杂曲歌辞 灞上轻薄行', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["長安無緩步，況值天景暮。","相逢灞滻間，親戚不相顧。","自歎方拙身，忽隨輕薄倫。","常恐失所避，化爲車轍塵。","此中生白髮，疾走亦未歇。"]', '["长安無緩步，況值天景暮。","相逢灞滻间，親戚不相顧。","自歎方拙身，忽隨轻薄倫。","常恐失所避，化爲车轍塵。","此中生白髮，疾走亦未歇。"]', '诗', 'shi', '', NULL, '雜曲歌辭 灞上輕薄行 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1af491fc-3298-4059-8f3e-533889aa466b', '雜曲歌辭 遊俠篇', '杂曲歌辞 游俠篇', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["少年負膽氣，好勇復知機。","仗劒出門去，孤城逢合圍。","殺人遼水上，走馬漁陽歸。","錯落金瑣甲，蒙茸貂鼠衣。","還家行且獵，弓矢速如飛。","地迥鷹犬疾，草深狐兔肥。","腰間懸兩綬，轉眄生光輝。"]', '["少年負膽氣，好勇复知機。","仗劒出门去，孤城逢合圍。","殺人遼水上，走马漁陽归。","錯落金瑣甲，蒙茸貂鼠衣。","還家行且獵，弓矢速如飞。","地迥鷹犬疾，草深狐兔肥。","腰间懸兩綬，轉眄生光輝。"]', '诗', 'shi', '', NULL, '雜曲歌辭 遊俠篇 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdf5c629-aac9-4b27-a025-acdb82f02349', '雜曲歌辭 遊俠行', '杂曲歌辞 游俠行', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["壯士性剛決，火中見石裂。","殺人不迴頭，輕生如暫別。","豈知眼有淚，肯白頭上髮。","平生無恩酬，劒閑一百月。"]', '["壯士性剛決，火中见石裂。","殺人不迴头，轻生如暫別。","豈知眼有泪，肯白头上髮。","平生無恩酬，劒闲一百月。"]', '诗', 'shi', '', NULL, '雜曲歌辭 遊俠行 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('016daf19-f22d-4933-9582-3d91c4f9aeab', '雜曲歌辭 俠客行', '杂曲歌辞 俠客行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["趙客縵胡纓，吳鉤霜雪明。","銀鞍照白馬，颯沓如流星。","十步殺一人，千里不留行。","事了拂衣去，深藏身與名。","閑過信陵飲，脫劒膝前橫。","將炙啖朱亥，持觴勸侯嬴。","三杯吐然諾，五嶽倒爲輕。","眼花耳熱後，意氣素霓生。","救趙揮金槌，邯鄲先震驚。","千秋二壯士，烜赫大梁城。","縱死俠骨香，不慙世上英。","誰能書閣下，白首太玄經。"]', '["趙客縵胡纓，吳鉤霜雪明。","銀鞍照白马，颯沓如流星。","十步殺一人，千里不留行。","事了拂衣去，深藏身與名。","闲過信陵饮，脫劒膝前橫。","將炙啖朱亥，持觴勸侯嬴。","三杯吐然諾，五嶽倒爲轻。","眼花耳熱後，意氣素霓生。","救趙揮金槌，邯鄲先震驚。","千秋二壯士，烜赫大梁城。","縱死俠骨香，不慙世上英。","誰能书閣下，白首太玄經。"]', '诗', 'shi', '', NULL, '雜曲歌辭 俠客行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86a4715d-5148-469e-95e1-a3c4db3a9b19', '雜曲歌辭 俠客行', '杂曲歌辞 俠客行', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["俠客不怕死，怕在事不成。","事成不肯藏姓名，我非竊賊誰夜行。","白日堂堂殺袁盎，九衢草草人面青。","此客此心師海鯨，海鯨露背橫滄溟。","海濱分作兩處生，海鯨分海減海力。","俠客有謀人不測，三尺鐵蛇延二國。"]', '["俠客不怕死，怕在事不成。","事成不肯藏姓名，我非竊賊誰夜行。","白日堂堂殺袁盎，九衢草草人面青。","此客此心師海鯨，海鯨露背橫滄溟。","海濱分作兩处生，海鯨分海減海力。","俠客有謀人不測，三尺鐵蛇延二国。"]', '诗', 'shi', '', NULL, '雜曲歌辭 俠客行 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42357d0c-52e0-4fb4-88a3-6b09333932a0', '雜曲歌辭 俠客行', '杂曲歌辞 俠客行', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["欲出鴻都門，陰雲蔽城闕。","寶劒黯如水，微紅溼餘血。","白馬夜頻嘶，三更霸陵雪。"]', '["欲出鴻都门，陰云蔽城闕。","寶劒黯如水，微紅溼餘血。","白马夜頻嘶，三更霸陵雪。"]', '诗', 'shi', '', NULL, '雜曲歌辭 俠客行 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('741c3eef-8892-4a08-9a13-3723b288c0ba', '雜曲歌辭 行行遊且獵篇', '杂曲歌辞 行行游且獵篇', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["邊城兒，生年不讀一字書，但知遊獵誇輕趫。","胡馬秋肥宜白草，騎來躡影何矜驕。","金鞭拂雲揮鳴鞘，半酣呼鷹出遠郊。","弓彎滿月不虛發，雙鶬迸落連飛𩩉。","海邊觀者皆辟易，猛氣英風振沙磧。"]', '["邊城兒，生年不读一字书，但知游獵誇轻趫。","胡马秋肥宜白草，騎来躡影何矜驕。","金鞭拂云揮鳴鞘，半酣呼鷹出远郊。","弓彎满月不虛發，雙鶬迸落連飞𩩉。","海邊观者皆辟易，猛氣英风振沙磧。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行行遊且獵篇 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22923091-18da-429d-9ef1-6b367fd74b1a', '雜曲歌辭 遊子吟', '杂曲歌辞 游子吟', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["慈母手中線，遊子身上衣。","臨行密密縫，意恐遲遲歸。","誰言寸草心，報得三春暉。"]', '["慈母手中線，游子身上衣。","臨行密密縫，意恐遲遲归。","誰言寸草心，報得三春暉。"]', '诗', 'shi', '', NULL, '雜曲歌辭 遊子吟 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afa0d6db-b93a-4e96-aae9-59ec920eb6de', '雜曲歌辭 遊子吟', '杂曲歌辞 游子吟', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["故櫪思疲馬，故巢思迷禽。","浮雲蔽我鄉，躑躅遊子吟。","遊子悲久滯，浮雲鬱東岑。","客堂無絲桐，落葉如秋霖。","艱哉遠遊子，所以悲滯淫。","一爲浮雲詞，憤塞誰能禁。","馳暉百年內，惟願展所欽。","胡爲不歸歟，坐使年病侵。","未老霜遶鬢，非狂火燒心。","太行何艱哉？北斗不可斟。","夜晴星河出，耿耿辰與參。","佳人敻青天，尺素重於金。","泬寥羣動異，眇默諸境森。","苔衣上閑階，蜻蛚催寒砧。","立身計幾誤，道險無容針。","三年不還家，萬里遺錦衾。","夢魂無重阻，離憂因古今。","胡爲不歸歟，孤負丘中琴。","腰下是何物？牽纏曠登尋。","朝與名山期，夕宿楚水陰。","楚水殊演漾，名山杳嶇嶔。","客從洞庭來，婉孌瀟湘深。","橘柚在南國，鴻雁遺秋音。","下有碧草洲，上有青橘林。","引燭窺洞穴，凌波睥天琛。","蒲荷影參差，鳧鶴雛淋涔。","浩歌惜芳杜，散髮輕華簪。","胡爲不歸歟，淚下霑衣襟。","鳶飛戾霄漢，螻蟻制鱣鱏。","赫赫大聖朝，日月光照臨。","聖主雖啓迪，奇人分堙沈。","層城發雲韶，玉府鏘球琳。","鹿鳴志豐草，況復虞人箴。"]', '["故櫪思疲马，故巢思迷禽。","浮云蔽我乡，躑躅游子吟。","游子悲久滯，浮云鬱东岑。","客堂無絲桐，落葉如秋霖。","艱哉远游子，所以悲滯淫。","一爲浮云词，憤塞誰能禁。","驰暉百年內，惟願展所欽。","胡爲不归歟，坐使年病侵。","未老霜遶鬢，非狂火燒心。","太行何艱哉？北斗不可斟。","夜晴星河出，耿耿辰與參。","佳人敻青天，尺素重於金。","泬寥羣动異，眇默諸境森。","苔衣上闲階，蜻蛚催寒砧。","立身計幾誤，道險無容針。","三年不還家，万里遺錦衾。","梦魂無重阻，離憂因古今。","胡爲不归歟，孤負丘中琴。","腰下是何物？牽纏曠登尋。","朝與名山期，夕宿楚水陰。","楚水殊演漾，名山杳嶇嶔。","客從洞庭来，婉孌瀟湘深。","橘柚在南国，鴻雁遺秋音。","下有碧草洲，上有青橘林。","引燭窺洞穴，凌波睥天琛。","蒲荷影參差，鳧鹤雛淋涔。","浩歌惜芳杜，散髮轻华簪。","胡爲不归歟，泪下霑衣襟。","鳶飞戾霄漢，螻蟻制鱣鱏。","赫赫大聖朝，日月光照臨。","聖主雖啓迪，奇人分堙沈。","層城發云韶，玉府鏘球琳。","鹿鳴志豐草，況复虞人箴。"]', '诗', 'shi', '', NULL, '雜曲歌辭 遊子吟 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33097bd6-4e80-4ed3-97fe-4444ff7468cb', '雜曲歌辭 遊子吟', '杂曲歌辞 游子吟', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["女羞夫壻蕩，客恥主人賤。","遭遇同衆流，低回愧相見。","君非青銅鏡，何事空照面？","莫以衣上塵，不謂心如練。","人生當榮盛，待士勿言倦。","君看白日馳，何異弦上箭。"]', '["女羞夫壻蕩，客恥主人賤。","遭遇同衆流，低回愧相见。","君非青銅镜，何事空照面？","莫以衣上塵，不謂心如練。","人生當榮盛，待士勿言倦。","君看白日驰，何異弦上箭。"]', '诗', 'shi', '', NULL, '雜曲歌辭 遊子吟 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('199cb91d-b884-4cee-bb45-d85c40d9ef16', '雜曲歌辭 壯士吟', '杂曲歌辞 壯士吟', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["壯士不曾悲，悲即無回期。","如何易水上，未歌先淚垂。"]', '["壯士不曾悲，悲即無回期。","如何易水上，未歌先泪垂。"]', '诗', 'shi', '', NULL, '雜曲歌辭 壯士吟 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0afe4eae-ded2-4a70-ae06-6144d4e77cf0', '雜曲歌辭 壯士行', '杂曲歌辞 壯士行', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["陰風振寒郊，猛虎正咆哮。","徐行出燒地，連吼入黃茆。","壯士走馬去，鐙前彎玉弰。","叱之使人立，一發如鈹交。","悍睛忽星墜，飛血濺林梢。","彪炳爲我席，羶腥充我庖。","里中欣害除，賀酒紛號呶。","明日長橋上，傾城看斬蛟。"]', '["陰风振寒郊，猛虎正咆哮。","徐行出燒地，連吼入黄茆。","壯士走马去，鐙前彎玉弰。","叱之使人立，一發如鈹交。","悍睛忽星墜，飞血濺林梢。","彪炳爲我席，羶腥充我庖。","里中欣害除，賀酒紛號呶。","明日长橋上，傾城看斬蛟。"]', '诗', 'shi', '', NULL, '雜曲歌辭 壯士行 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60e6c4fc-0583-4d86-898f-9bab22c5846a', '雜曲歌辭 壯士行', '杂曲歌辞 壯士行', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["西方太白高，壯士羞病死。","心知報恩處，對酒歌易水。","砂鴻嗥天末，橫劒別妻子。","蘇武執節歸，班超束書起。","山河不足重，重在遇知己。"]', '["西方太白高，壯士羞病死。","心知報恩处，对酒歌易水。","砂鴻嗥天末，橫劒別妻子。","蘇武執節归，班超束书起。","山河不足重，重在遇知己。"]', '诗', 'shi', '', NULL, '雜曲歌辭 壯士行 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23e1a814-7dfd-4148-8318-3f3b7cccafb2', '雜曲歌辭 壯士行', '杂曲歌辞 壯士行', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["一斗之膽撐臟腑，如磥之筋礙臂骨。","有時誤入千人叢，自覺一身橫突兀。","當今四海無煙塵，胸襟被壓不得伸。","凍梟殘蠆我不取，汙我匣黑青蛇鱗。"]', '["一斗之膽撐臟腑，如磥之筋礙臂骨。","有时誤入千人叢，自覺一身橫突兀。","當今四海無煙塵，胸襟被壓不得伸。","凍梟殘蠆我不取，汙我匣黑青蛇鱗。"]', '诗', 'shi', '', NULL, '雜曲歌辭 壯士行 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29e4fffb-ebb1-4bd5-96f0-fab28f4e18de', '雜曲歌辭 浩歌', '杂曲歌辞 浩歌', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["南風吹山作平地，帝遣天吳移海水。","王母桃花千遍紅，彭祖巫咸幾回死。","青毛驄馬參差錢，嬌春楊柳含細煙。","箏人勸我金屈巵，神血未凝身問誰。","不須浪飲丁督護，世上英雄本無主。","買絲繡作平原君，有酒惟澆趙州土。","漏催水咽玉蟾蜍，衛娘髮薄不勝梳。","看見秋眉換深綠，二十男兒那刺促。"]', '["南风吹山作平地，帝遣天吳移海水。","王母桃花千遍紅，彭祖巫咸幾回死。","青毛驄马參差錢，嬌春楊柳含細煙。","箏人勸我金屈巵，神血未凝身问誰。","不須浪饮丁督護，世上英雄本無主。","買絲繡作平原君，有酒惟澆趙州土。","漏催水咽玉蟾蜍，衛娘髮薄不勝梳。","看见秋眉換深綠，二十男兒那刺促。"]', '诗', 'shi', '', NULL, '雜曲歌辭 浩歌 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bab8a287-f853-4c81-ab99-2795a5484ae1', '雜曲歌辭 浩歌行', '杂曲歌辞 浩歌行', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["天長地久無終畢，昨夜今朝又明日。","鬢髮蒼浪牙齒疎，不覺身年四十七。","前去五十有幾年，把鏡照面心茫然。","既無長繩繫白日，又無大藥駐朱顏。","朱顏日漸不如故，青史功名在何處？","欲留年少待富貴，富貴不來年少去。","去復去兮如長河，東流赴海無迴波。","賢愚貴賤同歸盡，北邙冢墓高嵯峨。","古來如此非獨我，未死有酒且酣歌。","顏回短命伯夷餓，我今所得亦已多。"]', '["天长地久無終畢，昨夜今朝又明日。","鬢髮蒼浪牙齒疎，不覺身年四十七。","前去五十有幾年，把镜照面心茫然。","既無长繩繫白日，又無大藥駐朱顏。","朱顏日漸不如故，青史功名在何处？","欲留年少待富貴，富貴不来年少去。","去复去兮如长河，东流赴海無迴波。","賢愚貴賤同归尽，北邙冢墓高嵯峨。","古来如此非独我，未死有酒且酣歌。","顏回短命伯夷餓，我今所得亦已多。"]', '诗', 'shi', '', NULL, '雜曲歌辭 浩歌行 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37484eba-f71b-4797-aaa9-d8a43d3219cd', '雜曲歌辭 歸去來引', '杂曲歌辞 归去来引', 'b6fcbf3a-114f-4b05-bbfb-b26c236c335d', '唐', '["歸去來，歸期不可違。","相見故明月，浮雲共我歸。"]', '["归去来，归期不可違。","相见故明月，浮云共我归。"]', '诗', 'shi', '', NULL, '雜曲歌辭 歸去來引 張熾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12fa4755-e5e9-40fe-91bf-590aafb4ddf9', '雜曲歌辭 麗人曲', '杂曲歌辞 丽人曲', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["紅顏稱絕代，欲並真無侶。","獨有鏡中人，由來自相許。"]', '["紅顏稱絕代，欲並真無侶。","独有镜中人，由来自相許。"]', '诗', 'shi', '', NULL, '雜曲歌辭 麗人曲 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aaae5882-9b74-4b45-9bb5-9f773a721119', '雜曲歌辭 麗人行', '杂曲歌辞 丽人行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["三月三日天氣新，長安水邊多麗人。","態濃意遠淑且真，肌理細膩骨肉勻。","繡羅衣裳照暮春，蹙金孔雀銀麒麟。","頭上何所有？翠微㔩葉垂鬢脣。","背後何所見？珠壓腰衱穩稱身。","就中雲幕椒房親，賜名大國虢與秦。","紫駞之峯出翠釜，水晶之盤行素鱗。","犀筯厭飫久未下，鸞刀縷切空紛綸。","黃門飛鞚不動塵，御廚絲絡送八珍。","簫鼓哀吟感鬼神，賓從雜遝實要津。","後來鞍馬何逡巡，當軒下馬入錦茵。","楊花雪落覆白蘋，青鳥飛去銜紅巾。","炙手可熱勢絕倫，慎莫近前丞相嗔。"]', '["三月三日天氣新，长安水邊多丽人。","態濃意远淑且真，肌理細膩骨肉勻。","繡羅衣裳照暮春，蹙金孔雀銀麒麟。","头上何所有？翠微㔩葉垂鬢脣。","背後何所见？珠壓腰衱穩稱身。","就中云幕椒房親，賜名大国虢與秦。","紫駞之峯出翠釜，水晶之盤行素鱗。","犀筯厭飫久未下，鸾刀縷切空紛綸。","黄门飞鞚不动塵，御廚絲絡送八珍。","簫鼓哀吟感鬼神，賓從杂遝實要津。","後来鞍马何逡巡，當軒下马入錦茵。","楊花雪落覆白蘋，青鸟飞去銜紅巾。","炙手可熱勢絕倫，慎莫近前丞相嗔。"]', '诗', 'shi', '', NULL, '雜曲歌辭 麗人行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a35c63d8-b7e1-4da5-9780-47b1c8736b0c', '雜曲歌辭 東飛伯勞歌', '杂曲歌辞 东飞伯勞歌', 'db8c386d-e29f-47b9-a015-0fae6b9e00ee', '唐', '["青田白鶴丹山鳳，婺女姮娥兩相送。","誰家絕世綺帳前，豔粉芳脂映寶鈿。","窈窕玉堂褰翠幕，參差繡戶懸珠箔。","絕世三五愛紅妝，冶袖長裾蘭麝香。","春去花枝俄易改，可歎年光不相待。"]', '["青田白鹤丹山鳳，婺女姮娥兩相送。","誰家絕世綺帳前，豔粉芳脂映寶鈿。","窈窕玉堂褰翠幕，參差繡戶懸珠箔。","絕世三五愛紅妝，冶袖长裾蘭麝香。","春去花枝俄易改，可歎年光不相待。"]', '诗', 'shi', '', NULL, '雜曲歌辭 東飛伯勞歌 張柬之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('006d90dd-df34-4d79-af85-99e7e7d497bf', '雜曲歌辭 東飛伯勞歌', '杂曲歌辞 东飞伯勞歌', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["傳書青鳥迎簫鳳，巫嶺荆臺數通夢。","誰家窈窕住園樓，五馬千金照陌頭。","羅裙玉佩當軒出，點翠施紅競春日。","佳人二八盛舞歌，羞將百萬呈雙娥。","庭前芳樹朝夕改，空駐妍華欲誰待。"]', '["傳书青鸟迎簫鳳，巫嶺荆台數通梦。","誰家窈窕住园楼，五马千金照陌头。","羅裙玉佩當軒出，点翠施紅競春日。","佳人二八盛舞歌，羞將百万呈雙娥。","庭前芳樹朝夕改，空駐妍华欲誰待。"]', '诗', 'shi', '', NULL, '雜曲歌辭 東飛伯勞歌 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b2b0b80-871c-4b5f-ac4d-1d266fc0df36', '雜曲歌辭 東飛伯勞歌', '杂曲歌辞 东飞伯勞歌', 'bc3ce6dd-5bcf-4826-a95e-9852e09fc0a6', '唐', '["秦王龍劒燕后琴，珊瑚寶匣鏤雙心。","誰家女兒抱香枕，開衾滅燭願侍寢。","瓊窗半上金縷幬，輕羅隱面不障羞。","青綺幃中坐相憶，紅羅鏡裏見愁色。","簷花照月鶯對棲，空將可憐暗中啼。"]', '["秦王龙劒燕后琴，珊瑚寶匣鏤雙心。","誰家女兒抱香枕，开衾滅燭願侍寢。","瓊窗半上金縷幬，轻羅隐面不障羞。","青綺幃中坐相憶，紅羅镜裏见愁色。","簷花照月鶯对棲，空將可怜暗中啼。"]', '诗', 'shi', '', NULL, '雜曲歌辭 東飛伯勞歌 李暇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2076be94-1be6-4df6-b8a4-4bd7a755d247', '雜曲歌辭 鳴雁行', '杂曲歌辞 鳴雁行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["胡雁鳴，辭燕山，昨發委羽朝度關。","一一銜蘆枝，南飛散落天地間。","連行接翼往復還，客居煙波寄湘吳。","凌霜觸雪毛體枯，畏逢矰繳驚相呼。"]', '["胡雁鳴，辞燕山，昨發委羽朝度关。","一一銜蘆枝，南飞散落天地间。","連行接翼往复還，客居煙波寄湘吳。","凌霜觸雪毛體枯，畏逢矰繳驚相呼。"]', '诗', 'shi', '', NULL, '雜曲歌辭 鳴雁行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aaa3d713-8c7f-4f46-a0d5-39ed552d9511', '雜曲歌辭 鳴雁行', '杂曲歌辞 鳴雁行', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["嗷嗷鳴雁鳴且飛，窮秋南去春北歸。","去寒就暖識所處，天長地闊棲息稀。","風霜酸苦稻粱微，羽毛摧落身不肥。","徘徊反顧羣侶違，哀鳴欲下洲渚非。","江南水闊朝雲多，草長沙輭無網羅。"]', '["嗷嗷鳴雁鳴且飞，窮秋南去春北归。","去寒就暖識所处，天长地闊棲息稀。","风霜酸苦稻粱微，羽毛摧落身不肥。","徘徊反顧羣侶違，哀鳴欲下洲渚非。","江南水闊朝云多，草长沙輭無網羅。"]', '诗', 'shi', '', NULL, '雜曲歌辭 鳴雁行 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ef99715-15ba-4586-98d0-bb90aece4b71', '雜曲歌辭 鳴雁行', '杂曲歌辞 鳴雁行', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["七月朔方雁心苦，聯影翻空落南土。","八月江南陰復晴，浮雲繞天難夜行。","羽翼勞痛心虛驚，一聲相呼百處鳴。","楚童夜宿煙波側，沙上布羅連草色。","月闇風悲欲下天，不知何處容棲息？","楚童胡爲傷我神，爾不曾作遠行人。","江南羽族本不少，寧得網羅此客鳥。"]', '["七月朔方雁心苦，聯影翻空落南土。","八月江南陰复晴，浮云繞天难夜行。","羽翼勞痛心虛驚，一声相呼百处鳴。","楚童夜宿煙波側，沙上布羅連草色。","月闇风悲欲下天，不知何处容棲息？","楚童胡爲傷我神，爾不曾作远行人。","江南羽族本不少，寧得網羅此客鸟。"]', '诗', 'shi', '', NULL, '雜曲歌辭 鳴雁行 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31bc78e4-ece6-4a4f-b5bb-a8c00df6c620', '雜曲歌辭 鳴雁行', '杂曲歌辞 鳴雁行', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["朔風動地來，吹起沙上聲。","閨中有邊思，玉筯此時橫。","莫怕兒女恨，主人烹不鳴。"]', '["朔风动地来，吹起沙上声。","閨中有邊思，玉筯此时橫。","莫怕兒女恨，主人烹不鳴。"]', '诗', 'shi', '', NULL, '雜曲歌辭 鳴雁行 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51234d8c-4147-4404-a709-797f87f6931f', '雜曲歌辭 空城雀', '杂曲歌辞 空城雀', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["嗷嗷空城雀，身計何戚促。","本與鷦鷯羣，不隨鳳凰族。","提攜四黃口，飲乳未嘗足。","食君糠粃餘，常恐烏鳶逐。","恥涉太行險，羞營覆車粟。","天命有定端，守分絕所欲。"]', '["嗷嗷空城雀，身計何戚促。","本與鷦鷯羣，不隨鳳凰族。","提携四黄口，饮乳未嘗足。","食君糠粃餘，常恐烏鳶逐。","恥涉太行險，羞營覆车粟。","天命有定端，守分絕所欲。"]', '诗', 'shi', '', NULL, '雜曲歌辭 空城雀 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdd79ce6-205b-4c91-bf73-532087f5acfe', '雜曲歌辭 空城雀', '杂曲歌辞 空城雀', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["空城雀，何不飛來人家住？","空城無人種禾黍。","土間生子草間長，滿地蓬蒿幸無主。","近村雖有高樹枝，雨中無食長苦飢。","八月小兒夾弓箭，家家畏我田頭飛。","但能不出空城裏，秋時百草皆有子。","黃口黃口莫啾啾，長爾得成無橫死。"]', '["空城雀，何不飞来人家住？","空城無人種禾黍。","土间生子草间长，满地蓬蒿幸無主。","近村雖有高樹枝，雨中無食长苦飢。","八月小兒夾弓箭，家家畏我田头飞。","但能不出空城裏，秋时百草皆有子。","黄口黄口莫啾啾，长爾得成無橫死。"]', '诗', 'shi', '', NULL, '雜曲歌辭 空城雀 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b48917db-dd2c-48ff-b521-5a655dd0734a', '雜曲歌辭 空城雀', '杂曲歌辞 空城雀', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["一雀入官倉，所食能損幾。","所慮往損頻，官倉乃害爾。","魚網不在天，鳥網不在水。"]', '["一雀入官倉，所食能損幾。","所慮往損頻，官倉乃害爾。","鱼網不在天，鸟網不在水。"]', '诗', 'shi', '', NULL, '雜曲歌辭 空城雀 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe167a9d-6e8f-423b-90e5-9ba015de0358', '雜曲歌辭 空城雀', '杂曲歌辞 空城雀', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["飢啄空城土，莫近太倉粟。","一粒未充腸，却入公子腹。","且弔城上骨，幾曾害爾族。","不聞莊辛語，今日寒蕪綠。"]', '["飢啄空城土，莫近太倉粟。","一粒未充腸，却入公子腹。","且弔城上骨，幾曾害爾族。","不闻莊辛語，今日寒蕪綠。"]', '诗', 'shi', '', NULL, '雜曲歌辭 空城雀 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32d70177-1afe-411b-9a36-684d2e840b72', '雜曲歌辭 車遙遙', '杂曲歌辞 车遙遙', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["路喜到江盡，江上又通舟。","舟車兩無阻，何處不得遊？","丈夫四方志，女子安可留？","郎自別日言，無令生遠愁。","旅鴈忽叫月，斷猨寒啼秋。","此夕夢君夢，君在百城樓。","寄淚無因波，寄恨無因輈。","願爲馭者手，與郎迴馬頭。"]', '["路喜到江尽，江上又通舟。","舟车兩無阻，何处不得游？","丈夫四方志，女子安可留？","郎自別日言，無令生远愁。","旅鴈忽叫月，斷猨寒啼秋。","此夕梦君梦，君在百城楼。","寄泪無因波，寄恨無因輈。","願爲馭者手，與郎迴马头。"]', '诗', 'shi', '', NULL, '雜曲歌辭 車遙遙 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3cadd66-3071-4a7d-976c-4b2ec9ab2e23', '雜曲歌辭 車遙遙', '杂曲歌辞 车遙遙', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["征人遙遙出古城，雙輪齊動駟馬鳴。","山川無處無歸路，念君長作萬里行。","野田人稀秋草綠，日暮放馬車中宿。","驚麏遊兔在我傍，獨唱鄉歌對僮僕。","君家大宅鳳城隅，年年道上隨行車。","願爲玉鑾繫華軾，終日有聲在君側。","門前舊轍久已平，無由復得君消息。"]', '["征人遙遙出古城，雙輪齊动駟马鳴。","山川無处無归路，念君长作万里行。","野田人稀秋草綠，日暮放马车中宿。","驚麏游兔在我傍，独唱乡歌对僮僕。","君家大宅鳳城隅，年年道上隨行车。","願爲玉鑾繫华軾，終日有声在君側。","门前旧轍久已平，無由复得君消息。"]', '诗', 'shi', '', NULL, '雜曲歌辭 車遙遙 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9db361d6-8924-443c-bd96-2b01b1a8c95d', '雜曲歌辭 車遙遙', '杂曲歌辞 车遙遙', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["東方曨曨車軋軋，地色不分新去轍。","閨門半掩牀半空，斑斑枕花殘淚紅。","君心若車千萬轉，妾身如轍遺漸遠。","碧川迢迢山宛宛，馬蹏在耳輪在眼。","桑間女兒情不淺，莫道野蠶能作繭。"]', '["东方曨曨车軋軋，地色不分新去轍。","閨门半掩牀半空，斑斑枕花殘泪紅。","君心若车千万轉，妾身如轍遺漸远。","碧川迢迢山宛宛，马蹏在耳輪在眼。","桑间女兒情不淺，莫道野蠶能作繭。"]', '诗', 'shi', '', NULL, '雜曲歌辭 車遙遙 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c5018e5-d3da-49b5-965b-ac5c58fac0e5', '雜曲歌辭 車遙遙', '杂曲歌辞 车遙遙', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["自從車馬出門朝，便入空房守寂寥。","玉枕夜殘魚信絕，金鈿秋盡雁書遙。","臉邊楚雨臨風落，頭上春雲向日銷。","芳草又衰還不至，碧天霜冷轉無憀。"]', '["自從车马出门朝，便入空房守寂寥。","玉枕夜殘鱼信絕，金鈿秋尽雁书遙。","臉邊楚雨臨风落，头上春云向日銷。","芳草又衰還不至，碧天霜冷轉無憀。"]', '诗', 'shi', '', NULL, '雜曲歌辭 車遙遙 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('198f15ab-e3b2-404d-b6c5-7f53d7a0f0e8', '雜曲歌辭 自君之出矣', '杂曲歌辞 自君之出矣', '02b38e68-c8f5-4f17-b317-f93e0a9ace55', '唐', '["自君之出矣，梁塵靜不飛。","思君如滿月，夜夜減容暉。"]', '["自君之出矣，梁塵静不飞。","思君如满月，夜夜減容暉。"]', '诗', 'shi', '', NULL, '雜曲歌辭 自君之出矣 辛弘智 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eeab8129-4858-4ec3-beaf-8f176f357b7e', '雜曲歌辭 自君之出矣', '杂曲歌辞 自君之出矣', '91c0da00-96e1-41ea-bd8c-b56887bfedce', '唐', '["自君之出矣，弦吹絕無聲。","思君如百草，撩亂逐春生。"]', '["自君之出矣，弦吹絕無声。","思君如百草，撩亂逐春生。"]', '诗', 'shi', '', NULL, '雜曲歌辭 自君之出矣 李康成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01bd3441-2699-41e1-96f4-b59e1d42c3a3', '雜曲歌辭 自君之出矣', '杂曲歌辞 自君之出矣', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["自君之出矣，壁上蜘蛛織。","近取見妾心，夜夜無休息。","妾有雙玉環，寄君表相憶。","環是妾之心，玉是君之德。","馳情增悴容，蓄思損精力。","玉簟寒悽悽，延想心惻惻。","風含霜月明，水泛碧天色。","此水有盡時，此情無終極。"]', '["自君之出矣，壁上蜘蛛织。","近取见妾心，夜夜無休息。","妾有雙玉环，寄君表相憶。","环是妾之心，玉是君之德。","驰情增悴容，蓄思損精力。","玉簟寒悽悽，延想心惻惻。","风含霜月明，水泛碧天色。","此水有尽时，此情無終極。"]', '诗', 'shi', '', NULL, '雜曲歌辭 自君之出矣 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('145211da-6f92-4a02-aecb-b260130e310d', '雜曲歌辭 自君之出矣', '杂曲歌辞 自君之出矣', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["自君之出矣，寶鏡爲誰明。","思君如隴水，長聞嗚咽聲。"]', '["自君之出矣，寶镜爲誰明。","思君如隴水，长闻嗚咽声。"]', '诗', 'shi', '', NULL, '雜曲歌辭 自君之出矣 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe76e09a-ec1d-4ca8-b10f-cba85c1598d6', '雜曲歌辭 自君之出矣', '杂曲歌辞 自君之出矣', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["自君之出矣，萬物看成古。","千尋葶藶枝，爭奈長長苦。"]', '["自君之出矣，万物看成古。","千尋葶藶枝，爭奈长长苦。"]', '诗', 'shi', '', NULL, '雜曲歌辭 自君之出矣 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('feed970e-6f9d-451c-ba5c-ba6a629f924f', '雜曲歌辭 長相思', '杂曲歌辞 长相思', 'aff13fc2-5a00-4377-82e1-6a8e636e4aaf', '唐', '["長相思，久離別。","關山阻，風煙絕。","臺上鏡文銷，袖中書字滅。","不見君形影，何曾有懽悅。"]', '["长相思，久離別。","关山阻，风煙絕。","台上镜文銷，袖中书字滅。","不见君形影，何曾有懽悅。"]', '诗', 'shi', '', NULL, '雜曲歌辭 長相思 郎大家宋氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99314a0f-cce0-4006-aaaf-1e0cb2569f89', '雜曲歌辭 長相思', '杂曲歌辞 长相思', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["君不見天津橋下東流水，東望龍門北朝市。","楊柳青青宛地垂，桃紅李白花參差。","花參差，柳堪結，此時憶君心斷絕。"]', '["君不见天津橋下东流水，东望龙门北朝市。","楊柳青青宛地垂，桃紅李白花參差。","花參差，柳堪結，此时憶君心斷絕。"]', '诗', 'shi', '', NULL, '雜曲歌辭 長相思 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4baf2d1-ea61-4fb3-a284-e889275bdca2', '雜曲歌辭 長相思三首 一', '杂曲歌辞 长相思三首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["長相思，在長安，絡緯秋啼金井欄。","微霜淒淒簟色寒，孤燈不明思欲絕。","卷帷望月空長歎，美人如花隔雲端。","上有青冥之長天，下有綠水之波瀾。","天長路遠魂飛苦，夢魂不到關山難。","長相思，摧心肝。"]', '["长相思，在长安，絡緯秋啼金井欄。","微霜淒淒簟色寒，孤灯不明思欲絕。","卷帷望月空长歎，美人如花隔云端。","上有青冥之长天，下有綠水之波瀾。","天长路远魂飞苦，梦魂不到关山难。","长相思，摧心肝。"]', '诗', 'shi', '', NULL, '雜曲歌辭 長相思三首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('caa023cf-9f55-450c-9638-1cf5c0223cc1', '雜曲歌辭 長相思三首 二', '杂曲歌辞 长相思三首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["日色已盡花含煙，月明欲素愁不眠。","趙瑟初停鳳凰柱，蜀琴欲奏鴛鴦弦。","此曲有意無人傳，願隨春風寄燕然，憶君迢迢隔青天。","昔日橫波目，今成流淚泉。","不信妾腸斷，歸來看取明鏡前。"]', '["日色已尽花含煙，月明欲素愁不眠。","趙瑟初停鳳凰柱，蜀琴欲奏鴛鴦弦。","此曲有意無人傳，願隨春风寄燕然，憶君迢迢隔青天。","昔日橫波目，今成流泪泉。","不信妾腸斷，归来看取明镜前。"]', '诗', 'shi', '', NULL, '雜曲歌辭 長相思三首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0dc1b19-1846-4837-937f-8c2ff37fcd18', '雜曲歌辭 長相思三首 三', '杂曲歌辞 长相思三首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["美人在時花滿堂，美人去後花餘牀。","牀中繡被卷不寢，至今三載猶聞香。","香亦竟不滅，人亦竟不來。","相思黃葉落，白露點青苔。"]', '["美人在时花满堂，美人去後花餘牀。","牀中繡被卷不寢，至今三載猶闻香。","香亦竟不滅，人亦竟不来。","相思黄葉落，白露点青苔。"]', '诗', 'shi', '', NULL, '雜曲歌辭 長相思三首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b87015d-2a4a-4fa7-af5e-fe7cebc4a99f', '雜曲歌辭 長相思', '杂曲歌辞 长相思', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["遼陽望河縣，白首無由見。","海上珊瑚枝，年年寄春燕。"]', '["遼陽望河縣，白首無由见。","海上珊瑚枝，年年寄春燕。"]', '诗', 'shi', '', NULL, '雜曲歌辭 長相思 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4345418b-e039-46ad-b17a-e26a7bebed93', '雜曲歌辭 長相思二首 一', '杂曲歌辞 长相思二首 一', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["君行登隴上，妾夢在閨中。","玉筯千行落，銀牀一半空。"]', '["君行登隴上，妾梦在閨中。","玉筯千行落，銀牀一半空。"]', '诗', 'shi', '', NULL, '雜曲歌辭 長相思二首 一 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('158d4260-8f5c-4c8e-9ffd-872651a996ad', '雜曲歌辭 長相思二首 二', '杂曲歌辞 长相思二首 二', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["綺席春眠覺，紗窗曉望迷。","朦朧殘夢裏，猶自在遼西。"]', '["綺席春眠覺，紗窗晓望迷。","朦朧殘梦裏，猶自在遼西。"]', '诗', 'shi', '', NULL, '雜曲歌辭 長相思二首 二 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e26f9c9-ef6f-4b26-bf34-c683d1e41786', '雜曲歌辭 長相思', '杂曲歌辞 长相思', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["九月西風興，月冷霜華凝。","思君秋夜長，一夜魂九升。","二月東風來，草坼花心開。","思君春日遲，一日腸九迴。","妾住洛橋北，君住洛橋南。","十五即相識，今年二十三。","有如女蘿草，生在松之側。","蔓短枝苦高，縈迴上不得。","人言人有願，願至天必成。","願作遠方獸，步步比肩行。","願作深山木，枝枝連理生。"]', '["九月西风兴，月冷霜华凝。","思君秋夜长，一夜魂九升。","二月东风来，草坼花心开。","思君春日遲，一日腸九迴。","妾住洛橋北，君住洛橋南。","十五即相識，今年二十三。","有如女蘿草，生在松之側。","蔓短枝苦高，縈迴上不得。","人言人有願，願至天必成。","願作远方獸，步步比肩行。","願作深山木，枝枝連理生。"]', '诗', 'shi', '', NULL, '雜曲歌辭 長相思 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e6ddfac-90eb-4c9f-839d-062601924763', '雜曲歌辭 千里思', '杂曲歌辞 千里思', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["李陵沒胡沙，蘇武還漢家。","迢迢五原關，朔雪亂邊花。","一去隔絕域，思歸但長嗟。","鴻雁向西北，飛書報天涯。"]', '["李陵沒胡沙，蘇武還漢家。","迢迢五原关，朔雪亂邊花。","一去隔絕域，思归但长嗟。","鴻雁向西北，飞书報天涯。"]', '诗', 'shi', '', NULL, '雜曲歌辭 千里思 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09480502-2a86-458b-93be-fc0aca0f9b04', '雜曲歌辭 千里思', '杂曲歌辞 千里思', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["涼州風月美，遙望居延路。","泛泛下天雲，青青緣塞樹。","燕山蘇武上，海島田橫住。","更是草生時，行人出門去。"]', '["涼州风月美，遙望居延路。","泛泛下天云，青青緣塞樹。","燕山蘇武上，海島田橫住。","更是草生时，行人出门去。"]', '诗', 'shi', '', NULL, '雜曲歌辭 千里思 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6393b72d-7d61-4201-9072-e5589b1637ab', '雜曲歌辭 行路難', '杂曲歌辞 行路难', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["君不見長安城北渭橋邊，枯木橫槎臥古田。","昔日含紅復含紫，常時留霧亦留煙。","春景春風花似雪，香車玉轝恆闐咽。","若箇遊人不競攀，若箇倡家不來折。","倡家寶袜蛟龍帔，公子銀鞍千萬騎。","黃鶯一向花嬌春，兩兩三三將子戲。","千尺長條百尺枝，丹桂青榆相蔽虧。","珊瑚葉上鴛鴦鳥，鳳凰巢裏雛鵷兒。","巢傾枝折鳳歸去，條枯葉落狂風吹。","一朝零落無人問，萬古摧殘君詎知。","人生貴賤無終始，倏忽須臾難久恃。","誰家能駐西山日，誰家能堰東流水。","漢家陵樹滿秦川，行來行去盡哀憐。","自昔公卿二千石，咸擬榮華一萬年。","不見朱脣將白貌，惟聞素棘與黃泉。","金貂有時須換酒，玉麈但搖莫計錢。","寄言坐客神仙署，一生一死交情處。","蒼龍闕下君不來，白鶴山前我應去。","雲間海上邈難期，赤心會合在何時？","但願堯年一百萬，長作巢由也不辭。"]', '["君不见长安城北渭橋邊，枯木橫槎臥古田。","昔日含紅复含紫，常时留霧亦留煙。","春景春风花似雪，香车玉轝恆闐咽。","若箇游人不競攀，若箇倡家不来折。","倡家寶袜蛟龙帔，公子銀鞍千万騎。","黄鶯一向花嬌春，兩兩三三將子戲。","千尺长條百尺枝，丹桂青榆相蔽虧。","珊瑚葉上鴛鴦鸟，鳳凰巢裏雛鵷兒。","巢傾枝折鳳归去，條枯葉落狂风吹。","一朝零落無人问，万古摧殘君詎知。","人生貴賤無終始，倏忽須臾难久恃。","誰家能駐西山日，誰家能堰东流水。","漢家陵樹满秦川，行来行去尽哀怜。","自昔公卿二千石，咸擬榮华一万年。","不见朱脣將白貌，惟闻素棘與黄泉。","金貂有时須換酒，玉麈但搖莫計錢。","寄言坐客神仙署，一生一死交情处。","蒼龙闕下君不来，白鹤山前我應去。","云间海上邈难期，赤心會合在何时？","但願堯年一百万，长作巢由也不辞。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8285c2b9-3ad8-4ea6-9b16-3b739380036e', '雜曲歌辭 行路難', '杂曲歌辞 行路难', 'a278f803-7e2e-4648-b861-05c5d6253828', '唐', '["君不見溫家玉鏡臺，提攜抱握九重來。","君不見相如綠綺琴，一撫一拍鳳凰音。","人生意氣須及早，莫負當年行樂心。","荆王奏曲楚妃歎，曲盡歡終夜將半。","朱樓銀閣正平生，碧草青苔坐蕪漫。","當春對酒不須疑，視目相看能幾時。","春風吹盡燕初至，此時自謂稱君意。","秋露萎草鴻始歸，此時衰暮與君違。","人生翻覆何常足，誰保容顏無是非。"]', '["君不见溫家玉镜台，提携抱握九重来。","君不见相如綠綺琴，一撫一拍鳳凰音。","人生意氣須及早，莫負當年行乐心。","荆王奏曲楚妃歎，曲尽歡終夜將半。","朱楼銀閣正平生，碧草青苔坐蕪漫。","當春对酒不須疑，視目相看能幾时。","春风吹尽燕初至，此时自謂稱君意。","秋露萎草鴻始归，此时衰暮與君違。","人生翻覆何常足，誰保容顏無是非。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難 張紘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c4fcc83-5d62-47d2-b232-9f0143ecf61f', '雜曲歌辭 行路難五首 一', '杂曲歌辞 行路难五首 一', '26b83258-6111-419d-be94-30ed576cfe23', '唐', '["君不見嵒下井，百尺不及泉。","君不見山上蒿，數寸凌雲煙。","人生相命亦如此，何苦太息自憂煎。","但願親友長含笑，相逢莫吝杖頭錢。","寒夜邀歡須秉燭，豈得空思花柳年。"]', '["君不见嵒下井，百尺不及泉。","君不见山上蒿，數寸凌云煙。","人生相命亦如此，何苦太息自憂煎。","但願親友长含笑，相逢莫吝杖头錢。","寒夜邀歡須秉燭，豈得空思花柳年。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難五首 一 賀蘭進明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a455576e-eadf-4a75-a283-80266e1054fb', '雜曲歌辭 行路難五首 二', '杂曲歌辞 行路难五首 二', '26b83258-6111-419d-be94-30ed576cfe23', '唐', '["君不見門前柳，榮曜暫時蕭索久。","君不見陌上花，狂風吹去落誰家。","誰家思婦見之歎，蓬首不梳心歷亂。","盛年夫壻長別離，歲暮相逢色凋換。"]', '["君不见门前柳，榮曜暫时蕭索久。","君不见陌上花，狂风吹去落誰家。","誰家思婦见之歎，蓬首不梳心歷亂。","盛年夫壻长別離，歲暮相逢色凋換。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難五首 二 賀蘭進明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05ca1eef-d549-4f8e-b853-1340fbb486b8', '雜曲歌辭 行路難五首 三', '杂曲歌辞 行路难五首 三', '26b83258-6111-419d-be94-30ed576cfe23', '唐', '["君不見荒樹枝，春花落盡蜂不窺。","君不見梁上泥，秋風始高燕不棲。","蕩子從軍事征戰，蛾眉嬋娟空守閨。","獨宿自然堪下淚，況復時聞烏夜啼。"]', '["君不见荒樹枝，春花落尽蜂不窺。","君不见梁上泥，秋风始高燕不棲。","蕩子從軍事征戰，蛾眉嬋娟空守閨。","独宿自然堪下泪，況复时闻烏夜啼。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難五首 三 賀蘭進明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('caddd8da-5834-41d5-a136-9e1a56c7cef2', '雜曲歌辭 行路難五首 四', '杂曲歌辞 行路难五首 四', '26b83258-6111-419d-be94-30ed576cfe23', '唐', '["君不見雲間月，暫盈還復缺。","君不見林下風，聲遠意難窮。","親故平生欲聚散，歡娛未盡尊酒空。","自歎青青陵上柏，歲寒能與幾人同。"]', '["君不见云间月，暫盈還复缺。","君不见林下风，声远意难窮。","親故平生欲聚散，歡娛未尽尊酒空。","自歎青青陵上柏，歲寒能與幾人同。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難五首 四 賀蘭進明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10f85086-3dcd-46d9-8522-d850af4e9975', '雜曲歌辭 行路難五首 五', '杂曲歌辞 行路难五首 五', '26b83258-6111-419d-be94-30ed576cfe23', '唐', '["君不見東流水，一去無窮已。","君不見西郊雲，日夕空氛氳。","羣雁裴回不能去，一雁悲鳴復失羣。","人生結交在終始，莫爲升沈中路分。"]', '["君不见东流水，一去無窮已。","君不见西郊云，日夕空氛氳。","羣雁裴回不能去，一雁悲鳴复失羣。","人生結交在終始，莫爲升沈中路分。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難五首 五 賀蘭進明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf1d7c98-80bb-4886-93a1-ffbd1365dd20', '雜曲歌辭 行路難', '杂曲歌辞 行路难', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["君不見建章宮中金明枝，萬萬長條拂地垂。","二月三月花如霰，九重幽深君不見。","豔彩朝含四寶宮，香風吹入朝雲殿。","漢家宮女春未闌，愛此芳香朝暮看。","看去看來心不忘，攀折將安鏡臺上。","雙雙素手剪不成，兩兩紅妝笑相向。","建章昨夜起春風，一花飛落長信宮。","長信麗人見花泣，憶此珍樹何嗟及。","我昔初在昭陽時，朝折暮折登玉墀。","祗言歲歲長相對，不寤今朝遙相思。"]', '["君不见建章宮中金明枝，万万长條拂地垂。","二月三月花如霰，九重幽深君不见。","豔彩朝含四寶宮，香风吹入朝云殿。","漢家宮女春未闌，愛此芳香朝暮看。","看去看来心不忘，攀折將安镜台上。","雙雙素手剪不成，兩兩紅妝笑相向。","建章昨夜起春风，一花飞落长信宮。","长信丽人见花泣，憶此珍樹何嗟及。","我昔初在昭陽时，朝折暮折登玉墀。","祗言歲歲长相对，不寤今朝遙相思。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('527eba4b-b35c-4d29-99e7-8f40c6f3d5b7', '雜曲歌辭 行路難三首 一', '杂曲歌辞 行路难三首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["金尊清酒斗十千，玉盤珍羞直萬錢。","停杯投筯不能食，拔劒四顧心茫然。","欲渡黃河冰塞川，將登太行雪暗天。","閑來垂釣坐溪上，忽復乘舟夢日邊。","行路難，行路難，多岐路，今安在？","長風破浪會有時，直挂雲帆濟滄海。"]', '["金尊清酒斗十千，玉盤珍羞直万錢。","停杯投筯不能食，拔劒四顧心茫然。","欲渡黄河冰塞川，將登太行雪暗天。","闲来垂釣坐溪上，忽复乘舟梦日邊。","行路难，行路难，多岐路，今安在？","长风破浪會有时，直挂云帆濟滄海。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難三首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e12edd83-36cd-4e8a-a630-91874631c51f', '雜曲歌辭 行路難三首 二', '杂曲歌辞 行路难三首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["大道如青天，我獨不得出。","羞逐長安社中兒，赤雞白狗賭梨栗。","彈劒作歌奏苦聲，曳裾王門不稱情。","淮陰市井笑韓信，漢朝公卿忌賈生。","君不見昔時燕家重郭隗，擁篲折腰無嫌猜。","劇辛樂毅感恩分，輸肝剖膽效英才。","昭王白骨縈蔓草，誰人更掃黃金臺。","行路難，歸去來。"]', '["大道如青天，我独不得出。","羞逐长安社中兒，赤雞白狗賭梨栗。","彈劒作歌奏苦声，曳裾王门不稱情。","淮陰市井笑韓信，漢朝公卿忌賈生。","君不见昔时燕家重郭隗，擁篲折腰無嫌猜。","劇辛乐毅感恩分，輸肝剖膽效英才。","昭王白骨縈蔓草，誰人更掃黄金台。","行路难，归去来。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難三首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4f9c5b3-0108-4127-bf3e-73fd207176f3', '雜曲歌辭 行路難三首 三', '杂曲歌辞 行路难三首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["有耳莫洗潁川水，有口莫食首陽蕨。","含光混世貴無名，何用孤高比雲月。","吾觀自古賢達人，功成不退皆殞身。","子胥既棄吳江上，屈原終投湘水濱。","陸機才多豈自保，李斯稅駕苦不早。","華亭鶴唳詎可聞，上蔡蒼鷹何足道？","君不見吳中張翰稱達士，秋風忽憶江東行。","且樂生前一杯酒，何須身後千載名。"]', '["有耳莫洗潁川水，有口莫食首陽蕨。","含光混世貴無名，何用孤高比云月。","吾观自古賢達人，功成不退皆殞身。","子胥既棄吳江上，屈原終投湘水濱。","陸機才多豈自保，李斯稅駕苦不早。","华亭鹤唳詎可闻，上蔡蒼鷹何足道？","君不见吳中張翰稱達士，秋风忽憶江东行。","且乐生前一杯酒，何須身後千載名。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難三首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5388739-d560-444f-b24b-537db93e7519', '雜曲歌辭 行路難三首 一', '杂曲歌辞 行路难三首 一', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["君不見古來燒水銀，變作北邙山上塵。","藕絲挂身在虛空，欲落不落愁殺人。","睢水英雄多血刃，建章宮闕成灰燼。","淮王身死桂枝折，徐氏一去音書絕。","行路難，行路難，生死皆由天。","秦皇漢武遭下脫，汝獨何人學神仙。"]', '["君不见古来燒水銀，变作北邙山上塵。","藕絲挂身在虛空，欲落不落愁殺人。","睢水英雄多血刃，建章宮闕成灰燼。","淮王身死桂枝折，徐氏一去音书絕。","行路难，行路难，生死皆由天。","秦皇漢武遭下脫，汝独何人学神仙。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難三首 一 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ee919e0-cdff-4594-bc72-3d5d88503cee', '雜曲歌辭 行路難三首 二', '杂曲歌辞 行路难三首 二', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["君不見擔雪塞井徒用力，炊砂作飯豈堪喫。","一生肝膽向人盡，相識不如不相識。","冬青樹上挂凌宵，歲[晏]花凋樹不凋。","凡物各自有根本，種禾終不生豆苗。","行路難，行路難，何處是平道？","中心無事當富貴，今日覺君顏色好。"]', '["君不见擔雪塞井徒用力，炊砂作飯豈堪喫。","一生肝膽向人尽，相識不如不相識。","冬青樹上挂凌宵，歲[晏]花凋樹不凋。","凡物各自有根本，種禾終不生豆苗。","行路难，行路难，何处是平道？","中心無事當富貴，今日覺君顏色好。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難三首 二 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('160c5168-d55c-4a4c-ba73-ae1596f4b900', '雜曲歌辭 行路難三首 三', '杂曲歌辞 行路难三首 三', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["君不見少年頭上如雲髮，少壯如雲老如雪。","豈知灌頂有醍醐，能使清涼頭不熱。","呂梁之水挂飛流，黿鼉蛟蜃不敢游。","少年恃險若平地，獨倚長劒凌清秋。","行路難，行路難，昔少年，今已老。","前朝竹帛事皆空，日暮牛羊古城草。"]', '["君不见少年头上如云髮，少壯如云老如雪。","豈知灌頂有醍醐，能使清涼头不熱。","呂梁之水挂飞流，黿鼉蛟蜃不敢游。","少年恃險若平地，独倚长劒凌清秋。","行路难，行路难，昔少年，今已老。","前朝竹帛事皆空，日暮牛羊古城草。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難三首 三 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('028b5cb7-2c3b-4023-ae17-90d2128c5b75', '雜曲歌辭 行路難', '杂曲歌辞 行路难', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["漢家名臣楊德祖，四代五公享茅土。","父兄子弟綰銀黃，躍馬鳴珂朝建章。","火浣單衣繡方領，茱萸錦帶玉盤囊。","賓客填街復滿坐，片言出口生輝光。","世人逐勢爭奔走，瀝膽隳肝惟恐後。","當時一顧生青雲，自謂生死長隨君。","一朝謝病還鄉里，窮巷蒼茫絕知己。","秋風落葉閉重門，昨日論交竟誰是。","薄俗嗟嗟難重陳，深山麋鹿下爲鄰。","魯連所以蹈滄海，古往今來稱達人。"]', '["漢家名臣楊德祖，四代五公享茅土。","父兄子弟綰銀黄，躍马鳴珂朝建章。","火浣單衣繡方領，茱萸錦带玉盤囊。","賓客填街复满坐，片言出口生輝光。","世人逐勢爭奔走，瀝膽隳肝惟恐後。","當时一顧生青云，自謂生死长隨君。","一朝謝病還乡里，窮巷蒼茫絕知己。","秋风落葉閉重门，昨日論交竟誰是。","薄俗嗟嗟难重陳，深山麋鹿下爲鄰。","魯連所以蹈滄海，古往今来稱達人。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fc49eb5-7f24-4b67-8f25-30348868291d', '雜曲歌辭 行路難二首 一', '杂曲歌辞 行路难二首 一', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["君不見富家翁，昔時貧賤誰比數。","一朝金多結豪貴，萬事勝人健如虎。","子孫成長滿眼前，妻能管弦妾能舞。","自矜一朝忽如此，却笑傍人獨悲苦。","東鄰少年安所如，席門窮巷出無車。"]', '["君不见富家翁，昔时貧賤誰比數。","一朝金多結豪貴，万事勝人健如虎。","子孫成长满眼前，妻能管弦妾能舞。","自矜一朝忽如此，却笑傍人独悲苦。","东鄰少年安所如，席门窮巷出無车。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難二首 一 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba2f4924-7ab8-48f2-9e23-d656dea0117b', '雜曲歌辭 行路難二首 二', '杂曲歌辞 行路难二首 二', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["長安少年不少錢，能騎駿馬鳴金鞭。","五侯相逢大道邊，美人弦管爭留連。","黃金如斗不敢惜，片言如山莫棄捐。","安知顦顇讀書者，暮宿虛臺私自憐。"]', '["长安少年不少錢，能騎駿马鳴金鞭。","五侯相逢大道邊，美人弦管爭留連。","黄金如斗不敢惜，片言如山莫棄捐。","安知顦顇读书者，暮宿虛台私自怜。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難二首 二 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f401d0c-fe7d-4cd2-be76-5e30bfe28f2d', '雜曲歌辭 行路難', '杂曲歌辞 行路难', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["湘東行人長歎息，十年離家歸未得。","弊裘羸馬苦難行，童僕飢寒少筋力。","君不見牀頭黃金盡，壯士無顏色。","龍蟠泥中未有雲，不能生彼升天翼。"]', '["湘东行人长歎息，十年離家归未得。","弊裘羸马苦难行，童僕飢寒少筋力。","君不见牀头黄金尽，壯士無顏色。","龙蟠泥中未有云，不能生彼升天翼。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7111877e-28e4-47cd-bba0-fa2372beccb5', '雜曲歌辭 行路難', '杂曲歌辞 行路难', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["莫言行路難，夷狄如中國。","謂言骨肉親，中門如異域。","出處全在人，路亦無通塞。","門前兩條轍，何處去不得。"]', '["莫言行路难，夷狄如中国。","謂言骨肉親，中门如異域。","出处全在人，路亦無通塞。","门前兩條轍，何处去不得。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('013bf750-098b-4b37-93d9-82c2efea2634', '雜曲歌辭 行路難', '杂曲歌辞 行路难', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["荆山之白玉兮。","良工雕琢雙環連，月蝕中央鏡心穿。","故人贈妾初相結，恩在環中尋不絕。","人情厚薄苦須臾，昔似連環今似玦。","連環可碎不可離，如何物在人自移。","上客勿遽歡，聽妾歌路難。","傍人見環環可憐，不知中有長恨端。"]', '["荆山之白玉兮。","良工雕琢雙环連，月蝕中央镜心穿。","故人贈妾初相結，恩在环中尋不絕。","人情厚薄苦須臾，昔似連环今似玦。","連环可碎不可離，如何物在人自移。","上客勿遽歡，听妾歌路难。","傍人见环环可怜，不知中有长恨端。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07cfcd66-7c89-4b1c-b2c9-82e9ce69fcf3', '雜曲歌辭 行路難三首 一', '杂曲歌辞 行路难三首 一', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["君不見夸父逐日窺虞淵，跳踉北海超崑崙。","披霄決漢出沆漭，瞥裂左右遺星辰。","須臾力盡道渴死，狐鼠蜂蟻爭噬吞。","北方竫人長九寸，開口抵掌更笑喧。","啾啾飲食滴與粒，生死亦足終天年。","睢盱大志少成遂，坐使兒女相悲憐。"]', '["君不见夸父逐日窺虞淵，跳踉北海超崑崙。","披霄決漢出沆漭，瞥裂左右遺星辰。","須臾力尽道渴死，狐鼠蜂蟻爭噬吞。","北方竫人长九寸，开口抵掌更笑喧。","啾啾饮食滴與粒，生死亦足終天年。","睢盱大志少成遂，坐使兒女相悲怜。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難三首 一 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4812c8a-c01e-4340-aa75-13d0a6e5d3ef', '雜曲歌辭 行路難三首 二', '杂曲歌辞 行路难三首 二', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["虞衡斤斧羅千山，工命采斫杙與椽。","深林土翦十取一，百牛連鞅摧雙轅。","萬圍千尋妨道路，東西蹶倒山火焚。","遺餘毫末不見保，躝礫磵壑何當存。","羣材未成質已夭，突兀𡷸豁空巖巒。","柏梁天災武庫火，匠石狼顧相愁冤。","君不見南山棟梁益稀少，愛材養育誰復論。"]', '["虞衡斤斧羅千山，工命采斫杙與椽。","深林土翦十取一，百牛連鞅摧雙轅。","万圍千尋妨道路，东西蹶倒山火焚。","遺餘毫末不见保，躝礫磵壑何當存。","羣材未成質已夭，突兀𡷸豁空巖巒。","柏梁天災武庫火，匠石狼顧相愁冤。","君不见南山棟梁益稀少，愛材養育誰复論。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難三首 二 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8e39b30-119d-4b4f-b557-da792950a2a3', '雜曲歌辭 行路難三首 三', '杂曲歌辞 行路难三首 三', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["飛雪斷道冰成梁，侯家熾炭雕玉房。","蟠龍吐耀虎喙張，熊蹲豹擲爭低昂。","攢巒叢崿射朱光，丹霞翠霧飄奇香。","美人四向迴明璫，雪山冰谷晞太陽。","星躔奔走不得止，奄忽雙燕棲虹梁。","風臺露榭生光飾，死灰棄置參與商。","盛時一去貴反賤，桃笙葵扇安可常。"]', '["飞雪斷道冰成梁，侯家熾炭雕玉房。","蟠龙吐耀虎喙張，熊蹲豹擲爭低昂。","攢巒叢崿射朱光，丹霞翠霧飄奇香。","美人四向迴明璫，雪山冰谷晞太陽。","星躔奔走不得止，奄忽雙燕棲虹梁。","风台露榭生光飾，死灰棄置參與商。","盛时一去貴反賤，桃笙葵扇安可常。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難三首 三 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc57bcad-f98d-4152-ac21-3a633ab7426f', '雜曲歌辭 行路難', '杂曲歌辞 行路难', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["玉堂向夕如無人，絲竹儼然宮商死。","細人何言入君耳？塵生金尊酒如水。","君今不念歲蹉跎，雁天明明涼露多。","華燈青凝久照夜，綵童窈窕虛垂羅。","入宮見妬君不察，莫入此地出風波。"]', '["玉堂向夕如無人，絲竹儼然宮商死。","細人何言入君耳？塵生金尊酒如水。","君今不念歲蹉跎，雁天明明涼露多。","华灯青凝久照夜，綵童窈窕虛垂羅。","入宮见妬君不察，莫入此地出风波。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('955d967d-4df1-48ac-a81f-4965efe8dc37', '雜曲歌辭 行路難五首 一', '杂曲歌辞 行路难五首 一', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["不會當時作天地，剛有多般愚與智。","到頭還用真宰心，何如上下皆清氣。","大道冥冥不知處，那堪頓得羲和轡。","義不義兮仁不仁，擬學長生更容易。","負心爲爐復爲火，緣木求魚應且止。","君不見燒金煉石古帝王，鬼火熒熒白楊裏。"]', '["不會當时作天地，剛有多般愚與智。","到头還用真宰心，何如上下皆清氣。","大道冥冥不知处，那堪頓得羲和轡。","義不義兮仁不仁，擬学长生更容易。","負心爲爐复爲火，緣木求鱼應且止。","君不见燒金煉石古帝王，鬼火熒熒白楊裏。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難五首 一 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efd95247-1ecf-4032-ad4f-4e2b3e875f85', '雜曲歌辭 行路難五首 二', '杂曲歌辞 行路难五首 二', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["君不見道傍廢井生古木，本是驕奢貴人屋。","幾度美人照影來，素綆銀缾濯纖玉。","雲飛雨散今如此，繡闥雕甍作荒谷。","沸渭笙歌君莫誇，不應長是西家哭。","休說遺編行者幾，至竟終須合天理。","敗他成此亦何功，蘇張終作多言鬼。","行路難，行路難，不在羊腸裏。"]', '["君不见道傍廢井生古木，本是驕奢貴人屋。","幾度美人照影来，素綆銀缾濯纖玉。","云飞雨散今如此，繡闥雕甍作荒谷。","沸渭笙歌君莫誇，不應长是西家哭。","休说遺編行者幾，至竟終須合天理。","敗他成此亦何功，蘇張終作多言鬼。","行路难，行路难，不在羊腸裏。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難五首 二 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13b62101-428b-4ace-adab-6491df65e655', '雜曲歌辭 行路難五首 三', '杂曲歌辞 行路难五首 三', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["九有茫茫共堯日，浪死虛生亦非一。","清淨玄音竟不聞，花眼酒腸暗如漆。","或偶因片言隻字登第光二親，又不能獻可替不航要津。","口談羲軒與周孔，履行不及屠沽人。","行路難，行路難，日暮途遠空悲歎。"]', '["九有茫茫共堯日，浪死虛生亦非一。","清淨玄音竟不闻，花眼酒腸暗如漆。","或偶因片言隻字登第光二親，又不能獻可替不航要津。","口談羲軒與周孔，履行不及屠沽人。","行路难，行路难，日暮途远空悲歎。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難五首 三 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b79db72a-d0ca-42d1-846e-43cb64cea188', '雜曲歌辭 行路難五首 四', '杂曲歌辞 行路难五首 四', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["君不見道傍樹有寄生枝，青青鬱鬱同榮衰。","無情之物尚如此，爲人不及還堪悲。","父歸墳兮未朝夕，已分黃金爭田宅。","高堂老母頭似霜，心作數支淚常滴。","我聞忽如負芒刺，不獨爲君空歎息。","古人尺布猶可縫，潯陽義犬令人憶。","寄言世上爲人子，孝義團圓莫如此。"]', '["君不见道傍樹有寄生枝，青青鬱鬱同榮衰。","無情之物尚如此，爲人不及還堪悲。","父归墳兮未朝夕，已分黄金爭田宅。","高堂老母头似霜，心作數支泪常滴。","我闻忽如負芒刺，不独爲君空歎息。","古人尺布猶可縫，潯陽義犬令人憶。","寄言世上爲人子，孝義團圓莫如此。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難五首 四 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18d97728-ded9-4a2d-beb2-d4e66945fcc1', '雜曲歌辭 行路難五首 五', '杂曲歌辞 行路难五首 五', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["君不見山高海深人不測，古往今來轉青碧。","淺近輕浮莫與交，池卑只解生荆棘。","誰道黃金如糞土，張耳陳餘斷消息。","行路難，行路難，君自看。"]', '["君不见山高海深人不測，古往今来轉青碧。","淺近轻浮莫與交，池卑只解生荆棘。","誰道黄金如糞土，張耳陳餘斷消息。","行路难，行路难，君自看。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難五首 五 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0216919e-398c-4028-ac06-ca7b2d4852ba', '雜曲歌辭 行路難二首 一', '杂曲歌辞 行路难二首 一', '405848e7-8d14-42db-a593-f688fd279870', '唐', '["行路難，君好看。","驚波不在黤黮間，小人心裏藏奔湍。","七盤九折寒崷崪，翻車倒蓋猶堪出。","未似是非脣舌危，闇中潛毀平人骨。","君不見楚靈均，千古沈冤湘水濱。","又不見李太白，一朝却作江南客。"]', '["行路难，君好看。","驚波不在黤黮间，小人心裏藏奔湍。","七盤九折寒崷崪，翻车倒蓋猶堪出。","未似是非脣舌危，闇中潛毀平人骨。","君不见楚靈均，千古沈冤湘水濱。","又不见李太白，一朝却作江南客。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難二首 一 僧齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5935b82-f49f-4547-ac41-fd71911825d8', '雜曲歌辭 行路難二首 二', '杂曲歌辞 行路难二首 二', '405848e7-8d14-42db-a593-f688fd279870', '唐', '["下浸與高盤，不爲行路難。","是非真險惡，翻覆作峰巒。","漆媿同時黑，朱慙巧處丹。","令人畏相識，欲畫白雲看。"]', '["下浸與高盤，不爲行路难。","是非真險惡，翻覆作峰巒。","漆媿同时黑，朱慙巧处丹。","令人畏相識，欲畫白云看。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難二首 二 僧齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('832147f1-7dcc-4626-b3fc-0d197f29ad77', '雜曲歌辭 行路難', '杂曲歌辞 行路难', '60e56738-e921-4ab7-a3b3-c2203aac059b', '唐', '["行路艱難不復歌，故人榮達我蹉跎。","雙輪晚上銅梁雪，一葉春浮瘴海波。","自古要津皆若此，方今失路欲如何？","君看西漢翟丞相，鳳沼朝辭暮雀羅。"]', '["行路艱难不复歌，故人榮達我蹉跎。","雙輪晚上銅梁雪，一葉春浮瘴海波。","自古要津皆若此，方今失路欲如何？","君看西漢翟丞相，鳳沼朝辞暮雀羅。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難 翁綬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('debe2ac4-0b95-48c8-b3b1-33f5600b04c0', '雜曲歌辭 行路難', '杂曲歌辞 行路难', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["何處力堪殫？人心險萬端。","藏山難測度，暗水自波瀾。","對面如千里，迴腸似七盤。","已經吳坂困，欲向鴈門難。","南北誠須泣，高深不可干。","無因善行止，車轍得平安。"]', '["何处力堪殫？人心險万端。","藏山难測度，暗水自波瀾。","对面如千里，迴腸似七盤。","已經吳坂困，欲向鴈门难。","南北誠須泣，高深不可干。","無因善行止，车轍得平安。"]', '诗', 'shi', '', NULL, '雜曲歌辭 行路難 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a50fdaca-5397-4000-8c2c-bfcb9ab8e681', '雜曲歌辭 從軍中行路難二首 一', '杂曲歌辞 從軍中行路难二首 一', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["君不見封狐雄虺自成羣，馮深負固結妖氛。","玉璽分兵徵惡少，金壇受律動將軍。","將軍擁旄宣廟略，戰士橫行靜夷落。","長驅一息背銅梁，直指三巴逾劒閣。","閣道岧嶤上戍樓，劒門遙裔俯靈丘。","邛關九折無平路，江水雙源有急流。","征役無期返，他鄉歲華晚。","杳杳丘陵出，蒼蒼林薄遠。","途危紫蓋峰，路澀青泥坂。","去去指哀牢，行行入不毛。","絕壁千里險，連山四望高。","中外分區宇，夷夏殊風土。","交趾枕南荒，昆彌臨北戶。","川源饒毒霧，溪谷多淫雨。","行潦四時流，崩查千歲古。","漂梗飛蓬不自安，捫藤引葛度危巒。","昔時聞道從軍樂，今日方知行路難。","蒼江綠水東流駛，炎洲丹徼南中地。","南中南斗映星河，秦川秦塞阻煙波。","三春邊地風光少，五月瀘中瘴癘多。","朝驅疲斥候，夕息倦誰何。","向月彎繁弱，連星轉太阿。","重義輕生懷一顧，東伐西征凡幾度。","夜夜朝朝斑鬢新，年年歲歲戎衣故。","灞城隅，滇池水，天涯望轉積，地際行無已。","徒覺炎涼節物非，不知關山千萬里。","棄置勿重陳，重陳多苦辛。","且悅清笳楊柳曲，詎憶芳園桃李人。","絳節朱旗分白羽，丹心白刃酬明主。","但令一技君王識，誰憚三邊征戰苦。","行路難，行路難，岐路幾千端。","無復歸雲馮短翰，望日想長安。"]', '["君不见封狐雄虺自成羣，馮深負固結妖氛。","玉璽分兵徵惡少，金壇受律动將軍。","將軍擁旄宣廟略，戰士橫行静夷落。","长驱一息背銅梁，直指三巴逾劒閣。","閣道岧嶤上戍楼，劒门遙裔俯靈丘。","邛关九折無平路，江水雙源有急流。","征役無期返，他乡歲华晚。","杳杳丘陵出，蒼蒼林薄远。","途危紫蓋峰，路澀青泥坂。","去去指哀牢，行行入不毛。","絕壁千里險，連山四望高。","中外分區宇，夷夏殊风土。","交趾枕南荒，昆彌臨北戶。","川源饒毒霧，溪谷多淫雨。","行潦四时流，崩查千歲古。","漂梗飞蓬不自安，捫藤引葛度危巒。","昔时闻道從軍乐，今日方知行路难。","蒼江綠水东流駛，炎洲丹徼南中地。","南中南斗映星河，秦川秦塞阻煙波。","三春邊地风光少，五月瀘中瘴癘多。","朝驱疲斥候，夕息倦誰何。","向月彎繁弱，連星轉太阿。","重義轻生懷一顧，东伐西征凡幾度。","夜夜朝朝斑鬢新，年年歲歲戎衣故。","灞城隅，滇池水，天涯望轉積，地際行無已。","徒覺炎涼節物非，不知关山千万里。","棄置勿重陳，重陳多苦辛。","且悅清笳楊柳曲，詎憶芳园桃李人。","絳節朱旗分白羽，丹心白刃酬明主。","但令一技君王識，誰憚三邊征戰苦。","行路难，行路难，岐路幾千端。","無复归云馮短翰，望日想长安。"]', '诗', 'shi', '', NULL, '雜曲歌辭 從軍中行路難二首 一 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ede162c2-2d52-4ead-a96f-5e14e96369ac', '雜曲歌辭 從軍中行路難二首 二', '杂曲歌辞 從軍中行路难二首 二', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["君不見玉關塵色暗邊亭，銅鞮雜虜寇長城。","天子按劒徵餘勇，將軍受脤事橫行。","七德龍韜開玉帳，千里鼉鼓疊金鉦。","陰山苦霧埋高壘，交河孤月照連營。","連營去去無窮極，擁斾遙遙過絕國。","陣雲朝結晦天山，寒沙夕漲迷疎勒。","龍鱗水上開魚貫，馬首山前振鵰翼。","長驅萬里讋祁連，分麾三命武功宣。","百發烏號遙碎柳，七尺龍文迥照蓮。","春來秋去移灰琯，蘭閨柳市芳塵斷。","鴈門迢遰尺書稀，鴛被相思雙帶緩。","行路難，誓令氛祲靜皐蘭。","但使封侯龍額貴，詎隨中婦鳳樓寒。"]', '["君不见玉关塵色暗邊亭，銅鞮杂虜寇长城。","天子按劒徵餘勇，將軍受脤事橫行。","七德龙韜开玉帳，千里鼉鼓叠金鉦。","陰山苦霧埋高壘，交河孤月照連營。","連營去去無窮極，擁斾遙遙過絕国。","陣云朝結晦天山，寒沙夕漲迷疎勒。","龙鱗水上开鱼貫，马首山前振鵰翼。","长驱万里讋祁連，分麾三命武功宣。","百發烏號遙碎柳，七尺龙文迥照蓮。","春来秋去移灰琯，蘭閨柳市芳塵斷。","鴈门迢遰尺书稀，鴛被相思雙带緩。","行路难，誓令氛祲静皐蘭。","但使封侯龙額貴，詎隨中婦鳳楼寒。"]', '诗', 'shi', '', NULL, '雜曲歌辭 從軍中行路難二首 二 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('447e1bf3-306c-4dc3-86db-6a279f2a8257', '雜曲歌辭 變行路難', '杂曲歌辞 变行路难', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["向晚橫吹悲，風動馬嘶合。","前驅引旗節，千重陣雲帀。","單于下陰山，砂礫空颯颯。","封侯取一戰，豈復念閨閤。"]', '["向晚橫吹悲，风动马嘶合。","前驱引旗節，千重陣云帀。","單于下陰山，砂礫空颯颯。","封侯取一戰，豈复念閨閤。"]', '诗', 'shi', '', NULL, '雜曲歌辭 變行路難 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b939a56-7ec3-4f83-a887-48db856ae272', '雜曲歌辭 古別離', '杂曲歌辞 古別離', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["白水東悠悠，中有西行舟。","舟行有返棹，水去無還流。","奈何生別者，戚戚懷遠遊。","遠遊誰當惜，所悲會難收。","自君間芳躧，青陽四五遒。","皓月掩蘭室，光風虛蕙樓。","相思無明晦，長歎累冬秋。","離居分遲暮，駕高何淹留。"]', '["白水东悠悠，中有西行舟。","舟行有返棹，水去無還流。","奈何生別者，戚戚懷远游。","远游誰當惜，所悲會难收。","自君间芳躧，青陽四五遒。","皓月掩蘭室，光风虛蕙楼。","相思無明晦，长歎累冬秋。","離居分遲暮，駕高何淹留。"]', '诗', 'shi', '', NULL, '雜曲歌辭 古別離 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d85a6f55-150a-4e1e-8382-c9ba95c38f39', '雜曲歌辭 古別離', '杂曲歌辞 古別離', 'aafdb19f-05e9-4e14-911a-2b39ebf7f1af', '唐', '["朝日上高臺，離人怨秋草。","但見萬里天，不見萬里道。","君行本遙遠，苦樂良難保。","宿昔夢同衾，憂心夢顛倒。","含酸欲誰訴，轉轉傷懷抱。","結髮年已遲，征行去何早。","寒暄有時謝，顦顇難再好。","人皆算年壽，死者何曾老。","少壯無見期，水深風浩浩。"]', '["朝日上高台，離人怨秋草。","但见万里天，不见万里道。","君行本遙远，苦乐良难保。","宿昔梦同衾，憂心梦顛倒。","含酸欲誰訴，轉轉傷懷抱。","結髮年已遲，征行去何早。","寒暄有时謝，顦顇难再好。","人皆算年壽，死者何曾老。","少壯無见期，水深风浩浩。"]', '诗', 'shi', '', NULL, '雜曲歌辭 古別離 孟雲卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8ca61a8-148b-4046-8829-7165fc6cb503', '雜曲歌辭 古別離', '杂曲歌辞 古別離', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["雙劒欲別風悽然，雌沈水底雄上天。","江迴漢轉兩不見，雲交雨合知何年。","古來萬事皆由命，何用臨岐苦涕漣。"]', '["雙劒欲別风悽然，雌沈水底雄上天。","江迴漢轉兩不见，云交雨合知何年。","古来万事皆由命，何用臨岐苦涕漣。"]', '诗', 'shi', '', NULL, '雜曲歌辭 古別離 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d47d568-f9fa-4e5f-8dcb-9ae5ac6c2cac', '雜曲歌辭 古別離二首 一', '杂曲歌辞 古別離二首 一', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["入室少情意，出門多路岐。","黃鶴有歸日，蕩子無還時。","人誰無分命，妾身何太奇。","君爲東南風，妾作西北枝。","青樓鄰里婦，終年畫長眉。","自倚對良匹，笑妾空羅幃。"]', '["入室少情意，出门多路岐。","黄鹤有归日，蕩子無還时。","人誰無分命，妾身何太奇。","君爲东南风，妾作西北枝。","青楼鄰里婦，終年畫长眉。","自倚对良匹，笑妾空羅幃。"]', '诗', 'shi', '', NULL, '雜曲歌辭 古別離二首 一 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24d00fc4-4043-4ce6-bb89-efcb1f3b3d7c', '雜曲歌辭 古別離二首 二', '杂曲歌辞 古別離二首 二', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["郎本東家兒，妾本西家女。","對門中道間，終謂無離阻。","豈知中道間，遣作空閨主。","自是愛封侯，非關備胡虜。"]', '["郎本东家兒，妾本西家女。","对门中道间，終謂無離阻。","豈知中道间，遣作空閨主。","自是愛封侯，非关備胡虜。"]', '诗', 'shi', '', NULL, '雜曲歌辭 古別離二首 二 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fcf9b47-d7b1-4d40-9121-99c57c4747e3', '雜曲歌辭 古別離二首 一', '杂曲歌辞 古別離二首 一', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["水國葉黃時，洞庭霜落夜。","行舟聞商估，宿在楓林下。","此地送君還，茫茫似夢間。","後期知幾日，前路轉多山。","巫峽通湘浦，迢迢隔雲雨。","天晴見海檣，月落聞津鼓。","人老自多愁，水深難急流。","清宵歌一曲，白首對汀洲。"]', '["水国葉黄时，洞庭霜落夜。","行舟闻商估，宿在楓林下。","此地送君還，茫茫似梦间。","後期知幾日，前路轉多山。","巫峽通湘浦，迢迢隔云雨。","天晴见海檣，月落闻津鼓。","人老自多愁，水深难急流。","清宵歌一曲，白首对汀洲。"]', '诗', 'shi', '', NULL, '雜曲歌辭 古別離二首 一 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04f7819f-2ca3-43bf-afbc-26cb4f5cd0f1', '雜曲歌辭 古別離二首 二', '杂曲歌辞 古別離二首 二', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["與君桂陽別，令君岳陽待。","後事忽差池，前期日空在。","木落鴈嗷嗷，洞庭波浪高。","遠山雲似蓋，極浦樹如毫。","朝發能幾里，暮來風又起。","如何兩處愁，皆在孤舟裏。","昨夜天月明，長川寒且清。","菊花開欲盡，薺菜拍來生。","下江帆勢速，五兩遙相逐。","欲問去時人，知投何處宿。","空令猨嘯時，泣對湘潭竹。"]', '["與君桂陽別，令君岳陽待。","後事忽差池，前期日空在。","木落鴈嗷嗷，洞庭波浪高。","远山云似蓋，極浦樹如毫。","朝發能幾里，暮来风又起。","如何兩处愁，皆在孤舟裏。","昨夜天月明，长川寒且清。","菊花开欲尽，薺菜拍来生。","下江帆勢速，五兩遙相逐。","欲问去时人，知投何处宿。","空令猨嘯时，泣对湘潭竹。"]', '诗', 'shi', '', NULL, '雜曲歌辭 古別離二首 二 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d842953e-6c4b-46bf-8eed-3315ad11c7fc', '雜曲歌辭 古別離', '杂曲歌辞 古別離', '2ade647f-1bae-48ff-94d0-3b438f1df412', '唐', '["下階欲離別，相對映蘭叢。","含辭未及吐，淚落蘭叢中。","高堂靜秋日，羅衣飄暮風。","誰能待明月，迴首見牀空。"]', '["下階欲離別，相对映蘭叢。","含辞未及吐，泪落蘭叢中。","高堂静秋日，羅衣飄暮风。","誰能待明月，迴首见牀空。"]', '诗', 'shi', '', NULL, '雜曲歌辭 古別離 王縉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0457d34c-f28a-47a0-aa77-ab3b3a3b14e7', '雜曲歌辭 古別離', '杂曲歌辞 古別離', 'd031d511-00fb-47fd-8345-864309b121e2', '唐', '["太湖三山口，吳王在時道。","寂寞千載心，無人見春草。","誰堪緘怨者，持此傷懷抱。","孤舟畏狂風，一點宿煙島。","望所思兮若何，月蕩漾兮空波。","雲離離兮北斷，鴈眇眇兮南多。","身去兮天畔，心折兮湖岸。","春山胡爲兮塞路，使我歸夢兮撩亂。"]', '["太湖三山口，吳王在时道。","寂寞千載心，無人见春草。","誰堪緘怨者，持此傷懷抱。","孤舟畏狂风，一点宿煙島。","望所思兮若何，月蕩漾兮空波。","云離離兮北斷，鴈眇眇兮南多。","身去兮天畔，心折兮湖岸。","春山胡爲兮塞路，使我归梦兮撩亂。"]', '诗', 'shi', '', NULL, '雜曲歌辭 古別離 僧皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dae495a8-d198-4fe8-86d6-a56da79ac7b6', '雜曲歌辭 古別離', '杂曲歌辞 古別離', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["欲別牽郎衣，問郎遊何處？不恨歸日遲，莫向臨邛去。"]', '["欲別牽郎衣，问郎游何处？不恨归日遲，莫向臨邛去。"]', '诗', 'shi', '', NULL, '雜曲歌辭 古別離 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83383a17-2f32-4c5e-a25b-1b1d9c7873a1', '雜曲歌辭 古別離二首 一', '杂曲歌辞 古別離二首 一', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["古人謾歌西飛燕，十年不見狂夫面。","三更風作切夢刀，萬轉愁成繫腸線。","所嗟不及牛女星，一年一度得相見。"]', '["古人謾歌西飞燕，十年不见狂夫面。","三更风作切梦刀，万轉愁成繫腸線。","所嗟不及牛女星，一年一度得相见。"]', '诗', 'shi', '', NULL, '雜曲歌辭 古別離二首 一 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b693eaa3-5152-47da-bb89-56ac4b2d11cd', '雜曲歌辭 古別離二首 二', '杂曲歌辞 古別離二首 二', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["老母別愛子，少妻送征郎。","血流既四面，乃亦斷二腸。","不愁寒無衣，不怕飢無糧。","惟恐征戰不還鄉，母化爲鬼妻爲孀。"]', '["老母別愛子，少妻送征郎。","血流既四面，乃亦斷二腸。","不愁寒無衣，不怕飢無糧。","惟恐征戰不還乡，母化爲鬼妻爲孀。"]', '诗', 'shi', '', NULL, '雜曲歌辭 古別離二首 二 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53ba7bdc-7c71-435f-b93c-7d7479e6f239', '雜曲歌辭 古別離', '杂曲歌辞 古別離', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["紫燕黃鵠雖別離，一舉千里何難追。","猶聞啼風與叫月，流連斷續令人悲。","賦情更有深繾綣，碧甃千尋尚爲淺。","蟾蜍正向清夜流，蛺蝶須教墮絲罥。","莫道斷絲不可續，丹穴鳳皇膠不遠。","草草通流水不迴，海上兩潮長不返。"]', '["紫燕黄鵠雖別離，一舉千里何难追。","猶闻啼风與叫月，流連斷續令人悲。","賦情更有深繾綣，碧甃千尋尚爲淺。","蟾蜍正向清夜流，蛺蝶須教墮絲罥。","莫道斷絲不可續，丹穴鳳皇膠不远。","草草通流水不迴，海上兩潮长不返。"]', '诗', 'shi', '', NULL, '雜曲歌辭 古別離 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('567a2bed-87c9-40d6-9a49-6a6fcf776f9d', '雜曲歌辭 古離別', '杂曲歌辞 古離別', '9769f322-5a6d-4289-9676-aa8c22fc0c0d', '唐', '["昔歲驚楊柳，高樓悲獨守。","今年芳樹枝，孤棲怨別離。","珠簾晝不卷，羅幔曉長垂。","苦調琴先覺，愁容鏡獨知。","頻來鴈度無消息，罷去鴛文何用織。","夜還羅帳空有情，春著帬腰自無力。","青軒桃李落紛紛，紫庭蘭蕙日氛氳。","已能顦顇今如此，更復含情一待君。"]', '["昔歲驚楊柳，高楼悲独守。","今年芳樹枝，孤棲怨別離。","珠簾晝不卷，羅幔晓长垂。","苦調琴先覺，愁容镜独知。","頻来鴈度無消息，罷去鴛文何用织。","夜還羅帳空有情，春著帬腰自無力。","青軒桃李落紛紛，紫庭蘭蕙日氛氳。","已能顦顇今如此，更复含情一待君。"]', '诗', 'shi', '', NULL, '雜曲歌辭 古離別 王適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8373bfa-2eab-4e53-9f5c-aa41d9b065d6', '雜曲歌辭 古離別', '杂曲歌辞 古離別', '5b86c69d-c7a8-4466-ad20-8a0da4247ada', '唐', '["君御狐白裘，妾居緗綺幬。","粟鈿金夾膝，花錯玉搔頭。","離別生庭草，征行斷戍樓。","蠨蛸網清曙，菡萏落紅秋。","小膽空房怯，長眉滿鏡愁。","爲傳兒女意，不用遠封侯。"]', '["君御狐白裘，妾居緗綺幬。","粟鈿金夾膝，花錯玉搔头。","離別生庭草，征行斷戍楼。","蠨蛸網清曙，菡萏落紅秋。","小膽空房怯，长眉满镜愁。","爲傳兒女意，不用远封侯。"]', '诗', 'shi', '', NULL, '雜曲歌辭 古離別 常理 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65fb6fba-0ddb-449d-aea5-06cc005fba45', '雜曲歌辭 古離別', '杂曲歌辞 古離別', '0ab6f8e7-3f21-45c3-9779-ad1dd0babe39', '唐', '["涼風已嫋嫋，露重木蘭枝。","獨上高樓望，行人遠不知。","輕寒入洞戶，明月滿秋池。","燕去鴻方至，年年是別離。"]', '["涼风已嫋嫋，露重木蘭枝。","独上高楼望，行人远不知。","轻寒入洞戶，明月满秋池。","燕去鴻方至，年年是別離。"]', '诗', 'shi', '', NULL, '雜曲歌辭 古離別 姚係 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdeb9b53-185c-4b96-a83e-adbf55f4e59e', '雜曲歌辭 古離別', '杂曲歌辞 古離別', 'a74e1c3c-a964-42b7-ad56-831e95bee5be', '唐', '["離別無遠近，事歡情亦悲。","不聞車輪聲，後會將何時。","去日忘寄書，來日乖前期。","縱知明當還，一夕千萬思。"]', '["離別無远近，事歡情亦悲。","不闻车輪声，後會將何时。","去日忘寄书，来日乖前期。","縱知明當還，一夕千万思。"]', '诗', 'shi', '', NULL, '雜曲歌辭 古離別 張彪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc78a304-0ac7-4e42-b904-6fabc0de0149', '雜曲歌辭 古離別', '杂曲歌辞 古離別', '56c46543-e89e-4b9a-8fb8-6d9f0b651f77', '唐', '["違別未幾日，一日如三秋。","猶疑望可見，日日上高樓。","惟見分手處，白蘋滿芳洲。","寸心寧死別，不忍生離愁。"]', '["違別未幾日，一日如三秋。","猶疑望可见，日日上高楼。","惟见分手处，白蘋满芳洲。","寸心寧死別，不忍生離愁。"]', '诗', 'shi', '', NULL, '雜曲歌辭 古離別 趙微明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6aad1c8-38bc-44bd-a516-d9a87a0aea99', '雜曲歌辭 古離別二首 一', '杂曲歌辞 古離別二首 一', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["松山雲繚繞，萍路水分離。","雲去有歸日，水分無合時。","春芳役雙眼，春色柔四支。","楊柳織別愁，千條萬條絲。"]', '["松山云繚繞，萍路水分離。","云去有归日，水分無合时。","春芳役雙眼，春色柔四支。","楊柳织別愁，千條万條絲。"]', '诗', 'shi', '', NULL, '雜曲歌辭 古離別二首 一 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08b42e3e-75d5-46ef-abe7-bc5cd02668d8', '雜曲歌辭 古離別二首 二', '杂曲歌辞 古離別二首 二', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["山川古今路，縱橫無斷絕。","來往天地間，人皆有離別。","行衣未束帶，中腸已先結。","不用看鏡中，自知生白髮。","欲陳去留意，聲向言前咽。","愁結填心胸，茫茫若爲說。","荒郊煙莽蒼，曠野風淒切。","處處得相隨，人那不如月。"]', '["山川古今路，縱橫無斷絕。","来往天地间，人皆有離別。","行衣未束带，中腸已先結。","不用看镜中，自知生白髮。","欲陳去留意，声向言前咽。","愁結填心胸，茫茫若爲说。","荒郊煙莽蒼，曠野风淒切。","处处得相隨，人那不如月。"]', '诗', 'shi', '', NULL, '雜曲歌辭 古離別二首 二 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00b4d14e-5b09-485b-a9f7-5d6e9b9629b4', '雜曲歌辭 古離別', '杂曲歌辞 古離別', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["西江上，風動麻姑嫁時浪。","西山爲水水爲塵，不是人間離別人。"]', '["西江上，风动麻姑嫁时浪。","西山爲水水爲塵，不是人间離別人。"]', '诗', 'shi', '', NULL, '雜曲歌辭 古離別 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9185b303-813a-493d-ae09-5d4979cd90ef', '雜曲歌辭 古離別', '杂曲歌辞 古離別', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["離恨如旨酒，古今飲皆醉。","只恐長江水，盡是兒女淚。","伊余非此輩，送人空把臂。","他日再相逢，清風動天地。"]', '["離恨如旨酒，古今饮皆醉。","只恐长江水，尽是兒女泪。","伊余非此輩，送人空把臂。","他日再相逢，清风动天地。"]', '诗', 'shi', '', NULL, '雜曲歌辭 古離別 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f71778d1-64c3-4270-a9ce-4a94f16c9462', '雜曲歌辭 古離別', '杂曲歌辞 古離別', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["晴煙漠漠柳毿毿，不那離情酒半酣。","更把馬鞭雲外指，斷腸春色在江南。"]', '["晴煙漠漠柳毿毿，不那離情酒半酣。","更把马鞭云外指，斷腸春色在江南。"]', '诗', 'shi', '', NULL, '雜曲歌辭 古離別 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a2bdab8-9e68-4478-ade8-11d5fbb822c6', '雜曲歌辭 生別離', '杂曲歌辞 生別離', 'aafdb19f-05e9-4e14-911a-2b39ebf7f1af', '唐', '["結髮生別離，相思復相保。","何知日已久，五變庭中草。","眇眇天海途，悠悠吳江島。","但恐不出門，出門無遠道。","遠道行既難，家貧衣服單。","嚴風吹積雪，晨起鼻何酸。","人生各有戀，豈不懷所安。","分明天上日，生死誓同歡。"]', '["結髮生別離，相思复相保。","何知日已久，五变庭中草。","眇眇天海途，悠悠吳江島。","但恐不出门，出门無远道。","远道行既难，家貧衣服單。","嚴风吹積雪，晨起鼻何酸。","人生各有戀，豈不懷所安。","分明天上日，生死誓同歡。"]', '诗', 'shi', '', NULL, '雜曲歌辭 生別離 孟雲卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdb32446-6efc-402e-93f0-901b8eefe57e', '雜曲歌辭 生別離', '杂曲歌辞 生別離', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["食蘗不易食梅難，蘗能苦兮梅能酸。","未如生別之爲難，苦在心兮酸在肝。","晨雞載鳴殘月沒，征馬重嘶行人出。","迴看骨肉哭一聲，梅酸蘗苦甘如蜜。","黃河水白黃雲秋，行人河邊相對愁。","天寒野曠何處宿？棠梨葉戰風颼颼。","生離別，生離別，憂從中來無斷絕。","憂積心勞血氣衰，未年三十生白髮。"]', '["食蘗不易食梅难，蘗能苦兮梅能酸。","未如生別之爲难，苦在心兮酸在肝。","晨雞載鳴殘月沒，征马重嘶行人出。","迴看骨肉哭一声，梅酸蘗苦甘如蜜。","黄河水白黄云秋，行人河邊相对愁。","天寒野曠何处宿？棠梨葉戰风颼颼。","生離別，生離別，憂從中来無斷絕。","憂積心勞血氣衰，未年三十生白髮。"]', '诗', 'shi', '', NULL, '雜曲歌辭 生別離 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('495e6bc4-42a4-463e-ac80-b4fa4a6ea878', '雜曲歌辭 遠別離', '杂曲歌辞 远別離', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["遠別離，古有皇英之二女，乃在洞庭之南，瀟湘之浦。","海水直下萬里深，誰人不言此離苦。","日慘慘兮雲冥冥，猩猩啼煙兮鬼嘯雨。","我縱言之將何補，皇穹竊恐不照余之忠誠。","雷馮馮兮欲吼怒，堯舜當之亦禪禹。","君失臣兮龍爲魚，權歸臣兮鼠變虎。","或云堯幽囚，舜野死，九疑聯緜皆相似，重瞳孤墳竟何是。","帝子泣兮綠雲間，隨風波兮去無還。","慟哭兮遠望，見蒼梧之深山。","蒼梧山崩湘水絕，竹上之淚乃可滅。"]', '["远別離，古有皇英之二女，乃在洞庭之南，瀟湘之浦。","海水直下万里深，誰人不言此離苦。","日慘慘兮云冥冥，猩猩啼煙兮鬼嘯雨。","我縱言之將何補，皇穹竊恐不照余之忠誠。","雷馮馮兮欲吼怒，堯舜當之亦禪禹。","君失臣兮龙爲鱼，權归臣兮鼠变虎。","或云堯幽囚，舜野死，九疑聯緜皆相似，重瞳孤墳竟何是。","帝子泣兮綠云间，隨风波兮去無還。","慟哭兮远望，见蒼梧之深山。","蒼梧山崩湘水絕，竹上之泪乃可滅。"]', '诗', 'shi', '', NULL, '雜曲歌辭 遠別離 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f866479-db88-497f-b2b6-29dcb0ec2a63', '雜曲歌辭 遠別離', '杂曲歌辞 远別離', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["蓮葉團團杏花拆，長江鯉魚鰭鬣赤。","念君少年棄親戚，千里萬里獨爲客。","誰言遠別心不易，天星墜地能爲石。","幾時斷得城南陌，勿使居人有行役。"]', '["蓮葉團團杏花拆，长江鯉鱼鰭鬣赤。","念君少年棄親戚，千里万里独爲客。","誰言远別心不易，天星墜地能爲石。","幾时斷得城南陌，勿使居人有行役。"]', '诗', 'shi', '', NULL, '雜曲歌辭 遠別離 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c76bd40-ab40-4b1d-97ed-c3a3dd2d8310', '雜曲歌辭 遠別離二首 一', '杂曲歌辞 远別離二首 一', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["楊柳黃金穗，梧桐碧玉枝。","春來消息斷，早晚是歸時。"]', '["楊柳黄金穗，梧桐碧玉枝。","春来消息斷，早晚是归时。"]', '诗', 'shi', '', NULL, '雜曲歌辭 遠別離二首 一 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66793505-27a2-4119-beb5-fc018b062fbc', '雜曲歌辭 遠別離二首 二', '杂曲歌辞 远別離二首 二', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["玳織鴛鴦履，金裝翡翠簪。","畏人相問著，不擬到城南。"]', '["玳织鴛鴦履，金裝翡翠簪。","畏人相问著，不擬到城南。"]', '诗', 'shi', '', NULL, '雜曲歌辭 遠別離二首 二 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a57cefe-4ed5-4655-ace2-08edb17cdba1', '雜曲歌辭 久別離', '杂曲歌辞 久別離', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["別來幾春未還家，玉窗五見櫻桃花。","況有錦字書，開緘使人嗟。","至此腸斷彼心絕，雲鬟綠鬢罷攬結。","愁如迴飆亂白雪，去年寄書報陽臺。","今年寄書重相催，胡爲東風爲我吹行雲。","使西來，待來竟不來，落花寂寂委青苔。"]', '["別来幾春未還家，玉窗五见櫻桃花。","況有錦字书，开緘使人嗟。","至此腸斷彼心絕，云鬟綠鬢罷攬結。","愁如迴飆亂白雪，去年寄书報陽台。","今年寄书重相催，胡爲东风爲我吹行云。","使西来，待来竟不来，落花寂寂委青苔。"]', '诗', 'shi', '', NULL, '雜曲歌辭 久別離 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f1de501-ff4c-4292-8b4c-5141753afc5d', '雜曲歌辭 新別離', '杂曲歌辞 新別離', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["手把杏花枝，未曾經別離。","黃昏掩閨後，寂寞自心知。"]', '["手把杏花枝，未曾經別離。","黄昏掩閨後，寂寞自心知。"]', '诗', 'shi', '', NULL, '雜曲歌辭 新別離 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae14b4a7-e09b-4151-ab64-307800f6d5a7', '雜曲歌辭 今別離', '杂曲歌辞 今別離', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["送別未能旋，相望連水口。","船行欲映洲，幾度急搖手。"]', '["送別未能旋，相望連水口。","船行欲映洲，幾度急搖手。"]', '诗', 'shi', '', NULL, '雜曲歌辭 今別離 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e6f2405-6495-4b50-a112-addbd8054f84', '雜曲歌辭 暗別離', '杂曲歌辞 暗別離', 'c834c091-89d5-4a2d-8a15-34f28374584e', '唐', '["槐花結子桐葉焦，單飛越鳥嗁青霄。","翠軒輾雲輕遙遙，燕脂淚迸紅線條。","瑤草歇芳心耿耿，玉佩無聲畫屏冷。","朱弦暗斷不見人，風動花枝月中影。","青鸞脈脈西飛去，海闊天高不知處。"]', '["槐花結子桐葉焦，單飞越鸟嗁青霄。","翠軒輾云轻遙遙，燕脂泪迸紅線條。","瑤草歇芳心耿耿，玉佩無声畫屏冷。","朱弦暗斷不见人，风动花枝月中影。","青鸾脈脈西飞去，海闊天高不知处。"]', '诗', 'shi', '', NULL, '雜曲歌辭 暗別離 劉氏瑤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a33b0c7a-27af-4daf-9d0d-2d64f8db478b', '雜曲歌辭 潛別離', '杂曲歌辞 潛別離', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["不得哭，潛別離，不得語，暗相思，兩心之外無人知。","深籠夜[鎖]獨棲鳥，利劒[春]斷連理枝。","河水雖濁有清日，烏頭雖黑有白時。","惟有潛離與暗別，彼此甘心無後期。"]', '["不得哭，潛別離，不得語，暗相思，兩心之外無人知。","深籠夜[鎖]独棲鸟，利劒[春]斷連理枝。","河水雖濁有清日，烏头雖黑有白时。","惟有潛離與暗別，彼此甘心無後期。"]', '诗', 'shi', '', NULL, '雜曲歌辭 潛別離 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab88405a-eab9-4b19-8179-7471d5d865ce', '雜曲歌辭 別離曲', '杂曲歌辞 別離曲', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["行人結束出門去，馬蹏幾時踏門路。","憶昔君初納綵時，不言身屬遼陽戍。","早知今日當別離，成君家計良爲誰。","男兒生身自有役，那得悞我少年時。","不如逐君征戰死，誰能獨老空閨裏。"]', '["行人結束出门去，马蹏幾时踏门路。","憶昔君初納綵时，不言身屬遼陽戍。","早知今日當別離，成君家計良爲誰。","男兒生身自有役，那得悞我少年时。","不如逐君征戰死，誰能独老空閨裏。"]', '诗', 'shi', '', NULL, '雜曲歌辭 別離曲 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97bebaf8-2310-4683-b9a3-2281f414c53a', '雜曲歌辭 別離曲', '杂曲歌辞 別離曲', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["丈夫非無淚，不灑離別間。","仗劒對尊酒，恥爲游子顏。","蝮蛇一螫手，壯士疾解腕。","所思在功名，離別何足歎。"]', '["丈夫非無泪，不灑離別间。","仗劒对尊酒，恥爲游子顏。","蝮蛇一螫手，壯士疾解腕。","所思在功名，離別何足歎。"]', '诗', 'shi', '', NULL, '雜曲歌辭 別離曲 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3072c03d-8411-490c-b2f4-ead8056a3bfa', '雜曲歌辭 西洲曲', '杂曲歌辞 西洲曲', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["悠悠復悠悠，昨日下西洲。","西洲風色好，遙見武昌樓。","武昌何鬱鬱，儂家定無匹。","小婦被流黃，登樓撫瑤瑟。","朱弦繁復輕，素手直淒清。","一彈三四解，掩抑似含情。","南樓登且望，西江廣復平。","艇子搖兩槳，催過石頭城。","門前烏臼樹，慘澹天將曙。","鵾鵊飛復還，郎隨早帆去。","迴頭語同伴，定復負情儂。","去帆不安幅，作抵使西風。","他日相尋索，莫作西洲客。","西洲人不歸，春草年年碧。"]', '["悠悠复悠悠，昨日下西洲。","西洲风色好，遙见武昌楼。","武昌何鬱鬱，儂家定無匹。","小婦被流黄，登楼撫瑤瑟。","朱弦繁复轻，素手直淒清。","一彈三四解，掩抑似含情。","南楼登且望，西江廣复平。","艇子搖兩槳，催過石头城。","门前烏臼樹，慘澹天將曙。","鵾鵊飞复還，郎隨早帆去。","迴头語同伴，定复負情儂。","去帆不安幅，作抵使西风。","他日相尋索，莫作西洲客。","西洲人不归，春草年年碧。"]', '诗', 'shi', '', NULL, '雜曲歌辭 西洲曲 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02512a3b-3a1c-4a91-809a-7586791afb51', '雜曲歌辭 荆州樂', '杂曲歌辞 荆州乐', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["白帝城邊足風波，瞿塘五月誰敢過。","荆州麥熟繭成蛾，繅絲憶君頭緒多，撥穀飛鳴奈妾何。"]', '["白帝城邊足风波，瞿塘五月誰敢過。","荆州麦熟繭成蛾，繅絲憶君头緒多，撥穀飞鳴奈妾何。"]', '诗', 'shi', '', NULL, '雜曲歌辭 荆州樂 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7466a70-7646-42f2-b7cb-e31e3734e8b1', '雜曲歌辭 荆州樂二首 一', '杂曲歌辞 荆州乐二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["渚宮楊柳暗，麥城朝雉飛。","可憐踏青伴，乘暖著輕衣。"]', '["渚宮楊柳暗，麦城朝雉飞。","可怜踏青伴，乘暖著轻衣。"]', '诗', 'shi', '', NULL, '雜曲歌辭 荆州樂二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48f8c45d-f720-4d52-ad85-5a7339ea14fd', '雜曲歌辭 荆州樂二首 二', '杂曲歌辞 荆州乐二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["今日好南風，商旅相催發。","沙頭檣竿上，始見春江闊。"]', '["今日好南风，商旅相催發。","沙头檣竿上，始见春江闊。"]', '诗', 'shi', '', NULL, '雜曲歌辭 荆州樂二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84817a87-9ee4-4fc1-8207-68ba2ef51bc0', '雜曲歌辭 荆州泊', '杂曲歌辞 荆州泊', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["南樓西下時，月裏聞來棹。","桂水舳艫回，荆州津濟鬧。","移帷望星漢，引帶思容貌。","今夜一江人，惟應妾身覺。"]', '["南楼西下时，月裏闻来棹。","桂水舳艫回，荆州津濟鬧。","移帷望星漢，引带思容貌。","今夜一江人，惟應妾身覺。"]', '诗', 'shi', '', NULL, '雜曲歌辭 荆州泊 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee2f7142-ec63-4efb-ad6b-b26db2c7255c', '雜曲歌辭 紀南歌', '杂曲歌辞 紀南歌', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["風煙紀南城，塵土荆門路。","天寒獵獸者，走上樊姬墓。"]', '["风煙紀南城，塵土荆门路。","天寒獵獸者，走上樊姬墓。"]', '诗', 'shi', '', NULL, '雜曲歌辭 紀南歌 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4b28471-1a3e-47f0-a72b-8893ea3115a5', '雜曲歌辭 宜城歌', '杂曲歌辞 宜城歌', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["野水遶空城，行塵起孤驛。","花臺側生樹，石碣陽鐫頭。","靡靡度行人，溫風吹宿麥。"]', '["野水遶空城，行塵起孤驛。","花台側生樹，石碣陽鐫头。","靡靡度行人，溫风吹宿麦。"]', '诗', 'shi', '', NULL, '雜曲歌辭 宜城歌 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bef9a5e-f4a1-44bd-a78c-cb0fe38ccdff', '雜曲歌辭 長干曲四首 一', '杂曲歌辞 长干曲四首 一', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["君家定何處？妾住在橫塘。","停舟暫借問，或恐是同鄉。"]', '["君家定何处？妾住在橫塘。","停舟暫借问，或恐是同乡。"]', '诗', 'shi', '', NULL, '雜曲歌辭 長干曲四首 一 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d480633-1876-4082-aaca-a7b3a26c04d7', '雜曲歌辭 長干曲四首 二', '杂曲歌辞 长干曲四首 二', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["家臨九江水，去來九江側。","同是長干人，生小不相識。"]', '["家臨九江水，去来九江側。","同是长干人，生小不相識。"]', '诗', 'shi', '', NULL, '雜曲歌辭 長干曲四首 二 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de3624ff-f06e-4552-8e8c-22e75c3e6303', '雜曲歌辭 長干曲四首 三', '杂曲歌辞 长干曲四首 三', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["下渚多風浪，蓮舟漸覺稀。","那能不相待，獨自逆潮歸。"]', '["下渚多风浪，蓮舟漸覺稀。","那能不相待，独自逆潮归。"]', '诗', 'shi', '', NULL, '雜曲歌辭 長干曲四首 三 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e1d3e0d-b5d7-4d30-bce9-9fd69e694a80', '雜曲歌辭 長干曲四首 四', '杂曲歌辞 长干曲四首 四', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["三江潮水急，五湖風浪湧。","由來花性輕，莫畏蓮舟重。"]', '["三江潮水急，五湖风浪湧。","由来花性轻，莫畏蓮舟重。"]', '诗', 'shi', '', NULL, '雜曲歌辭 長干曲四首 四 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1352fbf1-2c3d-459c-b4ac-061e0c6befb8', '雜曲歌辭 長干行二首 一', '杂曲歌辞 长干行二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["妾髮初覆額，折花門前劇。","郎騎竹馬來，遶牀弄青梅。","同居長干里，兩小無嫌猜。","十四爲君婦，羞顏尚不開。","低頭向暗壁，千喚不一迴。","十五始展眉，願同塵與灰。","常存抱柱信，豈上望夫臺。","十六君遠行，瞿塘灩預堆。","五月不可觸，猨鳴天上哀。","門前遲行跡，一一生綠苔。","苔深不能掃，落葉秋風早。","八月蝴蝶來，雙飛西園草。","感此傷妾心，坐愁紅顏老。","早晚下三巴，預將書報家。","相迎不道遠，直至長風沙。"]', '["妾髮初覆額，折花门前劇。","郎騎竹马来，遶牀弄青梅。","同居长干里，兩小無嫌猜。","十四爲君婦，羞顏尚不开。","低头向暗壁，千喚不一迴。","十五始展眉，願同塵與灰。","常存抱柱信，豈上望夫台。","十六君远行，瞿塘灩預堆。","五月不可觸，猨鳴天上哀。","门前遲行跡，一一生綠苔。","苔深不能掃，落葉秋风早。","八月蝴蝶来，雙飞西园草。","感此傷妾心，坐愁紅顏老。","早晚下三巴，預將书報家。","相迎不道远，直至长风沙。"]', '诗', 'shi', '', NULL, '雜曲歌辭 長干行二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('529cf938-bb80-4453-b73f-7425d18396e4', '雜曲歌辭 長干行二首 二', '杂曲歌辞 长干行二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["憶妾深閨裏，煙塵不曾識。","嫁與長干人，沙頭候風色。","五月南風興，思君在巴陵。","八月西風起，想君發揚子。","去來悲如何，見少別離多。","湘潭幾日到，妾夢越風波。","昨夜狂風度，吹折江頭樹。","淼淼暗無邊，行人在何處？","北客真王公，朱衣滿江中。","日暮來投宿，數朝不肎東。","好乘浮雲驄，佳期蘭渚東。","鴛鴦綠浦上，翡翠錦屏中。","自憐十五餘，顏色桃李紅。","那作商人婦，愁水復愁風。"]', '["憶妾深閨裏，煙塵不曾識。","嫁與长干人，沙头候风色。","五月南风兴，思君在巴陵。","八月西风起，想君發揚子。","去来悲如何，见少別離多。","湘潭幾日到，妾梦越风波。","昨夜狂风度，吹折江头樹。","淼淼暗無邊，行人在何处？","北客真王公，朱衣满江中。","日暮来投宿，數朝不肎东。","好乘浮云驄，佳期蘭渚东。","鴛鴦綠浦上，翡翠錦屏中。","自怜十五餘，顏色桃李紅。","那作商人婦，愁水复愁风。"]', '诗', 'shi', '', NULL, '雜曲歌辭 長干行二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('157a14f5-9ce9-41a4-ad4d-05e4b7ba595e', '雜曲歌辭 長干行', '杂曲歌辞 长干行', '9087015e-af3e-4a1b-8b16-7c5d8331d190', '唐', '["壻貧如珠玉，壻富如埃塵。","貧時不忘舊，富貴多寵新。","妾本富家女，與君爲偶匹。","惠好一何深，中門不曾出。","妾有繡衣裳，葳蕤金縷光。","念君貧且賤，易此從遠方。","遠方三千里，發去悔不已。","日暮情更來，空望去時水。","孟夏麥始秀，江上多南風。","商賈歸欲盡，君今尚巴東。","巴東有巫山，窈窕神女顏。","常恐遊此山，果然不知還。"]', '["壻貧如珠玉，壻富如埃塵。","貧时不忘旧，富貴多寵新。","妾本富家女，與君爲偶匹。","惠好一何深，中门不曾出。","妾有繡衣裳，葳蕤金縷光。","念君貧且賤，易此從远方。","远方三千里，發去悔不已。","日暮情更来，空望去时水。","孟夏麦始秀，江上多南风。","商賈归欲尽，君今尚巴东。","巴东有巫山，窈窕神女顏。","常恐游此山，果然不知還。"]', '诗', 'shi', '', NULL, '雜曲歌辭 長干行 張潮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf218c4b-ebb6-4ae0-8aaa-7ad0da70c949', '雜曲歌辭 小長干曲', '杂曲歌辞 小长干曲', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["月暗送湖風，相尋路不通。","菱歌唱不輟，知在此塘中。"]', '["月暗送湖风，相尋路不通。","菱歌唱不輟，知在此塘中。"]', '诗', 'shi', '', NULL, '雜曲歌辭 小長干曲 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eee43be4-f6fe-4f0a-976e-a7a3279c26ee', '雜曲歌辭 杞梁妻', '杂曲歌辞 杞梁妻', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["秦之無道兮四海枯，築長城兮遮北胡。","築人築土一萬里，杞梁貞婦嗁嗚嗚。","上無父兮中無夫，下無子兮孤復孤。","一號城崩塞色苦，再號杞梁骨出土。","疲魂飢魄相逐歸，陌上少年莫相非。"]', '["秦之無道兮四海枯，築长城兮遮北胡。","築人築土一万里，杞梁貞婦嗁嗚嗚。","上無父兮中無夫，下無子兮孤复孤。","一號城崩塞色苦，再號杞梁骨出土。","疲魂飢魄相逐归，陌上少年莫相非。"]', '诗', 'shi', '', NULL, '雜曲歌辭 杞梁妻 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ad6cb9c-3c3a-4140-9197-03bed14ca119', '雜曲歌辭 盧女曲', '杂曲歌辞 盧女曲', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["二月春來半，宮中日漸長。","柳垂金屋暖，花覆玉樓香。","拂匣先臨鏡，調笙更炙簧。","還將盧女曲，夜夜奉君王。"]', '["二月春来半，宮中日漸长。","柳垂金屋暖，花覆玉楼香。","拂匣先臨镜，調笙更炙簧。","還將盧女曲，夜夜奉君王。"]', '诗', 'shi', '', NULL, '雜曲歌辭 盧女曲 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec0707a9-2298-40f6-bd03-100847a86e97', '雜曲歌辭 盧姬篇', '杂曲歌辞 盧姬篇', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["盧姬小小魏王家，綠鬢紅脣桃李花。","魏王綺樓十二重，水精簾箔繡芙蓉。","白玉闌干金作柱，樓上朝朝學歌舞。","前堂後堂羅袖人，南窗北窗花發春。","翠幌珠簾鬬弦管，一奏一彈雲欲斷。","君王日晚下朝歸，鳴環佩玉生光輝。","人生今日得驕貴，誰道盧姬身細微。"]', '["盧姬小小魏王家，綠鬢紅脣桃李花。","魏王綺楼十二重，水精簾箔繡芙蓉。","白玉闌干金作柱，楼上朝朝学歌舞。","前堂後堂羅袖人，南窗北窗花發春。","翠幌珠簾鬬弦管，一奏一彈云欲斷。","君王日晚下朝归，鳴环佩玉生光輝。","人生今日得驕貴，誰道盧姬身細微。"]', '诗', 'shi', '', NULL, '雜曲歌辭 盧姬篇 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1927aaaf-c323-4b29-88cb-95f77886d5bd', '雜曲歌辭 邯鄲才人嫁爲廝養卒婦', '杂曲歌辞 邯鄲才人嫁爲廝養卒婦', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["妾本叢臺女，揚蛾入丹闕。","自倚顏如花，寧知有凋歇。","一辭玉階下，去若朝雲沒。","每憶邯鄲城，深宮夢秋月。","君王不可見，惆悵至明發。"]', '["妾本叢台女，揚蛾入丹闕。","自倚顏如花，寧知有凋歇。","一辞玉階下，去若朝云沒。","每憶邯鄲城，深宮梦秋月。","君王不可见，惆悵至明發。"]', '诗', 'shi', '', NULL, '雜曲歌辭 邯鄲才人嫁爲廝養卒婦 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d26ae92-8701-4cba-ac21-43755964f77c', '雜曲歌辭 楊白花', '杂曲歌辞 楊白花', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["楊白花，風吹度江水。","坐令宮樹無顏色，搖蕩春光千萬里。","茫茫曉日下長秋，哀歌未斷城鵶起。"]', '["楊白花，风吹度江水。","坐令宮樹無顏色，搖蕩春光千万里。","茫茫晓日下长秋，哀歌未斷城鵶起。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊白花 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc988aaa-b1e6-4a0f-b0e5-798d42652c8c', '雜曲歌辭 茱萸女', '杂曲歌辞 茱萸女', 'a8bfe887-75c5-4523-a22b-b414739a35c1', '唐', '["山陰柳家女，九日采茱萸。","復得東鄰伴，雙爲陌上姝。","插花向高髻，結子置長裾。","作性恆遲緩，非關詫丈夫。","平明折林樹，日入反城隅。","俠客邀羅袖，行人挑短書。","蛾眉自有主，年少莫踟躕。"]', '["山陰柳家女，九日采茱萸。","复得东鄰伴，雙爲陌上姝。","插花向高髻，結子置长裾。","作性恆遲緩，非关詫丈夫。","平明折林樹，日入反城隅。","俠客邀羅袖，行人挑短书。","蛾眉自有主，年少莫踟躕。"]', '诗', 'shi', '', NULL, '雜曲歌辭 茱萸女 萬楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21aab035-72a4-49cb-b3a3-0be7e553f2d8', '雜曲歌辭 于闐采花', '杂曲歌辞 于闐采花', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["于闐采花人，自言花相似。","明妃一朝西入胡，胡中美女多羞死。","乃知漢地多名姝，胡中無花可方比。","丹青能令醜者妍，無鹽翻在深宮裏。","自古妬蛾眉，胡沙埋皓齒。"]', '["于闐采花人，自言花相似。","明妃一朝西入胡，胡中美女多羞死。","乃知漢地多名姝，胡中無花可方比。","丹青能令醜者妍，無鹽翻在深宮裏。","自古妬蛾眉，胡沙埋皓齒。"]', '诗', 'shi', '', NULL, '雜曲歌辭 于闐采花 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af16773b-0873-4690-b802-9f3825d1efef', '雜曲歌辭 秦女卷衣', '杂曲歌辞 秦女卷衣', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["天子居未央，妾侍卷衣裳。","顧無紫宮寵，敢拂黃金牀。","水至亦不去，熊來尚可當。","微身奉日月，飄若螢火光。","願君采葑菲，無以下體妨。"]', '["天子居未央，妾侍卷衣裳。","顧無紫宮寵，敢拂黄金牀。","水至亦不去，熊来尚可當。","微身奉日月，飄若螢火光。","願君采葑菲，無以下體妨。"]', '诗', 'shi', '', NULL, '雜曲歌辭 秦女卷衣 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42bc232f-00c5-4e92-8c55-8f38280a9dbe', '雜曲歌辭 愛妾換馬 一', '杂曲歌辞 愛妾換马 一', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["一面妖桃千里蹏，嬌姿駿背價應齊。","乍牽玉勒辭金棧，催整花鈿出繡閨。","去日豈無霑袂泣，歸時還有頓銜嘶。","嬋娟躞蹀春風裏，揮手搖鞭楊柳堤。"]', '["一面妖桃千里蹏，嬌姿駿背價應齊。","乍牽玉勒辞金棧，催整花鈿出繡閨。","去日豈無霑袂泣，归时還有頓銜嘶。","嬋娟躞蹀春风裏，揮手搖鞭楊柳堤。"]', '诗', 'shi', '', NULL, '雜曲歌辭 愛妾換馬 一 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a46125e8-7617-40ac-90f6-35d2f9af010c', '雜曲歌辭 愛妾換馬 二', '杂曲歌辞 愛妾換马 二', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["綺閣香銷華厩空，忍將行雨換追風。","休憐柳葉雙眉翠，卻愛桃花兩耳紅。","侍宴永辭春色裏，趁朝休立漏聲中。","恩勞未盡情先盡，暗泣嘶風兩意同。"]', '["綺閣香銷华厩空，忍將行雨換追风。","休怜柳葉雙眉翠，卻愛桃花兩耳紅。","侍宴永辞春色裏，趁朝休立漏声中。","恩勞未尽情先尽，暗泣嘶风兩意同。"]', '诗', 'shi', '', NULL, '雜曲歌辭 愛妾換馬 二 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc3453b2-0268-4064-90a5-1a3d17192724', '雜曲歌辭 枯魚過河泣', '杂曲歌辞 枯鱼過河泣', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["白龍改常服，偶被豫且制。","誰使爾爲魚，徒勞訴天帝。","作書報鯨鯢，勿恃風濤勢。","濤落歸泥沙，翻遭螻蟻噬。","萬乘慎出入，柏人以爲誡。"]', '["白龙改常服，偶被豫且制。","誰使爾爲鱼，徒勞訴天帝。","作书報鯨鯢，勿恃风濤勢。","濤落归泥沙，翻遭螻蟻噬。","万乘慎出入，柏人以爲誡。"]', '诗', 'shi', '', NULL, '雜曲歌辭 枯魚過河泣 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ead76427-5fa0-475e-bc09-3feb81b89a6a', '雜曲歌辭 飲酒樂', '杂曲歌辞 饮酒乐', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["日月似有事，一夜行一周。","草木猶須老，人生得無愁。","一飲解百結，再飲破百憂。","白髮欺貧賤，不入醉人頭。","我願東海水，盡向杯中流。","安得阮步兵，同入醉鄉遊。"]', '["日月似有事，一夜行一周。","草木猶須老，人生得無愁。","一饮解百結，再饮破百憂。","白髮欺貧賤，不入醉人头。","我願东海水，尽向杯中流。","安得阮步兵，同入醉乡游。"]', '诗', 'shi', '', NULL, '雜曲歌辭 飲酒樂 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b7a301f-f717-4fd1-a39f-f0db207a0887', '雜曲歌辭 王孫遊', '杂曲歌辞 王孫游', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["自與王孫別，頻看黃鳥飛。","應由春草誤，著處不成歸。"]', '["自與王孫別，頻看黄鸟飞。","應由春草誤，著处不成归。"]', '诗', 'shi', '', NULL, '雜曲歌辭 王孫遊 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bb05363-395d-48f6-b28a-55d3e414d6cf', '雜曲歌辭 發白馬', '杂曲歌辞 發白马', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["將軍發白馬，旌節渡黃河。","簫鼓聒川嶽，滄溟湧洪波。","武安有振瓦，易水無寒歌。","鐵騎若雪山，飲流涸滹沱。","揚兵獵月窟，轉戰畧朝那。","倚劍登燕然，邊峰列嵯峨。","蕭條萬里外，耕作五原多。","一掃清大漠，包虎戢金戈。"]', '["將軍發白马，旌節渡黄河。","簫鼓聒川嶽，滄溟湧洪波。","武安有振瓦，易水無寒歌。","鐵騎若雪山，饮流涸滹沱。","揚兵獵月窟，轉戰畧朝那。","倚劍登燕然，邊峰列嵯峨。","蕭條万里外，耕作五原多。","一掃清大漠，包虎戢金戈。"]', '诗', 'shi', '', NULL, '雜曲歌辭 發白馬 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b422712d-ef98-46d3-b967-0a2c5c000fc7', '雜曲歌辭 結韈子', '杂曲歌辞 結韈子', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["燕南壯士吳門豪，筑中置鉛魚隱刀。","感君恩重許君命，泰山一擲輕鴻毛。"]', '["燕南壯士吳门豪，筑中置鉛鱼隐刀。","感君恩重許君命，泰山一擲轻鴻毛。"]', '诗', 'shi', '', NULL, '雜曲歌辭 結韈子 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bbd4504-0c3d-4ab5-a537-3da6eab3eb29', '雜曲歌辭 沐浴子', '杂曲歌辞 沐浴子', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["沐芳莫彈冠，浴蘭莫振衣。","處世忌太潔，志人貴藏輝。","滄浪有釣叟，吾與爾同歸。"]', '["沐芳莫彈冠，浴蘭莫振衣。","处世忌太潔，志人貴藏輝。","滄浪有釣叟，吾與爾同归。"]', '诗', 'shi', '', NULL, '雜曲歌辭 沐浴子 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d201d25e-b274-479a-96b0-2465250dc564', '雜曲歌辭 三臺二首 一', '杂曲歌辞 三台二首 一', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["一年一年老去，明日後日花開。","未報長安平定，萬國豈得銜杯。"]', '["一年一年老去，明日後日花开。","未報长安平定，万国豈得銜杯。"]', '诗', 'shi', '', NULL, '雜曲歌辭 三臺二首 一 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('283d3d6b-8182-488d-8d04-9b3bc3a4da26', '雜曲歌辭 三臺二首 二', '杂曲歌辞 三台二首 二', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["冰泮寒塘始綠，雨餘百草皆生。","朝來門閤無事，晚下高齋有情。"]', '["冰泮寒塘始綠，雨餘百草皆生。","朝来门閤無事，晚下高斋有情。"]', '诗', 'shi', '', NULL, '雜曲歌辭 三臺二首 二 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed42eaf6-78fd-493d-acf6-612c30c704fc', '雜曲歌辭 上皇三臺', '杂曲歌辞 上皇三台', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["不寐倦長更，披衣出戶行。","月寒秋竹冷，風切夜窗聲。"]', '["不寐倦长更，披衣出戶行。","月寒秋竹冷，风切夜窗声。"]', '诗', 'shi', '', NULL, '雜曲歌辭 上皇三臺 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7474cb5a-0ad3-485b-b8f9-90af07d6f51a', '雜曲歌辭 突厥三臺', '杂曲歌辞 突厥三台', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["鴈門山上鴈初飛，馬邑闌中馬正肥。","日旰山西逢驛使，殷勤南北送征衣。"]', '["鴈门山上鴈初飞，马邑闌中马正肥。","日旰山西逢驛使，殷勤南北送征衣。"]', '诗', 'shi', '', NULL, '雜曲歌辭 突厥三臺 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40501915-700c-4cbe-8232-c5905a115f97', '雜曲歌辭 宮中三臺二首 一', '杂曲歌辞 宮中三台二首 一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["魚藻池邊射鴨，芙蓉園裏看花。","日色柘袍相似，不著紅鸞扇遮。"]', '["鱼藻池邊射鴨，芙蓉园裏看花。","日色柘袍相似，不著紅鸾扇遮。"]', '诗', 'shi', '', NULL, '雜曲歌辭 宮中三臺二首 一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49fb819b-564d-47ec-b0c1-fabe5924176a', '雜曲歌辭 宮中三臺二首 二', '杂曲歌辞 宮中三台二首 二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["池北池南草綠，殿前殿後花紅。","天子千年萬歲，未央明月清風。"]', '["池北池南草綠，殿前殿後花紅。","天子千年万歲，未央明月清风。"]', '诗', 'shi', '', NULL, '雜曲歌辭 宮中三臺二首 二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14a9ef0e-ad64-4dba-83ad-91719b1499da', '雜曲歌辭 江南三臺四首 一', '杂曲歌辞 江南三台四首 一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["揚州橋邊小婦，長干市裏商人。","三年不得消息，各自拜鬼求神。"]', '["揚州橋邊小婦，长干市裏商人。","三年不得消息，各自拜鬼求神。"]', '诗', 'shi', '', NULL, '雜曲歌辭 江南三臺四首 一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7bbc9ec-1800-4da3-9ed2-b06b5ea19684', '雜曲歌辭 江南三臺四首 二', '杂曲歌辞 江南三台四首 二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["青草湖邊草色，飛猨嶺上猨聲。","萬里三湘客到，有風有雨人行。"]', '["青草湖邊草色，飞猨嶺上猨声。","万里三湘客到，有风有雨人行。"]', '诗', 'shi', '', NULL, '雜曲歌辭 江南三臺四首 二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38aaa671-b84f-4419-a483-f2f4613d0bf5', '雜曲歌辭 江南三臺四首 三', '杂曲歌辞 江南三台四首 三', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["樹頭花落花開，道上人去人來。","朝愁暮愁即老，百年幾度三臺。"]', '["樹头花落花开，道上人去人来。","朝愁暮愁即老，百年幾度三台。"]', '诗', 'shi', '', NULL, '雜曲歌辭 江南三臺四首 三 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f26fae5d-2f45-409d-8401-bc28cddda693', '雜曲歌辭 江南三臺四首 四', '杂曲歌辞 江南三台四首 四', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["聞身彊健且爲，頭白齒落難追。","准擬百年千歲，能得幾許多時。"]', '["闻身彊健且爲，头白齒落难追。","准擬百年千歲，能得幾許多时。"]', '诗', 'shi', '', NULL, '雜曲歌辭 江南三臺四首 四 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('434c8a6e-2cd4-4195-bf8c-08d9a32b3095', '雜曲歌辭 築城曲', '杂曲歌辞 築城曲', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["築城去，千人萬人齊抱杵。","重重土堅試行錐，軍吏執鞭催作遲。","來時一年深磧裏，著盡短衣渴無水。","力盡不得拋杵聲，杵聲未定人皆死。","家家養男當門戶，今日作君城下土。"]', '["築城去，千人万人齊抱杵。","重重土堅試行錐，軍吏執鞭催作遲。","来时一年深磧裏，著尽短衣渴無水。","力尽不得拋杵声，杵声未定人皆死。","家家養男當门戶，今日作君城下土。"]', '诗', 'shi', '', NULL, '雜曲歌辭 築城曲 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81023b90-e4af-4540-bcc2-5d99bd77ab28', '雜曲歌辭 築城曲五解', '杂曲歌辞 築城曲五解', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["年年塞下丁，長作出塞兵。","自從冒頓彊，官築遮虜城。","築城須努力，城高遮得賊。","但恐賊路多，有城遮不得。","丁口傳父口，莫問城堅不。","平城被虜圍，漢斸城牆走。","因茲虜請和，虜往騎來多。","半疑兼半信，築城猶嵯峨。","築城安敢煩，願聽丁一言。","請築鴻臚寺，兼愁虜出關。"]', '["年年塞下丁，长作出塞兵。","自從冒頓彊，官築遮虜城。","築城須努力，城高遮得賊。","但恐賊路多，有城遮不得。","丁口傳父口，莫问城堅不。","平城被虜圍，漢斸城牆走。","因茲虜請和，虜往騎来多。","半疑兼半信，築城猶嵯峨。","築城安敢煩，願听丁一言。","請築鴻臚寺，兼愁虜出关。"]', '诗', 'shi', '', NULL, '雜曲歌辭 築城曲五解 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('499f57c6-97bf-4fd3-8010-d76a4f3ebc0b', '雜曲歌辭 築城曲', '杂曲歌辞 築城曲', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["城上一掊土，手中千萬杵。","築城畏不堅，堅城在何處？","莫歎築城勞，將軍要却敵。","城高功亦高，爾命何處惜。"]', '["城上一掊土，手中千万杵。","築城畏不堅，堅城在何处？","莫歎築城勞，將軍要却敵。","城高功亦高，爾命何处惜。"]', '诗', 'shi', '', NULL, '雜曲歌辭 築城曲 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26b7a177-210b-4d15-8e26-e17db2d1ca13', '雜曲歌辭 湖陰曲', '杂曲歌辞 湖陰曲', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["祖龍黃須珊瑚鞭，鐵驄金面青連錢。","虎髯拔劒欲成夢，日壓賊營如血鮮。","海旗風急驚眠起，甲重光搖照湖水。","蒼黃追騎塵外歸，森索妖星陣前死。","五陵愁碧春萋萋，灞川玉馬空中嘶。","羽書如電入青瑣，雪腕如搥催畫鞞。","白虬天子金煌鋩，高臨帝座迴龍章。","吳波不動楚山晚，花壓闌干春晝長。"]', '["祖龙黄須珊瑚鞭，鐵驄金面青連錢。","虎髯拔劒欲成梦，日壓賊營如血鲜。","海旗风急驚眠起，甲重光搖照湖水。","蒼黄追騎塵外归，森索妖星陣前死。","五陵愁碧春萋萋，灞川玉马空中嘶。","羽书如電入青瑣，雪腕如搥催畫鞞。","白虬天子金煌鋩，高臨帝座迴龙章。","吳波不动楚山晚，花壓闌干春晝长。"]', '诗', 'shi', '', NULL, '雜曲歌辭 湖陰曲 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5aca9b73-4673-4dbf-a5dc-65add8136e76', '雜曲歌辭 無愁果有愁曲', '杂曲歌辞 無愁果有愁曲', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["東有青龍西白虎，中含福皇包世度。","玉壺渭水笑清潭，鑿天不到牽牛處。","騏驎踏雲天馬獰，牛山撼碎珊瑚聲。","秋娥點滴不成淚，十二玉樓無故釘。","推煙唾月拋千里，十番紅桐一行死。","白楊別屋鬼迷人，空留暗記如蠶紙。","日暮向風牽短絲，血凝血散今誰是。"]', '["东有青龙西白虎，中含福皇包世度。","玉壺渭水笑清潭，鑿天不到牽牛处。","騏驎踏云天马獰，牛山撼碎珊瑚声。","秋娥点滴不成泪，十二玉楼無故釘。","推煙唾月拋千里，十番紅桐一行死。","白楊別屋鬼迷人，空留暗記如蠶紙。","日暮向风牽短絲，血凝血散今誰是。"]', '诗', 'shi', '', NULL, '雜曲歌辭 無愁果有愁曲 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27ce9f4a-b246-472d-b3c5-6f20fcdf2cc4', '雜曲歌辭 起夜來', '杂曲歌辞 起夜来', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["香銷連理帶，塵覆合歡杯。","嬾臥相思枕，愁吟起夜來。"]', '["香銷連理带，塵覆合歡杯。","嬾臥相思枕，愁吟起夜来。"]', '诗', 'shi', '', NULL, '雜曲歌辭 起夜來 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec880efb-495d-48aa-9764-a827c4bd8864', '雜曲歌辭 起夜半', '杂曲歌辞 起夜半', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["念遠心如燒，不覺中夜起。","桃花帶露泛，立在月明裏。"]', '["念远心如燒，不覺中夜起。","桃花带露泛，立在月明裏。"]', '诗', 'shi', '', NULL, '雜曲歌辭 起夜半 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15079155-e95e-4abc-b36e-f6b605848f37', '雜曲歌辭 獨不見', '杂曲歌辞 独不见', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["盧家小婦鬱金堂，海燕雙栖玳瑁梁。","九月寒砧催下葉，十年征戍憶遼陽。","白狼河北音書斷，丹鳳城南秋夜長。","誰知含愁獨不見，使妾明月照流黃。"]', '["盧家小婦鬱金堂，海燕雙栖玳瑁梁。","九月寒砧催下葉，十年征戍憶遼陽。","白狼河北音书斷，丹鳳城南秋夜长。","誰知含愁独不见，使妾明月照流黄。"]', '诗', 'shi', '', NULL, '雜曲歌辭 獨不見 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7684cf1b-97f8-4697-bb08-6990dc5f72e0', '雜曲歌辭 獨不見', '杂曲歌辞 独不见', '3d6014ae-1bb8-4d0a-bff9-fcba228dfe22', '唐', '["日晚宜春暮，風輭上林朝。","對酒近初節，開樓蕩夜嬌。","石橋通小澗，竹路上青霄。","持底誰見許，長愁成細腰。"]', '["日晚宜春暮，风輭上林朝。","对酒近初節，开楼蕩夜嬌。","石橋通小澗，竹路上青霄。","持底誰见許，长愁成細腰。"]', '诗', 'shi', '', NULL, '雜曲歌辭 獨不見 王訓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ffd2c22-09b3-46cf-a0b6-62d503e26cf2', '雜曲歌辭 獨不見', '杂曲歌辞 独不见', '08b14256-c564-4489-be33-927205119c81', '唐', '["東風豔陽色，柳綠花如霰。","競理同心鬟，爭持合歡扇。","香傳賈娘手，粉離何郎面。","最恨卷簾時，含情獨不見。"]', '["东风豔陽色，柳綠花如霰。","競理同心鬟，爭持合歡扇。","香傳賈娘手，粉離何郎面。","最恨卷簾时，含情独不见。"]', '诗', 'shi', '', NULL, '雜曲歌辭 獨不見 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f406635d-5044-4232-bd70-e34b542803b6', '雜曲歌辭 獨不見', '杂曲歌辞 独不见', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["白馬誰家子，黃龍邊塞兒。","天山三丈雪，豈是遠行時。","春蕙忽秋草，莎雞鳴曲池。","風催寒椶響，月入霜閨悲。","憶與君別年，種桃齊蛾眉。","桃今百餘尺，花落成枯枝。","終然獨不見，流淚空自知。"]', '["白马誰家子，黄龙邊塞兒。","天山三丈雪，豈是远行时。","春蕙忽秋草，莎雞鳴曲池。","风催寒椶响，月入霜閨悲。","憶與君別年，種桃齊蛾眉。","桃今百餘尺，花落成枯枝。","終然独不见，流泪空自知。"]', '诗', 'shi', '', NULL, '雜曲歌辭 獨不見 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc1c3862-676c-4eb6-822d-4c5fe33df317', '雜曲歌辭 獨不見', '杂曲歌辞 独不见', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["前宮路非遠，舊苑春將遍。","玉戶看早梅，雕梁數歸燕。","身輕逐舞袖，香暖傳歌扇。","自知秋風詞，長侍昭陽殿。","誰信後庭人，年年獨不見。"]', '["前宮路非远，旧苑春將遍。","玉戶看早梅，雕梁數归燕。","身轻逐舞袖，香暖傳歌扇。","自知秋风词，长侍昭陽殿。","誰信後庭人，年年独不见。"]', '诗', 'shi', '', NULL, '雜曲歌辭 獨不見 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d3e36fd-515d-43e3-9336-c3e827a93bdc', '雜曲歌辭 獨不見', '杂曲歌辞 独不见', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["玉關一自有氛埃，年少從軍竟未回。","門外塵凝張樂榭，水邊香滅按歌臺。","窗殘夜月人何處？簾卷春風燕復來。","萬里寂寥音信絕，寸心爭忍不成灰。"]', '["玉关一自有氛埃，年少從軍竟未回。","门外塵凝張乐榭，水邊香滅按歌台。","窗殘夜月人何处？簾卷春风燕复来。","万里寂寥音信絕，寸心爭忍不成灰。"]', '诗', 'shi', '', NULL, '雜曲歌辭 獨不見 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23e08615-433c-48b1-a1e8-9d3ceb31e899', '雜曲歌辭 攜手曲', '杂曲歌辞 携手曲', 'c3eab4f9-1607-4725-922e-a095f7c3b5ee', '唐', '["攜手共惜芳菲節，鶯啼錦花滿城闕。","行樂逶迤念容色，色衰祗恐君恩歇。","鳳笙龍管白日陰，盈虧自感青天月。"]', '["携手共惜芳菲節，鶯啼錦花满城闕。","行乐逶迤念容色，色衰祗恐君恩歇。","鳳笙龙管白日陰，盈虧自感青天月。"]', '诗', 'shi', '', NULL, '雜曲歌辭 攜手曲 田娥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b89f5c6f-e3b2-4503-9d26-8b67db0ae707', '雜曲歌辭 大垂手', '杂曲歌辞 大垂手', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["金刀翦輕雲，盤用黃金縷。","裝束趙飛燕，教來掌上舞。","舞罷飛燕死，片片隨風去。"]', '["金刀翦轻云，盤用黄金縷。","裝束趙飞燕，教来掌上舞。","舞罷飞燕死，片片隨风去。"]', '诗', 'shi', '', NULL, '雜曲歌辭 大垂手 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e14cbebf-e7fd-4eb3-af52-d8d5587ae78b', '雜曲歌辭 夜夜曲', '杂曲歌辞 夜夜曲', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["愁人夜獨傷，滅燭臥蘭房。","祗恐多情月，旋來照妾牀。"]', '["愁人夜独傷，滅燭臥蘭房。","祗恐多情月，旋来照妾牀。"]', '诗', 'shi', '', NULL, '雜曲歌辭 夜夜曲 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68a3e39c-58e3-4b5b-890a-22f1e3f1c185', '雜曲歌辭 夜夜曲', '杂曲歌辞 夜夜曲', 'ed7684c5-7336-496c-b177-980a1337b513', '唐', '["北斗星移銀漢低，班姬愁思鳳城西。","青槐陌上人行絕，明月樓前烏夜啼。"]', '["北斗星移銀漢低，班姬愁思鳳城西。","青槐陌上人行絕，明月楼前烏夜啼。"]', '诗', 'shi', '', NULL, '雜曲歌辭 夜夜曲 王偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2abccdd1-975e-460b-a0a4-a9e523cab8e4', '雜曲歌辭 夜夜曲', '杂曲歌辞 夜夜曲', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["蟪蛄切切風騷騷，芙蓉噴香蟾蜍高。","孤燈耿耿征婦勞，更深撲落金錯刀。"]', '["蟪蛄切切风騷騷，芙蓉噴香蟾蜍高。","孤灯耿耿征婦勞，更深撲落金錯刀。"]', '诗', 'shi', '', NULL, '雜曲歌辭 夜夜曲 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08df45bf-0fcf-4ada-aaf9-844b6e18490e', '雜曲歌辭 秋夜長', '杂曲歌辞 秋夜长', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["秋夜長，殊未央。","月明白露澄清光，層城綺閣遙相望。","遙相望，川無梁。","北風受節鴈南翔，崇蘭委質時菊芳。","鳴環曳履出長廊，爲君秋夜擣衣裳。","纖羅對鳳皇，丹綺雙鴛鴦。","調砧亂杵思自傷，思自傷，征夫萬里戍他鄉。","鶴關音信斷，龍門道路長。","所在天一方，寒衣徒自香。"]', '["秋夜长，殊未央。","月明白露澄清光，層城綺閣遙相望。","遙相望，川無梁。","北风受節鴈南翔，崇蘭委質时菊芳。","鳴环曳履出长廊，爲君秋夜擣衣裳。","纖羅对鳳皇，丹綺雙鴛鴦。","調砧亂杵思自傷，思自傷，征夫万里戍他乡。","鹤关音信斷，龙门道路长。","所在天一方，寒衣徒自香。"]', '诗', 'shi', '', NULL, '雜曲歌辭 秋夜長 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ff8ecff-2578-40c6-87b9-7ca546c25fac', '雜曲歌辭 秋夜長', '杂曲歌辞 秋夜长', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["秋天如水夜未央，天漢東西月色光。","愁人不寐畏枕席，暗蟲唧唧遶我傍。","荒城爲村無更聲，起看北斗天未明。","白露滿田風褭褭，千聲萬聲鶡鳥鳴。"]', '["秋天如水夜未央，天漢东西月色光。","愁人不寐畏枕席，暗蟲唧唧遶我傍。","荒城爲村無更声，起看北斗天未明。","白露满田风褭褭，千声万声鶡鸟鳴。"]', '诗', 'shi', '', NULL, '雜曲歌辭 秋夜長 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fa92cdf-24cf-4a6a-af33-db5809652091', '雜曲歌辭 秋夜曲二首 一', '杂曲歌辞 秋夜曲二首 一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["天清漏長霜泊泊，蘭綠收榮桂膏涸。","高樓雲鬟弄嬋娟，古瑟暗斷秋風弦。","玉關遙隔萬里道，金刀不翦雙淚泉。","香囊火死香氣少，向帷合眼何時曉？","城烏作營嗁野月，秦川少婦生離別。"]', '["天清漏长霜泊泊，蘭綠收榮桂膏涸。","高楼云鬟弄嬋娟，古瑟暗斷秋风弦。","玉关遙隔万里道，金刀不翦雙泪泉。","香囊火死香氣少，向帷合眼何时晓？","城烏作營嗁野月，秦川少婦生離別。"]', '诗', 'shi', '', NULL, '雜曲歌辭 秋夜曲二首 一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53cf061b-f9b7-4a39-bccc-241449bef36f', '雜曲歌辭 秋夜曲二首 二', '杂曲歌辞 秋夜曲二首 二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["秋燈向壁掩洞房，良人此夜直明光。","天河悠悠漏水長，南樓北斗兩相當。"]', '["秋灯向壁掩洞房，良人此夜直明光。","天河悠悠漏水长，南楼北斗兩相當。"]', '诗', 'shi', '', NULL, '雜曲歌辭 秋夜曲二首 二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acd009f5-60ec-4569-878f-28fb51b0ef0f', '雜曲歌辭 秋夜曲', '杂曲歌辞 秋夜曲', 'f841c0a4-cfe1-4d0b-a30c-6261191f82e2', '唐', '["丁丁漏水夜何長，漫漫輕雲露月光。","秋壁闇蟲通夕響，寒衣未寄莫飛霜。"]', '["丁丁漏水夜何长，漫漫轻云露月光。","秋壁闇蟲通夕响，寒衣未寄莫飞霜。"]', '诗', 'shi', '', NULL, '雜曲歌辭 秋夜曲 張仲素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f66d2ec-8418-485e-a434-e21a0d439dda', '雜曲歌辭 秋夜曲', '杂曲歌辞 秋夜曲', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["桂魄初生秋露微，輕羅已薄未更衣。","銀箏夜久殷勤弄，心怯空房不忍歸。"]', '["桂魄初生秋露微，轻羅已薄未更衣。","銀箏夜久殷勤弄，心怯空房不忍归。"]', '诗', 'shi', '', NULL, '雜曲歌辭 秋夜曲 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b8a54fd-f08a-4f0d-a6ab-96774ef6b15b', '雜曲歌辭 夜坐吟', '杂曲歌辞 夜坐吟', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["冬夜夜寒覺夜長，沈吟久坐坐北堂。","冰合井泉月入閨，青缸凝明照悲嗁。","青缸滅，嗁轉多，掩妾淚，聽君歌。","歌有聲，妾有情，情聲合，兩無違。","一語不入意，從君萬曲梁塵飛。"]', '["冬夜夜寒覺夜长，沈吟久坐坐北堂。","冰合井泉月入閨，青缸凝明照悲嗁。","青缸滅，嗁轉多，掩妾泪，听君歌。","歌有声，妾有情，情声合，兩無違。","一語不入意，從君万曲梁塵飞。"]', '诗', 'shi', '', NULL, '雜曲歌辭 夜坐吟 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c89fcc8b-70df-4b67-84c8-6c855555eb41', '雜曲歌辭 夜坐吟', '杂曲歌辞 夜坐吟', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["踏踏馬頭誰見過，眼看北斗直天河。","西風羅幕生翠波，鉛華笑妾顰青蛾。","爲君起唱長相思，簾外嚴霜皆倒飛。","明星爛爛東方陲，紅霞稍出東南涯，陸郎去矣乘斑騅。"]', '["踏踏马头誰见過，眼看北斗直天河。","西风羅幕生翠波，鉛华笑妾顰青蛾。","爲君起唱长相思，簾外嚴霜皆倒飞。","明星爛爛东方陲，紅霞稍出东南涯，陸郎去矣乘斑騅。"]', '诗', 'shi', '', NULL, '雜曲歌辭 夜坐吟 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6feba2ad-2a6e-40d1-ace1-6ecc16819a82', '雜曲歌辭 夜寒吟', '杂曲歌辞 夜寒吟', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["九衢金吾夜行行，上宮玉漏遙分明。","霜飆乘陰掃地起，旅鴻迷雪繞枕聲。","遠人歸夢既不成，留家惜夜歡心發。","羅幕畫堂深皎潔，蘭煙對酒客幾人。","獸火揚光二三月，細腰楚姬絲竹間。","白紵長袖歌閑閑，豈識苦寒損朱顏。"]', '["九衢金吾夜行行，上宮玉漏遙分明。","霜飆乘陰掃地起，旅鴻迷雪繞枕声。","远人归梦既不成，留家惜夜歡心發。","羅幕畫堂深皎潔，蘭煙对酒客幾人。","獸火揚光二三月，細腰楚姬絲竹间。","白紵长袖歌闲闲，豈識苦寒損朱顏。"]', '诗', 'shi', '', NULL, '雜曲歌辭 夜寒吟 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dce26031-6d6a-4cb4-abe6-95f50c149af0', '雜曲歌辭 定情篇', '杂曲歌辞 定情篇', '5fbbb254-1f00-4d96-a79a-1a7d570b22ca', '唐', '["共君結新婚，歲寒心未卜。","相與遊春園，各隨情所逐。","君念菖蒲花，妾感苦寒竹。","菖花多豔姿，寒竹有貞葉。","此時妾比君，君心不如妾。","簪玉步河堤，妖韶援綠{𥫗/戢}。","鳧鴈將子遊，鶯燕從雙栖。","君念春光好，妾向春光嗁。","君時不得意，妾棄還金閨。","結言本同心，悲懽何未齊。","怨咽前致辭，願得中所悲。","人間丈夫易，世路婦難爲。","始經天月照，終若流星馳。","長信佳麗人，失意非蛾眉。","廬江小吏婦，非關織作遲。","本願長相對，今已長相思。","復有遊宦子，結援從梁陳。","燕居崇三朝，去來歷九春。","誓心妾終始，蠶桑奉所親。","歸願未克從，黃金贈路人。","潔婦懷明義，從汎河之津。","於今千萬年，誰當問水濱。","更憶倡家樓，夫壻事封侯。","去時思灼灼，去罷心悠悠。","不憐妾歲晏，千載隴西頭。","以茲常惕惕，百慮恆盈積。","由來共結褵，幾人同匪石。","故歲雕梁燕，雙去今來隻。","今日玉庭梅，朝紅暮成碧。","碧榮始芬敷，黃葉已[淅]瀝。","何用念芳春，芳春有流易。","何用重懽娛，懽娛俄戚戚。","家本巫山陽，歸去路何長。","敍言情未盡，采菉已盈筐。","桑榆日映物，草色盈高岡。","下有碧流水，上有丹桂香。","桂枝不須折，碧流清且潔。","贈君比芳菲，受惠常不滅。","贈君淚潺湲，相思無斷絕。","妾有秦家鏡，寶匣裝珠璣。","鑑來年二八，不記易陰暉。","妾無光寂寂，委照影依依。","今日持爲贈，相識莫相違。"]', '["共君結新婚，歲寒心未卜。","相與游春园，各隨情所逐。","君念菖蒲花，妾感苦寒竹。","菖花多豔姿，寒竹有貞葉。","此时妾比君，君心不如妾。","簪玉步河堤，妖韶援綠{𥫗/戢}。","鳧鴈將子游，鶯燕從雙栖。","君念春光好，妾向春光嗁。","君时不得意，妾棄還金閨。","結言本同心，悲懽何未齊。","怨咽前致辞，願得中所悲。","人间丈夫易，世路婦难爲。","始經天月照，終若流星驰。","长信佳丽人，失意非蛾眉。","廬江小吏婦，非关织作遲。","本願长相对，今已长相思。","复有游宦子，結援從梁陳。","燕居崇三朝，去来歷九春。","誓心妾終始，蠶桑奉所親。","归願未克從，黄金贈路人。","潔婦懷明義，從汎河之津。","於今千万年，誰當问水濱。","更憶倡家楼，夫壻事封侯。","去时思灼灼，去罷心悠悠。","不怜妾歲晏，千載隴西头。","以茲常惕惕，百慮恆盈積。","由来共結褵，幾人同匪石。","故歲雕梁燕，雙去今来隻。","今日玉庭梅，朝紅暮成碧。","碧榮始芬敷，黄葉已[淅]瀝。","何用念芳春，芳春有流易。","何用重懽娛，懽娛俄戚戚。","家本巫山陽，归去路何长。","敍言情未尽，采菉已盈筐。","桑榆日映物，草色盈高岡。","下有碧流水，上有丹桂香。","桂枝不須折，碧流清且潔。","贈君比芳菲，受惠常不滅。","贈君泪潺湲，相思無斷絕。","妾有秦家镜，寶匣裝珠璣。","鑑来年二八，不記易陰暉。","妾無光寂寂，委照影依依。","今日持爲贈，相識莫相違。"]', '诗', 'shi', '', NULL, '雜曲歌辭 定情篇 喬知之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1c23df5-e9ea-4ab7-bf23-ed6fd7036b62', '雜曲歌辭 定情樂', '杂曲歌辞 定情乐', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["敢嗟君不憐，自是命不諧。","著破三條裾，卻還雙股釵。"]', '["敢嗟君不怜，自是命不諧。","著破三條裾，卻還雙股釵。"]', '诗', 'shi', '', NULL, '雜曲歌辭 定情樂 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3b95e77-5985-49ef-b603-cce95a5c6ae2', '雜曲歌辭 春江曲', '杂曲歌辞 春江曲', '21ff9f86-72e1-4ef1-9e34-944b1639b174', '唐', '["江水春沈沈，上有雙竹林。","竹葉壞水色，郎亦壞人心。"]', '["江水春沈沈，上有雙竹林。","竹葉壞水色，郎亦壞人心。"]', '诗', 'shi', '', NULL, '雜曲歌辭 春江曲 郭元振 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('306c2503-eff5-418b-873e-c72596a676bd', '雜曲歌辭 春江曲', '杂曲歌辞 春江曲', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["春江無雲潮水平，蒲心出水鳧雛鳴。","長干夫壻愛遠行，自染春衣縫已成。","妾身生長金陵側，去年隨夫住江北。","春來未到父母家，舟小風多渡不得。","欲辭舅姑先問人，私向江頭祭水神。"]', '["春江無云潮水平，蒲心出水鳧雛鳴。","长干夫壻愛远行，自染春衣縫已成。","妾身生长金陵側，去年隨夫住江北。","春来未到父母家，舟小风多渡不得。","欲辞舅姑先问人，私向江头祭水神。"]', '诗', 'shi', '', NULL, '雜曲歌辭 春江曲 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22df0b35-cf47-4dd2-844b-1984891d5db0', '雜曲歌辭 春江曲', '杂曲歌辞 春江曲', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["搖漾越江春，相將看白蘋。","歸時不覺夜，出浦月隨人。"]', '["搖漾越江春，相將看白蘋。","归时不覺夜，出浦月隨人。"]', '诗', 'shi', '', NULL, '雜曲歌辭 春江曲 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c3450f9-3313-4b37-a250-3a2a65ffc6ea', '雜曲歌辭 春江曲二首 一', '杂曲歌辞 春江曲二首 一', 'f841c0a4-cfe1-4d0b-a30c-6261191f82e2', '唐', '["家寄征江岸，征人幾歲遊。","不知潮水信，每日到沙頭。"]', '["家寄征江岸，征人幾歲游。","不知潮水信，每日到沙头。"]', '诗', 'shi', '', NULL, '雜曲歌辭 春江曲二首 一 張仲素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c801e3f-7e0e-427e-bdc6-20a221935c19', '雜曲歌辭 春江曲二首 二', '杂曲歌辞 春江曲二首 二', 'f841c0a4-cfe1-4d0b-a30c-6261191f82e2', '唐', '["乘曉南湖去，參差疊浪橫。","前洲在何處？霧裏鴈嚶嚶。"]', '["乘晓南湖去，參差叠浪橫。","前洲在何处？霧裏鴈嚶嚶。"]', '诗', 'shi', '', NULL, '雜曲歌辭 春江曲二首 二 張仲素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('132c7276-e108-4501-b619-ae997cf31e4b', '雜曲歌辭 江上曲', '杂曲歌辞 江上曲', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["江上澹澹芙蓉花，江口蛾眉獨浣紗。","可憐應是陽臺女，坐對鸕鷀嬌不語。","掩面羞看北地人，回首忽作空山雨。","蒼梧秋色不堪論，千載依依帝子魂。","君看峯上斑斑竹，盡是湘妃泣淚痕。"]', '["江上澹澹芙蓉花，江口蛾眉独浣紗。","可怜應是陽台女，坐对鸕鷀嬌不語。","掩面羞看北地人，回首忽作空山雨。","蒼梧秋色不堪論，千載依依帝子魂。","君看峯上斑斑竹，尽是湘妃泣泪痕。"]', '诗', 'shi', '', NULL, '雜曲歌辭 江上曲 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09fea87e-c0a8-44bc-a18f-307b9f7ee92b', '雜曲歌辭 桃花曲', '杂曲歌辞 桃花曲', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["魏帝宮人舞鳳樓，隋家天子泛龍舟。","君王夜醉春眠[晏]，不覺桃花逐水流。"]', '["魏帝宮人舞鳳楼，隋家天子泛龙舟。","君王夜醉春眠[晏]，不覺桃花逐水流。"]', '诗', 'shi', '', NULL, '雜曲歌辭 桃花曲 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed9367a7-fa9f-42b7-a45a-b9bd34a1c531', '雜曲歌辭 樹中草', '杂曲歌辞 樹中草', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["鳥銜野田草，誤入枯桑裏。","客土植危根，逢春猶不死。","草木雖無情，因依尚可生。","如何同枝葉，各自有枯榮。"]', '["鸟銜野田草，誤入枯桑裏。","客土植危根，逢春猶不死。","草木雖無情，因依尚可生。","如何同枝葉，各自有枯榮。"]', '诗', 'shi', '', NULL, '雜曲歌辭 樹中草 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f0805f2-27d7-4ca4-b338-22722d62e69e', '雜曲歌辭 樹中草', '杂曲歌辞 樹中草', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["青青樹中草，託根非不危。","草生樹卻死，榮枯君可知。"]', '["青青樹中草，託根非不危。","草生樹卻死，榮枯君可知。"]', '诗', 'shi', '', NULL, '雜曲歌辭 樹中草 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c98aa957-7dec-4900-81c9-2cf976568176', '雜曲歌辭 春遊吟', '杂曲歌辞 春游吟', '9dfc9c4c-4b74-46c0-a765-a0d0389c992a', '唐', '["初春遍芳甸，千里靄盈矚。","美人摘新英，步步玩春綠。","所思杳何處，宛在吳江曲。","可憐不得共芳菲，日暮歸來淚滿衣。"]', '["初春遍芳甸，千里靄盈矚。","美人摘新英，步步玩春綠。","所思杳何处，宛在吳江曲。","可怜不得共芳菲，日暮归来泪满衣。"]', '诗', 'shi', '', NULL, '雜曲歌辭 春遊吟 李章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('352f00c4-1ac3-4ab0-a0a0-7a2bb4ca86fe', '雜曲歌辭 春遊樂', '杂曲歌辞 春游乐', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["一年三百六十日，賞心那似春中物。","草迷曲塢花滿園，東家少年西家出。"]', '["一年三百六十日，賞心那似春中物。","草迷曲塢花满园，东家少年西家出。"]', '诗', 'shi', '', NULL, '雜曲歌辭 春遊樂 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65dfff04-3602-4d69-b326-82b5a3da2c6a', '雜曲歌辭 春遊樂二首 一', '杂曲歌辞 春游乐二首 一', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["遊童蘇合帶，倡女蒲葵扇。","初日映城時，相思忽相見。","褰裳踏露草，理鬢回花面。","薄暮不同歸，留情此芳甸。"]', '["游童蘇合带，倡女蒲葵扇。","初日映城时，相思忽相见。","褰裳踏露草，理鬢回花面。","薄暮不同归，留情此芳甸。"]', '诗', 'shi', '', NULL, '雜曲歌辭 春遊樂二首 一 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0321b79-1e81-4776-8ef4-2f171d71e842', '雜曲歌辭 春遊樂二首 二', '杂曲歌辞 春游乐二首 二', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["柘彈連錢馬，銀鉤妥墮鬟。","采桑春陌上，踏草夕陽間。","意合辭先露，心誠貌卻閑。","明朝若相憶，雲雨出巫山。"]', '["柘彈連錢马，銀鉤妥墮鬟。","采桑春陌上，踏草夕陽间。","意合辞先露，心誠貌卻闲。","明朝若相憶，云雨出巫山。"]', '诗', 'shi', '', NULL, '雜曲歌辭 春遊樂二首 二 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a8f5fae-de21-42ba-b458-893eeffa3c54', '雜曲歌辭 春遊曲三首 一', '杂曲歌辞 春游曲三首 一', 'f841c0a4-cfe1-4d0b-a30c-6261191f82e2', '唐', '["煙柳飛輕絮，風榆落小錢。","濛濛百花裏，羅綺競鞦韆。"]', '["煙柳飞轻絮，风榆落小錢。","濛濛百花裏，羅綺競鞦韆。"]', '诗', 'shi', '', NULL, '雜曲歌辭 春遊曲三首 一 張仲素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30a09ffc-27bf-4fec-b22b-6e91f4dd8a0a', '雜曲歌辭 春遊曲三首 二', '杂曲歌辞 春游曲三首 二', 'f841c0a4-cfe1-4d0b-a30c-6261191f82e2', '唐', '["騁望登香閣，爭高下砌臺。","林間踏青去，席上意錢來。"]', '["騁望登香閣，爭高下砌台。","林间踏青去，席上意錢来。"]', '诗', 'shi', '', NULL, '雜曲歌辭 春遊曲三首 二 張仲素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47fc9ebc-0070-4a86-bf6c-63fe970ae534', '雜曲歌辭 春遊曲三首 三', '杂曲歌辞 春游曲三首 三', 'f841c0a4-cfe1-4d0b-a30c-6261191f82e2', '唐', '["行樂三春節，林花百和香。","當年重意氣，先占鬬雞場。"]', '["行乐三春節，林花百和香。","當年重意氣，先占鬬雞場。"]', '诗', 'shi', '', NULL, '雜曲歌辭 春遊曲三首 三 張仲素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8bc16df-4b48-40e4-b666-dbed47d9047c', '雜曲歌辭 樂府二首 一', '杂曲歌辞 乐府二首 一', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["花頷紅騣一向偏，綠槐香陌欲朝天。","仍嫌衆裏嬌行疾，傍鐙深藏白玉鞭。"]', '["花頷紅騣一向偏，綠槐香陌欲朝天。","仍嫌衆裏嬌行疾，傍鐙深藏白玉鞭。"]', '诗', 'shi', '', NULL, '雜曲歌辭 樂府二首 一 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac87576e-bb93-4ad0-86eb-b21f1cf7429b', '雜曲歌辭 樂府二首 二', '杂曲歌辞 乐府二首 二', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["噴珠團香小桂條，玉鞭兼賜霍嫖姚。","弄影便從天禁出，碧蹏聲碎五門橋。"]', '["噴珠團香小桂條，玉鞭兼賜霍嫖姚。","弄影便從天禁出，碧蹏声碎五门橋。"]', '诗', 'shi', '', NULL, '雜曲歌辭 樂府二首 二 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7307d6c8-62c3-4487-97d2-86e55dc12ebc', '雜曲歌辭 樂府', '杂曲歌辞 乐府', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["暖谷春光至，宸遊近甸榮。","雲隨天仗轉，風入御簾輕。","翠蓋浮佳氣，朱樓倚太清。","朝臣冠劒退，宮女管弦迎。","細草承雕輦，繁花入幔城。","文房開聖藻，武衛宿天營。","玉醴隨觴至，銅壺逐漏行。","五星含土德，萬姓徹中聲。","親祀先崇典，躬推示勸耕。","國風新正樂，農器近消兵。","道德關河固，刑章日月明。","野人同鳥獸，率舞感升平。"]', '["暖谷春光至，宸游近甸榮。","云隨天仗轉，风入御簾轻。","翠蓋浮佳氣，朱楼倚太清。","朝臣冠劒退，宮女管弦迎。","細草承雕輦，繁花入幔城。","文房开聖藻，武衛宿天營。","玉醴隨觴至，銅壺逐漏行。","五星含土德，万姓徹中声。","親祀先崇典，躬推示勸耕。","国风新正乐，農器近消兵。","道德关河固，刑章日月明。","野人同鸟獸，率舞感升平。"]', '诗', 'shi', '', NULL, '雜曲歌辭 樂府 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36efd4bc-6d4f-489a-9c9a-e333e18739af', '雜曲歌辭 樂府', '杂曲歌辞 乐府', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["光風澹蕩百花吐，樓上朝朝學歌舞。","身年二八壻侍中，幼妹承恩兄尚主。","綠窗珠箔繡鴛鴦，侍婢先焚百和香。","鶯嗁日出不知曙，寂寂羅幃春夢長。"]', '["光风澹蕩百花吐，楼上朝朝学歌舞。","身年二八壻侍中，幼妹承恩兄尚主。","綠窗珠箔繡鴛鴦，侍婢先焚百和香。","鶯嗁日出不知曙，寂寂羅幃春梦长。"]', '诗', 'shi', '', NULL, '雜曲歌辭 樂府 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf9e7e4a-227e-441a-865f-873ad8e957c5', '雜曲歌辭 樂府三首 一', '杂曲歌辞 乐府三首 一', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["蓮子不可得，荷花生水中。","猶勝道傍柳，無事蕩春風。"]', '["蓮子不可得，荷花生水中。","猶勝道傍柳，無事蕩春风。"]', '诗', 'shi', '', NULL, '雜曲歌辭 樂府三首 一 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b0061ae-a45e-43f3-9c20-aa221f18852f', '雜曲歌辭 樂府三首 二', '杂曲歌辞 乐府三首 二', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["淥萍與荷葉，同時一水中。","風吹荷葉在，淥萍西復東。"]', '["淥萍與荷葉，同时一水中。","风吹荷葉在，淥萍西复东。"]', '诗', 'shi', '', NULL, '雜曲歌辭 樂府三首 二 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a01640c4-01fc-44c4-bf10-f2a4b79a31e0', '雜曲歌辭 樂府三首 三', '杂曲歌辞 乐府三首 三', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["蓮花未開時，苦心終日卷。","春水徒蕩漾，荷花未開展。"]', '["蓮花未开时，苦心終日卷。","春水徒蕩漾，荷花未开展。"]', '诗', 'shi', '', NULL, '雜曲歌辭 樂府三首 三 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e23c4038-0674-4bc3-b6f6-051d116a6191', '雜曲歌辭 樂府', '杂曲歌辞 乐府', '53f77d71-48b8-4376-adc3-2a5e7143822d', '唐', '["芙蓉初出水，菡萏露中花。","風吹著枯木，無奈值空槎。"]', '["芙蓉初出水，菡萏露中花。","风吹著枯木，無奈值空槎。"]', '诗', 'shi', '', NULL, '雜曲歌辭 樂府 陸長源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('854b6573-38fc-4cfa-95a9-8f0f2b731d19', '雜曲歌辭 雜曲', '杂曲歌辞 杂曲', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["智瓊神女，來訪文君。","蛾眉始約，羅袖初薰。","歌齊曲韻，舞亂行分。","若向陽臺薦枕，何啻得勝朝雲。"]', '["智瓊神女，来訪文君。","蛾眉始約，羅袖初薰。","歌齊曲韻，舞亂行分。","若向陽台薦枕，何啻得勝朝云。"]', '诗', 'shi', '', NULL, '雜曲歌辭 雜曲 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dbfbde5-aa79-40ba-8a91-b22ee077a8e9', '雜曲歌辭 古曲五首 一', '杂曲歌辞 古曲五首 一', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["可憐江北女，慣唱江南曲。","搖蕩木蘭舟，雙鳧不成浴。"]', '["可怜江北女，慣唱江南曲。","搖蕩木蘭舟，雙鳧不成浴。"]', '诗', 'shi', '', NULL, '雜曲歌辭 古曲五首 一 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b77cfb9-d9f3-40ab-b94d-6d8f6d0d59f0', '雜曲歌辭 古曲五首 二', '杂曲歌辞 古曲五首 二', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["郎爲匕上香，妾爲籠上灰。","歸時雖暖熱，去罷生塵埃。"]', '["郎爲匕上香，妾爲籠上灰。","归时雖暖熱，去罷生塵埃。"]', '诗', 'shi', '', NULL, '雜曲歌辭 古曲五首 二 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7aae9190-ddaa-4148-a93e-f1a7d7b3bb7b', '雜曲歌辭 古曲五首 三', '杂曲歌辞 古曲五首 三', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["夜裁鴛鴦綺，朝織蒲桃綾。","欲試一寸心，待縫三尺冰。"]', '["夜裁鴛鴦綺，朝织蒲桃綾。","欲試一寸心，待縫三尺冰。"]', '诗', 'shi', '', NULL, '雜曲歌辭 古曲五首 三 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b94c5a1b-2074-41fd-8545-1527160fe131', '雜曲歌辭 古曲五首 四', '杂曲歌辞 古曲五首 四', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["憐時魚得水，怨罷商與參。","不如山支子，卻解結同心。"]', '["怜时鱼得水，怨罷商與參。","不如山支子，卻解結同心。"]', '诗', 'shi', '', NULL, '雜曲歌辭 古曲五首 四 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f566f5b-d74e-4b91-b7f6-31b49deff655', '雜曲歌辭 古曲五首 五', '杂曲歌辞 古曲五首 五', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["紅顏感暮花，白日同流水。","思君如孤燈，一夜一心死。"]', '["紅顏感暮花，白日同流水。","思君如孤灯，一夜一心死。"]', '诗', 'shi', '', NULL, '雜曲歌辭 古曲五首 五 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b05b8916-14f3-4727-9074-7a5191560361', '雜曲歌辭 高句麗', '杂曲歌辞 高句丽', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["金花折風帽，白馬小遲回。","翩翩舞廣袖，似鳥海東來。"]', '["金花折风帽，白马小遲回。","翩翩舞廣袖，似鸟海东来。"]', '诗', 'shi', '', NULL, '雜曲歌辭 高句麗 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47f20f9b-0dcc-4282-b429-c13d22f32f26', '雜曲歌辭 摩多樓子', '杂曲歌辞 摩多楼子', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["玉塞去金人，二萬四千里。","風吹沙作雲，一時渡遼水。","天白水如練，甲絲雙串斷。","行行莫苦辛，城月猶殘半。","曉氣朔煙上，趢趗胡馬蹏。","行人聽水別，隔隴長東西。"]', '["玉塞去金人，二万四千里。","风吹沙作云，一时渡遼水。","天白水如練，甲絲雙串斷。","行行莫苦辛，城月猶殘半。","晓氣朔煙上，趢趗胡马蹏。","行人听水別，隔隴长东西。"]', '诗', 'shi', '', NULL, '雜曲歌辭 摩多樓子 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9af7e0b-49ef-4661-bbd5-50358eb88ed7', '雜曲歌辭 遼東行', '杂曲歌辞 遼东行', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["遼東萬里遼水曲，古戍無城復無屋。","黃雲蓋地雪作山，不惜黃金買衣服。","戰回各自收弓箭，正西回面家鄉遠。","年年郡縣送征人，將與遼東作丘坂。","寧爲草木鄉中生，有身不向遼東行。"]', '["遼东万里遼水曲，古戍無城复無屋。","黄云蓋地雪作山，不惜黄金買衣服。","戰回各自收弓箭，正西回面家乡远。","年年郡縣送征人，將與遼东作丘坂。","寧爲草木乡中生，有身不向遼东行。"]', '诗', 'shi', '', NULL, '雜曲歌辭 遼東行 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebd43cac-8ec6-413b-a17a-120e02cebafa', '雜曲歌辭 渡遼水', '杂曲歌辞 渡遼水', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["渡遼水，此去咸陽五千里。","來時父母知隔生，重著衣裳如送死。","亦有白骨歸咸陽，營家各與題本鄉。","身在應無回渡日，駐馬相看遼水傍。"]', '["渡遼水，此去咸陽五千里。","来时父母知隔生，重著衣裳如送死。","亦有白骨归咸陽，營家各與題本乡。","身在應無回渡日，駐马相看遼水傍。"]', '诗', 'shi', '', NULL, '雜曲歌辭 渡遼水 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('238e54b0-be71-449d-8184-a084c2769f0a', '雜曲歌辭 昔昔鹽 垂柳覆金堤', '杂曲歌辞 昔昔鹽 垂柳覆金堤', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["新年垂柳色，嫋嫋對空閨。","不畏芳菲好，自緣離別嗁。","因風飄玉戶，向日映金堤。","驛使何時度？還將贈隴西。"]', '["新年垂柳色，嫋嫋对空閨。","不畏芳菲好，自緣離別嗁。","因风飄玉戶，向日映金堤。","驛使何时度？還將贈隴西。"]', '诗', 'shi', '', NULL, '雜曲歌辭 昔昔鹽 垂柳覆金堤 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50fa86ae-4358-4dac-bc7d-26a60929034f', '雜曲歌辭 昔昔鹽 蘼蕪葉復齊', '杂曲歌辞 昔昔鹽 蘼蕪葉复齊', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["提筐紅葉下，度日采蘼蕪。","掬翠香盈袖，看花憶故夫。","葉齊誰復見，風暖恨偏孤。","一被春光累，容顏與昔殊。"]', '["提筐紅葉下，度日采蘼蕪。","掬翠香盈袖，看花憶故夫。","葉齊誰复见，风暖恨偏孤。","一被春光累，容顏與昔殊。"]', '诗', 'shi', '', NULL, '雜曲歌辭 昔昔鹽 蘼蕪葉復齊 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18575058-f526-4248-a273-164a84618218', '雜曲歌辭 昔昔鹽 水溢芙蓉沼', '杂曲歌辞 昔昔鹽 水溢芙蓉沼', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["淥沼春光後，青青草色濃。","綺羅驚翡翠，暗粉妒芙蓉。","雲遍窗前見，荷翻鏡裏逢。","將心託流水，終日渺無從。"]', '["淥沼春光後，青青草色濃。","綺羅驚翡翠，暗粉妒芙蓉。","云遍窗前见，荷翻镜裏逢。","將心託流水，終日渺無從。"]', '诗', 'shi', '', NULL, '雜曲歌辭 昔昔鹽 水溢芙蓉沼 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc8adf47-d6ff-46f9-99a3-ee2833e075b7', '雜曲歌辭 昔昔鹽 花飛桃李蹊', '杂曲歌辞 昔昔鹽 花飞桃李蹊', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["遠期難可託，桃李自依依。","花徑無容跡，戎裘未下機。","隨風開又落，度日掃還飛。","欲折枝枝贈，那知歸不歸。"]', '["远期难可託，桃李自依依。","花徑無容跡，戎裘未下機。","隨风开又落，度日掃還飞。","欲折枝枝贈，那知归不归。"]', '诗', 'shi', '', NULL, '雜曲歌辭 昔昔鹽 花飛桃李蹊 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30f0ddbd-2f19-4dba-8a7a-79433098b5b6', '雜曲歌辭 昔昔鹽 采桑秦氏女', '杂曲歌辞 昔昔鹽 采桑秦氏女', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["南陌采桑出，誰知妾姓秦。","獨憐傾國貌，不負早鶯春。","珠履盪花溼，龍鉤折桂新。","使君那駐馬，自有侍中人。"]', '["南陌采桑出，誰知妾姓秦。","独怜傾国貌，不負早鶯春。","珠履盪花溼，龙鉤折桂新。","使君那駐马，自有侍中人。"]', '诗', 'shi', '', NULL, '雜曲歌辭 昔昔鹽 采桑秦氏女 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c24b1f64-0a19-417f-95a9-225b99c242db', '雜曲歌辭 昔昔鹽 織錦竇家妻', '杂曲歌辞 昔昔鹽 织錦竇家妻', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["當年誰不羨，分作竇家妻。","錦字行行苦，羅帷日日嗁。","豈知登隴遠，祗恨下機迷。","直候陽關使，殷勤寄海西。"]', '["當年誰不羨，分作竇家妻。","錦字行行苦，羅帷日日嗁。","豈知登隴远，祗恨下機迷。","直候陽关使，殷勤寄海西。"]', '诗', 'shi', '', NULL, '雜曲歌辭 昔昔鹽 織錦竇家妻 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8766a6c-a017-4b39-8765-0d5b57c668bf', '雜曲歌辭 昔昔鹽 關山別蕩子', '杂曲歌辞 昔昔鹽 关山別蕩子', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["那堪聞蕩子，迢遰涉關山。","腸爲馬嘶斷，衣從淚滴斑。","愁看塞上路，詎惜鏡中顏。","儻見征西鴈，應傳一字還。"]', '["那堪闻蕩子，迢遰涉关山。","腸爲马嘶斷，衣從泪滴斑。","愁看塞上路，詎惜镜中顏。","儻见征西鴈，應傳一字還。"]', '诗', 'shi', '', NULL, '雜曲歌辭 昔昔鹽 關山別蕩子 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e43db4ab-925d-4cb0-b14a-d105ef6cd63c', '雜曲歌辭 昔昔鹽 風月守空閨', '杂曲歌辞 昔昔鹽 风月守空閨', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["良人猶遠戍，耿耿夜閨空。","繡戶流宵月，羅帷坐曉風。","魂飛沙帳北，腸斷玉關中。","尚自無消息，錦衾那得同。"]', '["良人猶远戍，耿耿夜閨空。","繡戶流宵月，羅帷坐晓风。","魂飞沙帳北，腸斷玉关中。","尚自無消息，錦衾那得同。"]', '诗', 'shi', '', NULL, '雜曲歌辭 昔昔鹽 風月守空閨 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('988b8d28-4cf1-4f52-818d-78eae6fa546e', '雜曲歌辭 昔昔鹽 恆斂千金笑', '杂曲歌辞 昔昔鹽 恆斂千金笑', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["玉顏恆自斂，羞出鏡臺前。","早惑陽城客，今悲華錦筵。","從軍人更遠，投喜鵲空傳。","夫壻交河北，迢迢路幾千。"]', '["玉顏恆自斂，羞出镜台前。","早惑陽城客，今悲华錦筵。","從軍人更远，投喜鵲空傳。","夫壻交河北，迢迢路幾千。"]', '诗', 'shi', '', NULL, '雜曲歌辭 昔昔鹽 恆斂千金笑 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1fc2fbc-1dee-4646-a0f7-108ec7d40161', '雜曲歌辭 昔昔鹽 長垂雙玉嗁', '杂曲歌辞 昔昔鹽 长垂雙玉嗁', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["雙雙紅淚墮，度日暗中嗁。","鴈出居延北，人猶遼海西。","向燈垂玉枕，對月灑金閨。","不惜羅衣溼，惟愁歸意迷。"]', '["雙雙紅泪墮，度日暗中嗁。","鴈出居延北，人猶遼海西。","向灯垂玉枕，对月灑金閨。","不惜羅衣溼，惟愁归意迷。"]', '诗', 'shi', '', NULL, '雜曲歌辭 昔昔鹽 長垂雙玉嗁 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09651746-3fe6-4d53-a888-d3b865951982', '雜曲歌辭 昔昔鹽 蟠龍隨鏡隱', '杂曲歌辞 昔昔鹽 蟠龙隨镜隐', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["鸞鏡無由照，蛾眉豈忍看。","不知愁髮換，空見隱龍蟠。","那愜紅顏改，偏傷白日殘。","今朝窺玉匣，雙淚落闌干。"]', '["鸾镜無由照，蛾眉豈忍看。","不知愁髮換，空见隐龙蟠。","那愜紅顏改，偏傷白日殘。","今朝窺玉匣，雙泪落闌干。"]', '诗', 'shi', '', NULL, '雜曲歌辭 昔昔鹽 蟠龍隨鏡隱 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dea46cae-439c-45e6-ba22-06519ba0793f', '雜曲歌辭 昔昔鹽 綵鳳逐帷低', '杂曲歌辞 昔昔鹽 綵鳳逐帷低', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["巧繡雙飛鳳，朝朝伴下帷。","春花那見照，暮色已頻欺。","欲卷思君處，將嗁裛淚時。","何年征戍客？傳語報佳期。"]', '["巧繡雙飞鳳，朝朝伴下帷。","春花那见照，暮色已頻欺。","欲卷思君处，將嗁裛泪时。","何年征戍客？傳語報佳期。"]', '诗', 'shi', '', NULL, '雜曲歌辭 昔昔鹽 綵鳳逐帷低 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eebcac54-df54-47a7-9045-aaa691f418ab', '雜曲歌辭 昔昔鹽 驚魂同夜鵲', '杂曲歌辞 昔昔鹽 驚魂同夜鵲', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["萬里無人見，衆情難與論。","思君常入夢，同鵲屢驚魂。","孤寢紅羅帳，雙嗁玉筯痕。","妾心甘自保，豈復暫忘恩。"]', '["万里無人见，衆情难與論。","思君常入梦，同鵲屢驚魂。","孤寢紅羅帳，雙嗁玉筯痕。","妾心甘自保，豈复暫忘恩。"]', '诗', 'shi', '', NULL, '雜曲歌辭 昔昔鹽 驚魂同夜鵲 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49459ec1-5948-4b67-950c-339b4e058684', '雜曲歌辭 昔昔鹽 倦寢聽晨雞', '杂曲歌辞 昔昔鹽 倦寢听晨雞', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["去去邊城騎，愁眠掩夜閨。","披衣窺落月，拭淚待鳴雞。","不憤連年別，那堪長夜嗁。","功成應自恨，早晚發遼西。"]', '["去去邊城騎，愁眠掩夜閨。","披衣窺落月，拭泪待鳴雞。","不憤連年別，那堪长夜嗁。","功成應自恨，早晚發遼西。"]', '诗', 'shi', '', NULL, '雜曲歌辭 昔昔鹽 倦寢聽晨雞 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dadfdd07-52de-4eb0-b72a-e9f06a09e652', '雜曲歌辭 昔昔鹽 暗牖懸蛛網', '杂曲歌辞 昔昔鹽 暗牖懸蛛網', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["暗中蛛網織，歷亂綺窗前。","萬里終無信，一條徒自懸。","分從珠露滴，愁見隙風牽。","妾意何聊賴，看看劇斷弦。"]', '["暗中蛛網织，歷亂綺窗前。","万里終無信，一條徒自懸。","分從珠露滴，愁见隙风牽。","妾意何聊賴，看看劇斷弦。"]', '诗', 'shi', '', NULL, '雜曲歌辭 昔昔鹽 暗牖懸蛛網 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a06cb556-2b4d-4b1c-a52a-fcff10b7f87e', '雜曲歌辭 昔昔鹽 空梁落燕泥', '杂曲歌辞 昔昔鹽 空梁落燕泥', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["春至今朝燕，花時伴獨嗁。","飛斜珠箔隔，語近畫梁低。","帷卷閑窺戶，牀空暗落泥。","誰能長對此，雙去復雙棲。"]', '["春至今朝燕，花时伴独嗁。","飞斜珠箔隔，語近畫梁低。","帷卷闲窺戶，牀空暗落泥。","誰能长对此，雙去复雙棲。"]', '诗', 'shi', '', NULL, '雜曲歌辭 昔昔鹽 空梁落燕泥 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1de2239-e272-4be0-b710-ae16ece61789', '雜曲歌辭 昔昔鹽 前年過代北', '杂曲歌辞 昔昔鹽 前年過代北', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["代北幾千里，前年又復經。","燕山雲自合，胡塞草應青。","鐵馬喧鼙鼓，蛾眉怨錦屏。","不知羌笛曲，掩淚若爲聽。"]', '["代北幾千里，前年又复經。","燕山云自合，胡塞草應青。","鐵马喧鼙鼓，蛾眉怨錦屏。","不知羌笛曲，掩泪若爲听。"]', '诗', 'shi', '', NULL, '雜曲歌辭 昔昔鹽 前年過代北 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9a7c49b-cf3c-4469-936c-a23449959978', '雜曲歌辭 昔昔鹽 今歲往遼西', '杂曲歌辞 昔昔鹽 今歲往遼西', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["萬里飛書至，聞君已渡遼。","祗諳新別苦，忘卻舊時嬌。","烽戍年將老，紅顏日向彫。","胡沙兼漢苑，相望幾迢迢。"]', '["万里飞书至，闻君已渡遼。","祗諳新別苦，忘卻旧时嬌。","烽戍年將老，紅顏日向彫。","胡沙兼漢苑，相望幾迢迢。"]', '诗', 'shi', '', NULL, '雜曲歌辭 昔昔鹽 今歲往遼西 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f619ba03-5e1d-497e-af90-2367f48e9c01', '雜曲歌辭 昔昔鹽 一去無還意', '杂曲歌辞 昔昔鹽 一去無還意', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["良人征絕域，一去不言還。","百戰攻胡虜，三冬阻玉關。","蕭蕭邊馬思，獵獵戍旗閑。","獨把千重恨，連年未解顏。"]', '["良人征絕域，一去不言還。","百戰攻胡虜，三冬阻玉关。","蕭蕭邊马思，獵獵戍旗闲。","独把千重恨，連年未解顏。"]', '诗', 'shi', '', NULL, '雜曲歌辭 昔昔鹽 一去無還意 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c9c3d75-272f-4529-bf21-8aafbe5b276e', '雜曲歌辭 昔昔鹽 那能惜馬蹏', '杂曲歌辞 昔昔鹽 那能惜马蹏', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["雲中路杳杳，江畔草萋萋。","妾久垂珠淚，君何惜馬蹏。","邊風悲曉角，營月怨春鼙。","未道休征戰，愁眉又復低。"]', '["云中路杳杳，江畔草萋萋。","妾久垂珠泪，君何惜马蹏。","邊风悲晓角，營月怨春鼙。","未道休征戰，愁眉又复低。"]', '诗', 'shi', '', NULL, '雜曲歌辭 昔昔鹽 那能惜馬蹏 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('321a1b75-4cdf-48c7-8f57-047300fa7f50', '雜曲歌辭 水調 歌第一', '杂曲歌辞 水調 歌第一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["平沙落日大荒西，隴上明星高復低。","孤山幾處看烽火，壯士連營候鼓鼙。"]', '["平沙落日大荒西，隴上明星高复低。","孤山幾处看烽火，壯士連營候鼓鼙。"]', '诗', 'shi', '', NULL, '雜曲歌辭 水調 歌第一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('148561e3-75bd-49f3-a2ad-0f0a65e4ab18', '雜曲歌辭 水調 歌第二', '杂曲歌辞 水調 歌第二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["猛將關西意氣多，能騎駿馬弄琱戈。","金鞍寶鉸精神出，笛倚新翻水調歌。"]', '["猛將关西意氣多，能騎駿马弄琱戈。","金鞍寶鉸精神出，笛倚新翻水調歌。"]', '诗', 'shi', '', NULL, '雜曲歌辭 水調 歌第二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7f44dab-e6ec-46dc-8967-6c20743ca4f9', '雜曲歌辭 水調 歌第三', '杂曲歌辞 水調 歌第三', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["王孫別上綠珠輪，不羨名公樂此身。","戶外碧潭春洗馬，樓前紅燭夜迎人。"]', '["王孫別上綠珠輪，不羨名公乐此身。","戶外碧潭春洗马，楼前紅燭夜迎人。"]', '诗', 'shi', '', NULL, '雜曲歌辭 水調 歌第三 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0634a2b4-170c-4f89-8bc3-84cbe50dd49f', '雜曲歌辭 水調 歌第四', '杂曲歌辞 水調 歌第四', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["隴頭一叚氣長秋，舉目蕭條總是愁。","秖爲征人多下淚，年年添作斷腸流。"]', '["隴头一叚氣长秋，舉目蕭條總是愁。","秖爲征人多下泪，年年添作斷腸流。"]', '诗', 'shi', '', NULL, '雜曲歌辭 水調 歌第四 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99774e06-b675-4e90-812d-8687d5dec0cc', '雜曲歌辭 水調 歌第五', '杂曲歌辞 水調 歌第五', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["雙帶仍分影，同心巧結香。","不應須換彩，意欲媚濃妝。"]', '["雙带仍分影，同心巧結香。","不應須換彩，意欲媚濃妝。"]', '诗', 'shi', '', NULL, '雜曲歌辭 水調 歌第五 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c078e52-4245-4e6c-bdb6-f2ee4ea18b72', '雜曲歌辭 水調 入破第一', '杂曲歌辞 水調 入破第一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["細草河邊一鴈飛，黃龍關裏挂戎衣。","爲受明王恩寵甚，從事經年不復歸。"]', '["細草河邊一鴈飞，黄龙关裏挂戎衣。","爲受明王恩寵甚，從事經年不复归。"]', '诗', 'shi', '', NULL, '雜曲歌辭 水調 入破第一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a1b9edf-ca5a-4cd5-ae29-759a67fbaced', '雜曲歌辭 水調 入破第二', '杂曲歌辞 水調 入破第二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["錦城絲管日紛紛，半入江風半入雲。","此曲只應天上去，人間能得幾回聞。"]', '["錦城絲管日紛紛，半入江风半入云。","此曲只應天上去，人间能得幾回闻。"]', '诗', 'shi', '', NULL, '雜曲歌辭 水調 入破第二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfaf022d-6290-4edf-8d26-e6bb69a2e5e2', '雜曲歌辭 水調 入破第三', '杂曲歌辞 水調 入破第三', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["昨夜遙歡出建章，今朝綴賞度昭陽。","傳聲莫閉黃金屋，爲報先開白玉堂。"]', '["昨夜遙歡出建章，今朝綴賞度昭陽。","傳声莫閉黄金屋，爲報先开白玉堂。"]', '诗', 'shi', '', NULL, '雜曲歌辭 水調 入破第三 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('283d91c5-d4a9-4d74-8cde-151d413e4257', '雜曲歌辭 水調 入破第四', '杂曲歌辞 水調 入破第四', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["日晚笳聲咽戍樓，隴雲漫漫水東流。","行人萬里向西去，滿目關山空恨愁。"]', '["日晚笳声咽戍楼，隴云漫漫水东流。","行人万里向西去，满目关山空恨愁。"]', '诗', 'shi', '', NULL, '雜曲歌辭 水調 入破第四 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7ce62e6-0839-4be5-bb5a-2afa195d7b23', '雜曲歌辭 水調 入破第五', '杂曲歌辞 水調 入破第五', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["千年一遇聖明朝，願對君王舞細腰。","乍可當熊任生死，誰能伴鳳上雲霄。"]', '["千年一遇聖明朝，願对君王舞細腰。","乍可當熊任生死，誰能伴鳳上云霄。"]', '诗', 'shi', '', NULL, '雜曲歌辭 水調 入破第五 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fef5012-ce3c-4d1c-b10e-763f536f4d1f', '雜曲歌辭 水調 入破第六徹', '杂曲歌辞 水調 入破第六徹', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["閨燭無人影，羅屏有夢魂。","近來音耗絕，終日望君門。"]', '["閨燭無人影，羅屏有梦魂。","近来音耗絕，終日望君门。"]', '诗', 'shi', '', NULL, '雜曲歌辭 水調 入破第六徹 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da9d2ede-c1ae-4d70-ad8a-86a1c1cbaeab', '雜曲歌辭 水調', '杂曲歌辞 水調', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["鑿河千里走黃沙，浮殿西來動日華。","可道新聲是亡國，且貪惆悵後庭花。"]', '["鑿河千里走黄沙，浮殿西来动日华。","可道新声是亡国，且貪惆悵後庭花。"]', '诗', 'shi', '', NULL, '雜曲歌辭 水調 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee4f90a7-2e12-4406-9160-0ce744364e98', '雜曲歌辭 堂堂 一', '杂曲歌辞 堂堂 一', 'c5b421d5-4fcf-4983-afbc-50189c7a6749', '唐', '["鏤月成歌扇，裁雲作舞衣。","自憐回雪影，好取洛川歸。"]', '["鏤月成歌扇，裁云作舞衣。","自怜回雪影，好取洛川归。"]', '诗', 'shi', '', NULL, '雜曲歌辭 堂堂 一 李義府 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4443735c-8ed2-4f28-a04d-7b4e4b3f1005', '雜曲歌辭 堂堂 二', '杂曲歌辞 堂堂 二', 'c5b421d5-4fcf-4983-afbc-50189c7a6749', '唐', '["嬾正鴛鴦被，羞褰玳瑁牀。","春風別有意，密處也尋香。"]', '["嬾正鴛鴦被，羞褰玳瑁牀。","春风別有意，密处也尋香。"]', '诗', 'shi', '', NULL, '雜曲歌辭 堂堂 二 李義府 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c72218f8-026a-4393-9a75-141f2aa28294', '雜曲歌辭 堂堂', '杂曲歌辞 堂堂', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["堂堂復堂堂，紅脫梅灰香。","十年粉蠹生畫梁，飢蟲不食推碎黃。","蕙花已老桃葉長，禁院懸簾隔御光。","華清源中礜石湯，裴回百鳳隨君王。"]', '["堂堂复堂堂，紅脫梅灰香。","十年粉蠹生畫梁，飢蟲不食推碎黄。","蕙花已老桃葉长，禁院懸簾隔御光。","华清源中礜石湯，裴回百鳳隨君王。"]', '诗', 'shi', '', NULL, '雜曲歌辭 堂堂 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3517279-6e20-4847-a7a7-518aa6eb9eb3', '雜曲歌辭 涼州 歌第一', '杂曲歌辞 涼州 歌第一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["漢家宮裏柳如絲，上苑桃花連碧池。","聖壽已傳千歲酒，天文更賞百僚詩。"]', '["漢家宮裏柳如絲，上苑桃花連碧池。","聖壽已傳千歲酒，天文更賞百僚诗。"]', '诗', 'shi', '', NULL, '雜曲歌辭 涼州 歌第一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45c8fb06-8bc7-4f39-8874-9d6748c12fb9', '雜曲歌辭 涼州 歌第二', '杂曲歌辞 涼州 歌第二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["朔風吹葉鴈門秋，萬里煙塵昏戍樓。","征馬長思青海北，胡笳夜聽隴山頭。"]', '["朔风吹葉鴈门秋，万里煙塵昏戍楼。","征马长思青海北，胡笳夜听隴山头。"]', '诗', 'shi', '', NULL, '雜曲歌辭 涼州 歌第二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa89c7ac-8d34-4f99-9572-205ac0ed78b2', '雜曲歌辭 涼州 歌第三', '杂曲歌辞 涼州 歌第三', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["開篋淚霑襦，見君前日書。","夜臺空寂寞，猶見紫雲車。"]', '["开篋泪霑襦，见君前日书。","夜台空寂寞，猶见紫云车。"]', '诗', 'shi', '', NULL, '雜曲歌辭 涼州 歌第三 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03c22f95-a8cd-4b3b-81ad-48c2e94469dd', '雜曲歌辭 涼州 排遍第一', '杂曲歌辞 涼州 排遍第一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["三秋陌上早霜飛，羽獵平田淺草齊。","錦背蒼鷹初出按，五花驄馬餵來肥。"]', '["三秋陌上早霜飞，羽獵平田淺草齊。","錦背蒼鷹初出按，五花驄马餵来肥。"]', '诗', 'shi', '', NULL, '雜曲歌辭 涼州 排遍第一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f7a578f-f6da-4dee-a195-938e2aeddb99', '雜曲歌辭 涼州 排遍第二', '杂曲歌辞 涼州 排遍第二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["鴛鴦殿裏笙歌起，翡翠樓前出舞人。","喚上紫微三五夕，聖明方壽一千春。"]', '["鴛鴦殿裏笙歌起，翡翠楼前出舞人。","喚上紫微三五夕，聖明方壽一千春。"]', '诗', 'shi', '', NULL, '雜曲歌辭 涼州 排遍第二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13d01f32-e7b8-4ba4-a834-5cbd2174970f', '雜曲歌辭 涼州詞', '杂曲歌辞 涼州词', '7c891598-5c2d-4135-b2cd-60fcb5f29523', '唐', '["國使翩翩隨斾旌，隴西岐路足荒城。","氈裘牧馬胡雛小，日暮蕃歌三兩聲。"]', '["国使翩翩隨斾旌，隴西岐路足荒城。","氈裘牧马胡雛小，日暮蕃歌三兩声。"]', '诗', 'shi', '', NULL, '雜曲歌辭 涼州詞 耿[湋] shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea4f6277-8e73-4d23-b500-dd995005322a', '雜曲歌辭 涼州詞 一', '杂曲歌辞 涼州词 一', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["邊城暮雨鴈飛低，蘆筍初生漸欲齊。","無數鈴聲遙過磧，應馱白練到安西。"]', '["邊城暮雨鴈飞低，蘆筍初生漸欲齊。","無數鈴声遙過磧，應馱白練到安西。"]', '诗', 'shi', '', NULL, '雜曲歌辭 涼州詞 一 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8284624-2472-47b7-ab3f-0bc99f42df81', '雜曲歌辭 涼州詞 二', '杂曲歌辞 涼州词 二', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["古鎮城門白磧開，胡兵往往傍沙堆。","巡邊使客行應早，每待平安火到來。"]', '["古鎮城门白磧开，胡兵往往傍沙堆。","巡邊使客行應早，每待平安火到来。"]', '诗', 'shi', '', NULL, '雜曲歌辭 涼州詞 二 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d93b8fa9-665b-4e61-a353-a15d869d8c92', '雜曲歌辭 涼州詞 三', '杂曲歌辞 涼州词 三', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["鳳林關裏水東流，白草黃榆六十秋。","邊將皆承主恩澤，無人解道取涼州。"]', '["鳳林关裏水东流，白草黄榆六十秋。","邊將皆承主恩澤，無人解道取涼州。"]', '诗', 'shi', '', NULL, '雜曲歌辭 涼州詞 三 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f44618a-ec8e-40e0-bbfd-7cefa27e61d2', '雜曲歌辭 涼州詞', '杂曲歌辞 涼州词', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["昨夜蕃兵報國讐，沙州都護破涼州。","黃河九曲今歸漢，塞外縱橫戰血流。"]', '["昨夜蕃兵報国讐，沙州都護破涼州。","黄河九曲今归漢，塞外縱橫戰血流。"]', '诗', 'shi', '', NULL, '雜曲歌辭 涼州詞 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('198b8237-295c-41ac-a4b0-49d3761a85b7', '雜曲歌辭 太和 第一', '杂曲歌辞 太和 第一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["國門卿相舊山莊，聖主移來宴綠芳。","簾外輾爲車馬路，花間踏出舞人場。"]', '["国门卿相旧山莊，聖主移来宴綠芳。","簾外輾爲车马路，花间踏出舞人場。"]', '诗', 'shi', '', NULL, '雜曲歌辭 太和 第一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a16801c-b035-4c76-b485-2e02c736e508', '雜曲歌辭 太和 第二', '杂曲歌辞 太和 第二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["國鳥尚含天樂轉，寒風猶帶御衣香。","爲報碧潭明月夜，會須留賞待君王。"]', '["国鸟尚含天乐轉，寒风猶带御衣香。","爲報碧潭明月夜，會須留賞待君王。"]', '诗', 'shi', '', NULL, '雜曲歌辭 太和 第二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5a61d09-e847-43a2-8ff4-45b37ca64d90', '雜曲歌辭 太和 第三', '杂曲歌辞 太和 第三', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["庭前鵲遶相思樹，井上鶯歌爭刺桐。","含情少婦悲春草，多是良人學轉蓬。"]', '["庭前鵲遶相思樹，井上鶯歌爭刺桐。","含情少婦悲春草，多是良人学轉蓬。"]', '诗', 'shi', '', NULL, '雜曲歌辭 太和 第三 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51b62ef0-7fba-42f9-9560-945a0d15e2b8', '雜曲歌辭 太和 第四', '杂曲歌辞 太和 第四', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["塞北江南共一家，何須淚落怨黃沙。","春酒半酣千日醉，庭前還有落梅花。"]', '["塞北江南共一家，何須泪落怨黄沙。","春酒半酣千日醉，庭前還有落梅花。"]', '诗', 'shi', '', NULL, '雜曲歌辭 太和 第四 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53e0450d-1e04-4909-a384-c6c9b6f17e5a', '雜曲歌辭 太和 第五徹', '杂曲歌辞 太和 第五徹', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["我皇膺運太平年，四海朝宗會百川。","自古幾多明聖主，不如今帝勝堯天。"]', '["我皇膺運太平年，四海朝宗會百川。","自古幾多明聖主，不如今帝勝堯天。"]', '诗', 'shi', '', NULL, '雜曲歌辭 太和 第五徹 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14473112-f820-431f-b353-a013af09dede', '雜曲歌辭 伊州 歌第一', '杂曲歌辞 伊州 歌第一', '8544146d-bf03-4fff-bd85-b31012073164', '唐', '["秋風明月獨離居，蕩子從戎十載餘。","征人去日殷勤屬，歸鴈來時數寄書。"]', '["秋风明月独離居，蕩子從戎十載餘。","征人去日殷勤屬，归鴈来时數寄书。"]', '诗', 'shi', '', NULL, '雜曲歌辭 伊州 歌第一 蓋嘉運 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d12a1587-2ddf-4162-86a9-f8f208371f9e', '雜曲歌辭 伊州 歌第二', '杂曲歌辞 伊州 歌第二', '8544146d-bf03-4fff-bd85-b31012073164', '唐', '["彤闈曉闢萬鞍迴，玉輅春遊薄晚開。","渭北清光搖草樹，州南嘉景入樓臺。"]', '["彤闈晓闢万鞍迴，玉輅春游薄晚开。","渭北清光搖草樹，州南嘉景入楼台。"]', '诗', 'shi', '', NULL, '雜曲歌辭 伊州 歌第二 蓋嘉運 shi');
